window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[27]={"id":"027","numero":27,"titre":"Prévention risques fœtaux","objectifs":[{"id":"27-1","rang":"B","rubrique":"Définition","titre":"Connaître la définition de l'infection materno-fœtale (IMF)","contenu":"<div class=\"notion-course\"><p>L'<span>infection materno-fœtale (IMF)</span> est une infection contractée par le fœtus ou le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> à partir de germes d'origine maternelle, transmise au cours de la <span><span class=\"nc-green_bg\">grossesse</span></span>, à l'accouchement ou en post-partum immédiat.</p>\n      <table>\n        <thead><tr><th>Période</th><th>Mode</th><th>Conséquences possibles</th></tr></thead>\n        <tbody>\n          <tr><td>Anténatale</td><td>Passage transplacentaire hématogène</td><td><span><span class=\"nc-red_bg\">Embryopathie</span></span>, fœtopathie, <span>MFIU</span>, <span class=\"nc-red nc-bold\">fausse couche</span></td></tr>\n          <tr><td>Per-partum</td><td>Voie ascendante (filière génitale) ou contact direct</td><td><span class=\"nc-red\">Chorioamniotite</span>, <span class=\"nc-red_bg\">accouchement prématuré</span>, <span class=\"nc-red_bg\">infection néonatale</span> précoce</td></tr>\n          <tr><td>Post-natale</td><td><span>Allaitement</span>, contact</td><td><span class=\"nc-red_bg\">Infection néonatale</span> tardive (symptomatique d'emblée ou à distance)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Fréquence :</strong> <span><span class=\"nc-pink nc-bold\">1 à 4 %</span></span> des naissances toutes infections confondues, <span>2 à 4 ×</span> plus chez les prématurés.</div>\n      <p>Toute infection fébrile chez la femme enceinte peut, de façon non spécifique, être responsable d'une <span><span class=\"nc-red nc-bold\">fausse couche</span> spontanée</span>, même sans atteinte directe du tissu embryonnaire.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie \"microbienne\" des IMF","contenu":"<div class=\"notion-course\"><p>Les germes responsables d'IMF se répartissent en <span <span=\"\">&gt;3</span> grandes familles. Le profil microbien dépend de la voie de contamination.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Germes principaux</th><th>Voie dominante</th></tr></thead>\n        <tbody>\n          <tr><td>Bactéries</td><td><span>Listeria monocytogenes</span>, <span><span class=\"nc-purple_bg\">Streptococcus agalactiae</span></span> (SGB), <span>Escherichia coli</span>, <span>syphilis</span>, <span>tuberculose</span>, <span>fièvre</span> Q</td><td>Hématogène (<span>Listeria</span>) · ascendante (SGB, <span>E. coli</span>) · transplacentaire (<span>syphilis</span>)</td></tr>\n          <tr><td>Parasites</td><td><span>Toxoplasma gondii</span>, paludisme</td><td>Hématogène transplacentaire</td></tr>\n          <tr><td>Virus</td><td><span>Grippe</span>, <span>hépatite</span> B, <span>HSV</span>, varicelle, rubéole, CMV, VIH, parvovirus B19, Zika</td><td>Hématogène (rubéole, <span>CMV</span>, parvo, toxo, VIH) · per-partum (HSV, VHB, VIH)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span> · 162 — IST · 167 — Hépatites virales · 168 — Herpesvirus · 169 — <span>VIH</span> · 170 — Paludisme · 173 — Zoonose</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":2},{"id":"27-3","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes des IMF","contenu":"<div class=\"notion-course\"><p>Trois voies de contamination structurent la <span>physiopathologie</span> des IMF — le piège QCM est de relier la voie au germe et à la conséquence attendue.</p>\n      <table>\n        <thead><tr><th>Voie</th><th>Mécanisme</th><th>Germes typiques</th><th>Conséquences ⚠️</th></tr></thead>\n        <tbody>\n          <tr><td>Hématogène <span class=\"nc-orange_bg\">transplacentaire</span></td><td>Bactériémie/virémie maternelle → passage placentaire</td><td><span>Listeria</span>, <span>CMV</span>, rubéole, toxo, parvovirus B19, <span>syphilis</span></td><td><span>Atteinte fœtale</span> (embryo/fœtopathie)</td></tr>\n          <tr><td>Ascendante cervico-vaginale</td><td>Germes de la filière génitale → membranes</td><td>SGB, <span>E. coli</span>, <span>vaginose</span></td><td><span><span class=\"nc-orange_bg\">MAP</span></span>, <span class=\"nc-orange_bg\">chorioamniotite</span>, <span class=\"nc-red nc-bold\">fausse couche</span> tardive</td></tr>\n          <tr><td>Per-partum / post-natale</td><td>Contact filière génitale ou <span><span class=\"nc-brown_bg\">allaitement</span></span></td><td>SGB, <span>HSV</span>, VHB, VIH, CMV</td><td><span class=\"nc-red_bg\">Infection néonatale</span> précoce ou tardive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège QCM :</strong> distinguer la <span>fenêtre embryonnaire</span> (<span>J0</span>–J56, organogenèse, malformations structurelles) de la <span>fenêtre fœtale</span> (&gt; J56, atteinte fonctionnelle et croissance). L'évocation devant un point d'appel maternel (<span>fièvre</span>) <em>ou</em> fœtal (signe échographique, altération du bien-être) est <span class=\"nc-red nc-bold\">obligatoire</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span> · 162 — IST</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":2},{"id":"27-4","rang":"A","rubrique":"Définition","titre":"Toxoplasmose : connaître les conséquences de l'IMF","contenu":"<div class=\"notion-course\"><p>La toxoplasmose <span>congénitale</span> résulte de la <span><span class=\"nc-red nc-bold\">primo-infection</span> maternelle</span> pendant la <span><span class=\"nc-green_bg\">grossesse</span></span> (<span>1-2 %</span> des grossesses, 4000-5000 femmes/an en France).</p>\n      <table>\n        <thead><tr><th>Période</th><th>Risque transmission</th><th>Sévérité fœtale</th></tr></thead>\n        <tbody>\n          <tr><td>Périconceptionnelle (0-7 SA)</td><td><span>1 %</span></td><td>Embryopathie/fœtopathie sévère <span>60 %</span> (avortement, MFIU)</td></tr>\n          <tr><td>Jusqu'à 13 SA</td><td><span>5 %</span></td><td>Lésions sévères</td></tr>\n          <tr><td>2ᵉ trimestre</td><td><span>40 %</span></td><td>Fœtopathie ou forme infraclinique <span>25 %</span></td></tr>\n          <tr><td>3ᵉ trimestre</td><td><span>70 %</span></td><td><span class=\"nc-blue_bg\">Formes sérologiques pures</span> ou choriorétinite <span>9 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations chez l'enfant contaminé :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-green_bg\">Atteinte infraclinique</span></span> :<span> 70 %</span></li>\n        <li><span><span class=\"nc-green_bg\">Forme légère</span></span> :<span> 25 %</span></li>\n        <li><span>Forme grave</span> (&lt; 5 %) : <span><span class=\"nc-red nc-bold\">microcéphalie</span></span>, <span><span class=\"nc-red nc-bold\">hydrocéphalie</span></span>, <span><span class=\"nc-red nc-bold\">calcifications intracrâniennes</span></span>, <span>choriorétinite</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Paradoxe à retenir :</strong> le <span class=\"nc-yellow_bg\">risque de transmission augmente avec le terme</span>, mais la sévérité décroît — l'infection T1 est rare mais dévastatrice, l'infection T3 est fréquente mais souvent infraclinique.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-5","rang":"A","rubrique":"Prise en charge","titre":"Toxoplasmose : connaître les modalités de surveillance d'une femme enceinte séronégative pour la toxoplasmose","contenu":"<div class=\"notion-course\"><p>La <span>sérologie toxoplasmose</span> est <strong><span class=\"nc-red nc-bold\">obligatoire</span> au 1ᵉʳ trimestre</strong> (1ʳᵉ consultation) chez toute femme enceinte. <span>45-50 %</span> des femmes enceintes en France sont séronégatives.</p>\n      <table>\n        <thead><tr><th>Statut</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Femme immune (IgG+)</td><td>Aucune <span>surveillance</span>, aucune précaution</td></tr>\n          <tr><td>Femme non-immune</td><td><strong><span>Prévention primaire</span></strong> (conseils alimentaires/chats — voir obj-5) + <strong><span>prévention secondaire</span> <span class=\"nc-red nc-bold\">obligatoire</span></strong> : <span>sérologie mensuelle</span> (IgM, IgG) jusqu'à 3 sem après l'accouchement</td></tr>\n        </tbody>\n      </table>\n      <p><strong>CAT en cas de séroconversion :</strong></p>\n      <ul>\n        <li>Orientation <span>CPDPN</span> (Centre Pluridisciplinaire de Diagnostic Prénatal)</li>\n        <li><span class=\"nc-pink_bg\">Traitement précoce par</span> <span><span class=\"nc-pink_bg nc-bold\">spiramycine</span></span> <span>9 MUI/j</span> (prophylactique, diminue le risque de transmission, bien toléré)</li>\n        <li><span><span class=\"nc-blue_bg\">PCR sur amniocentèse</span></span> à partir de <span><span class=\"nc-pink nc-bold\">≥ 16</span></span><span class=\"nc-pink nc-bold\">-18 SA</span>, réalisée ≥ <span><span class=\"nc-pink nc-bold\">4 semaines</span></span><span class=\"nc-pink nc-bold\"> après la date d'infection maternelle</span></li>\n        <li>Si <span>PCR</span> + : relais par <span><span class=\"nc-pink_bg\">pyriméthamine + sulfadiazine + acide folinique</span></span> <span class=\"nc-pink_bg nc-bold\">jusqu'à l'accouchement</span></li>\n        <li>Échographies <span>mensuelles</span> ciblées (recherche dilatation ventriculaire, <span class=\"nc-red nc-bold\">hydrocéphalie</span>, calcifications intra-crâniennes)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Pas de vaccin :</strong> il n'existe pas de vaccin contre la toxoplasmose.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/27/serologie-toxoplasmose-interpretation.png\" alt=\"Algorithme HAS d&#x27;interprétation d&#x27;une sérologie toxoplasmose positive chez la femme enceinte selon les profils IgG/IgM et l&#x27;indice d&#x27;avidité\" loading=\"lazy\">\n        <figcaption>Interprétation d'une <span>sérologie</span> toxoplasmose positive (rang C) — décision selon IgG, IgM et indice d'avidité IgG. Source : fiche source EDN item 27 — Infections et <span>grossesse</span>.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-6","rang":"A","rubrique":"Prise en charge","titre":"Toxoplasmose : connaître les principaux conseils de prévention de la toxoplasmose","contenu":"<div class=\"notion-course\"><p>Chez la femme enceinte <strong>séronégative</strong>, les <span class=\"nc-green_bg\">conseils de </span><span><span class=\"nc-green_bg\">prévention</span> primaire</span> sont remis par écrit dès le 1ᵉʳ trimestre.</p>\n      <ul>\n        <li><span>Viande bien cuite</span> (<span>≥ 67-72 °C</span> à cœur) ou congelée (-<span <span=\"\">&gt;18</span> °C) ; éviter charcuterie crue (jambon cru, saucisson, viande fumée)</li>\n        <li><span>Laver soigneusement</span> fruits, légumes, herbes aromatiques (terre potentiellement contaminée)</li>\n        <li>Éviter le <span>contact avec la litière des chats</span> ; si inévitable : <span>port de gants</span> + désinfection à l'eau bouillante quotidienne</li>\n        <li><span>Lavage des mains</span> systématique après jardinage, manipulation de terre, manipulation de viande crue</li>\n        <li>Éviter <span class=\"nc-red_bg\">coquillages crus</span>, <span class=\"nc-red_bg\">surimi</span>, <span class=\"nc-red_bg\">tarama</span></li>\n        <li>Conserver aliments crus séparés des aliments cuits/prêts à consommer</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong><span>Activité physique adaptée</span> :</strong><span> <span class=\"nc-pink nc-bold\">30 min</span></span>, 3 à 5 ×/semaine — recommandation HAS.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 24 — Complications de la grossesse · 173 — Zoonose</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":2},{"id":"27-7","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences d'une rubéole au cours de la grossesse","contenu":"<div class=\"notion-course\"><p>La rubéole maternelle est <strong>grave</strong> chez la <span class=\"nc-orange nc-bold\">femme enceinte non immunisée</span> — le virus est <span><span class=\"nc-red nc-bold\">tératogène</span></span>. <span><span class=\"nc-pink_bg\">5-10 %</span></span><span class=\"nc-pink_bg\"> des femmes enceintes</span> ne sont <span class=\"nc-pink_bg\">pas immunisées</span> en France (<span class=\"nc-pink nc-bold\">&lt; 40 cas/an</span>).</p>\n      <table>\n        <thead><tr><th>Âge gestationnel</th><th>Risque de malformation</th></tr></thead>\n        <tbody>\n          <tr><td>0-8 SA</td><td><span>85 %</span></td></tr>\n          <tr><td>9-12 SA</td><td><span>52 %</span></td></tr>\n          <tr><td>13-20 SA</td><td><span>16 %</span></td></tr>\n          <tr><td><span>&gt; 20</span> SA</td><td><span>0 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 tableaux cliniques (rubéole <span>congénitale</span>) :</strong></p>\n      <ul>\n        <li><span>Syndrome malformatif (triade de Gregg)</span> : <span><span class=\"nc-red_bg\">RCIU</span></span>, MFIU, FCS ; atteinte neurosensorielle (<span><span class=\"nc-red_bg\">surdité</span></span>, <span class=\"nc-red_bg\">microcéphalie</span>, <span class=\"nc-red_bg\">retard psychomoteur</span>) ; atteinte cardiaque (<span>CIV, CIA, PCA</span>, sténose artère pulmonaire) ; atteinte oculaire (<span><span class=\"nc-orange_bg\">cataracte</span></span>, <span class=\"nc-orange_bg\">microphtalmie</span>, <span class=\"nc-orange_bg\">rétinopathie pigmentaire</span>, <span class=\"nc-orange_bg\">glaucome</span>)</li>\n        <li><span>Rubéole congénitale évolutive</span> : infection chronique persistante (nouveau-né très contagieux) — <span class=\"nc-red nc-bold\">RCIU</span>, <span><span class=\"nc-orange nc-bold\">purpura</span></span><span class=\"nc-orange nc-bold\"> thrombopénique</span>, <span>hépatosplénomégalie</span>, <span><span class=\"nc-blue_bg\">ictère</span></span>, <span><span class=\"nc-orange nc-bold\">convulsions</span></span>, <span class=\"nc-blue_bg nc-bold\">anomalies osseuses</span> <span class=\"nc-blue_bg\">radiologiques</span> ; <span>pronostic</span> psychomoteur réservé</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-8","rang":"A","rubrique":"Prise en charge","titre":"Rubéole : connaître les éléments de la prévention fœtale","contenu":"<div class=\"notion-course\"><p>La prévention de la rubéole <span>congénitale</span> repose sur deux axes complémentaires — primaire (vaccination) et secondaire (<span><span class=\"nc-blue_bg\">dépistage</span></span> sérologique).</p>\n      <table>\n        <thead><tr><th>Type</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Prévention primaire</span></strong></td><td><span>Vaccination ROR</span> des femmes non immunisées <strong>en âge de procréer</strong> ; vaccination des enfants (calendrier vaccinal) ; femme enceinte séronégative vaccinée en <strong>post-partum</strong> (vaccin vivant atténué <span>CI pendant la grossesse</span>)</td></tr>\n          <tr><td><strong><span>Prévention secondaire</span></strong></td><td><span>Sérologie IgG</span> <span class=\"nc-red nc-bold\">obligatoire</span> à la 1ʳᵉ consultation (sauf immunité antérieure documentée) ; si négative : contrôle <strong>mensuel jusqu'à <span class=\"nc-pink nc-bold\">18-20 SA</span></strong> (au-delà, risque très faible)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>CAT séroconversion T1 :</strong> avis CPDPN — <span><span class=\"nc-pink nc-bold\">autorisation d'IMG possible</span></span> si demande du couple. Si refus <span class=\"nc-pink nc-bold\">IMG</span> : diagnostic anténatal par <span>amniocentèse</span> (<span><span class=\"nc-pink nc-bold\">≥ 18</span></span><span class=\"nc-pink nc-bold\"> SA</span> et ≥ 4 sem <span class=\"nc-pink nc-bold\">après</span> séroconversion) + <span><span class=\"nc-blue nc-bold\">surveillance</span></span><span class=\"nc-blue nc-bold\"> échographique</span> mensuelle. <strong>Pas de <span class=\"nc-yellow_bg\">traitement curatif</span> disponible.</strong></div>\n      <p>Délai de contraception après vaccin ROR : <span>≥ 1 mois</span> (vaccin vivant).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-9","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la rougeole materno-fœtale","contenu":"<div class=\"notion-course\"><p>La <span>rougeole materno-fœtale</span> désigne l'infection rougeoleuse contractée par la femme enceinte avec possible transmission au fœtus ou au <span class=\"nc-blue_bg nc-bold\">nouveau-né</span>. La rougeole est rare pendant la <span><span class=\"nc-green_bg\">grossesse</span></span> mais grave.</p>\n      <table>\n        <thead><tr><th>Mode</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Transmission placentaire</td><td>Passage hématogène transplacentaire</td></tr>\n          <tr><td>Transmission néonatale précoce</td><td>Voie aérienne en per-partum / post-natal immédiat</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pas d'effet <span><span class=\"nc-red nc-bold\">tératogène</span></span> :</strong> contrairement à la rubéole, la rougeole <span>n'est pas associée à un syndrome polymalformatif</span>. Le risque est obstétrical (FCS, <span class=\"nc-red nc-bold\">prématurité</span>) et néonatal (rougeole <span>congénitale</span>).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-10","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences d'une rougeole au cours de la grossesse","contenu":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Versant</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td>Rougeole maternelle</td><td><span><span class=\"nc-red nc-bold\">Pneumonie</span></span> par surinfection <span>bactérienne</span> (forme + grave durant la <span>grossesse</span>) ; <span><span class=\"nc-red nc-bold\">fausse couche</span></span>, <span><span class=\"nc-red nc-bold\">prématurité</span></span> (comme tout syndrome fébrile)</td></tr>\n          <tr><td>Rougeole <span>congénitale</span> ou périnatale</td><td>Risque maximal si <span>éruption</span> maternelle dans les <strong><span class=\"nc-pink nc-bold\">&lt; 10 jours précédant l'accouchement</span></strong> ; <span>éruption</span> néonatale dans les <span class=\"nc-blue_bg nc-bold\">10 premiers jours de vie</span> ; <span>mortalité</span> néonatale historiquement élevée ; risque accru de <span>panencéphalite subaiguë sclérosante (Van Bogaert)</span> précoce (&lt; 2 ans) et fulminante ⚠️</td></tr>\n          <tr><td>Rougeole post-natale</td><td><span>Éruption</span> entre J14 et J30 post-natal ; plus rare, généralement <span class=\"nc-green_bg\">moins grave</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pas de malformation <span>congénitale</span> :</strong> <span class=\"nc-green_bg\">absence d'effet </span><span><span class=\"nc-green_bg\">tératogène</span></span> — le <span>pronostic</span> est dominé par le risque maternel (pneumopathie) et néonatal (rougeole congénitale).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-11","rang":"A","rubrique":"Prise en charge","titre":"Rougeole : Connaître les éléments de prévention fœtale","contenu":"<div class=\"notion-course\"><ul>\n        <li><strong><span>Prévention primaire</span></strong> : amélioration de la <span>couverture vaccinale ROR</span> avant <span><span class=\"nc-green_bg\">grossesse</span></span> (vaccin vivant atténué, <span>CI pendant la <span class=\"nc-green_bg\">grossesse</span></span>) — couverture actuelle insuffisante pour éradiquer le virus</li>\n        <li><strong>CAT en cas de contage chez femme enceinte non immune</strong> : <span><span class=\"nc-pink_bg\">immunoglobulines polyvalentes IV</span></span>, efficaces dans les <strong><span>6 jours</span> suivant le contage</strong></li>\n        <li><strong>Si <span>éruption</span> maternelle &lt; 10 j <span class=\"nc-pink_bg nc-bold\">avant</span> accouchement</strong> : Ig polyvalentes IV chez le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> <strong><span class=\"nc-pink nc-bold\">dès la naissance</span></strong> (prévention de la rougeole <span>congénitale</span> et de ses complications)</li>\n        <li><strong>Inutile</strong> si <span>éruption</span> maternelle &gt; 10 j avant accouchement (collège de gynéco)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-12","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'infection à Cytomégalovirus (CMV) materno-fœtale","contenu":"<div class=\"notion-course\"><ul><li>Le CMV peut être transmis au fœtus <span class=\"nc-pink nc-bold\">après</span> <span class=\"nc-red nc-bold\">primo-infection</span> mais aussi <span class=\"nc-pink nc-bold\">après</span> infection maternelle non primaire. La transmission augmente avec le terme ; les atteintes sévères sont surtout liées aux infections précoces. Une séropositivité ancienne ne garantit pas une protection absolue.</li><li>Atteintes possibles : <span class=\"nc-red_bg\">surdité</span> neurosensorielle, anomalies cérébrales et neurodéveloppementales, <span class=\"nc-red nc-bold\">retard de croissance</span> et atteintes viscérales. Une échographie normale ne permet pas d’exclure toute séquelle.</li><li><b>Évolution du référentiel :</b> la HAS recommande depuis 2025 un <span class=\"nc-blue_bg\">dépistage</span> systématiquement proposé au premier trimestre, avec modalités précisées en 2026. Sérologie précoce ; si négative, renouvellement toutes les quatre semaines avec dernier contrôle entre 13+0 et 14+0 SA.</li><li>Une IgM positive isolée ne date pas l’infection : interprétation experte des IgG/IgM, avidité et résultats antérieurs. Une <span class=\"nc-red nc-bold\">primo-infection</span> récente conduit rapidement à un avis spécialisé/CPDPN, une information sur les incertitudes et la discussion d’un <span class=\"nc-pink_bg\">traitement précoce par</span> valaciclovir et du diagnostic fœtal.</li><li>Prévention pour toutes : lavage des mains après contact avec sécrétions d’un jeune enfant, ne pas partager couverts/verres et éviter les baisers sur la bouche. Ce conseil reste utile quel que soit le statut sérologique.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-13","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de transmission materno-fœtale des virus les plus fréquemment impliqués","contenu":"<div class=\"notion-course\"><p>Le mécanisme de transmission <span>virale</span> dépend du virus et conditionne la période à risque + la stratégie préventive.</p>\n      <table>\n        <thead><tr><th>Virus</th><th>Voie principale</th><th>Période à risque</th></tr></thead>\n        <tbody>\n          <tr><td><span>CMV</span></td><td>Hématogène <span class=\"nc-orange_bg\">transplacentaire</span></td><td>Risque de séquelles surtout lié aux infections précoces ; ne pas assimiler une infection plus tardive à une absence absolue de risque.</td></tr>\n          <tr><td>Rubéole</td><td>Hématogène transplacentaire</td><td>&lt; 18-20 SA (<span>tératogène</span>)</td></tr>\n          <tr><td>Parvovirus B19</td><td>Hématogène <span class=\"nc-orange_bg\">transplacentaire</span></td><td>T1-T2 (<span class=\"nc-red_bg\">anémie</span> fœtale, anasarque)</td></tr>\n          <tr><td><span>VZV</span></td><td>Hématogène + per-partum</td><td>&lt; 20 SA (embryofœtopathie) ; 5 j avant à 2 j après accouchement (<span>varicelle néonatale grave</span>)</td></tr>\n          <tr><td><span>HSV</span></td><td>Per-partum +++</td><td><span class=\"nc-red nc-bold\">Primo-infection</span> T3 (transmission <span>50 %</span>)</td></tr>\n          <tr><td><span>VHB</span></td><td>Per-partum (<span>90 %</span>) &gt; <span class=\"nc-brown_bg\">transplacentaire</span></td><td>Accouchement</td></tr>\n          <tr><td><span>VIH</span></td><td><span class=\"nc-brown_bg\">Per-partum</span> (<span>20 %</span>), <span class=\"nc-brown_bg\">transplacentaire</span> (<span>6 %</span>), <span><span class=\"nc-brown_bg\">allaitement</span></span> (<span>15 %</span>)</td><td>Accouchement et <span><span class=\"nc-brown_bg\">allaitement</span></span></td></tr>\n          <tr><td><span>Grippe</span></td><td>Pas de transmission fœtale directe (pas <span>tératogène</span>)</td><td>Tous trimestres (risque maternel + FCS, prématurité)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 168 — Herpesvirus · 169 — <span>VIH</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-14","rang":"B","rubrique":"Prise en charge","titre":"Herpes simplex virus (HSV) : connaître les éléments de prévention fœtale","contenu":"<div class=\"notion-course\"><ul><li>Distinguer un premier épisode connu (<span class=\"nc-red nc-bold\">primo-infection</span>, infection initiale non primaire ou récurrence méconnue) d’une récurrence documentée. PCR de la lésion et sérologie selon situation ; une lésion atypique nécessite confirmation.</li><li>Premier épisode pendant la <span class=\"nc-green_bg\">grossesse</span> : traitement antiviral, puis prophylaxie à partir de 36 SA selon RPC. Une infection initiale proche de l’accouchement expose au risque néonatal le plus élevé et conduit à discuter/recommander la <span class=\"nc-pink nc-bold\">césarienne</span> selon le délai et les lésions.</li><li>Récurrence : traitement si symptômes invalidants, particulièrement précoce, et prophylaxie en fin de grossesse si épisode pendant la grossesse. Pas de <span class=\"nc-blue_bg\">dépistage</span> virologique systématique en travail en l’absence de lésion/prodrome.</li><li>Récurrence en travail : décision selon membranes, terme et terrain ; une <span class=\"nc-pink nc-bold\">césarienne</span> est davantage considérée si membranes intactes, prématurité ou VIH, une voie vaginale davantage si rupture prolongée à terme sans VIH. Ce n’est pas une règle binaire universelle.</li><li>Prévenir l’équipe pédiatrique et limiter les gestes traumatiques fœtaux en cas de lésions actives. Les deux arbres LiSA/CNGOF détaillent les branches ; les notes distinguent le schéma de ses précautions d’interprétation.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":2},{"id":"27-15","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'infection à VHB materno-fœtale","contenu":"<div class=\"notion-course\"><p>L'<span>infection à VHB materno-fœtale</span> est l'infection par le virus de l'<span>hépatite</span> B contractée par le fœtus ou le nouveau-né à partir d'une mère porteuse (~ <span>1 %</span> des femmes enceintes en France).</p>\n      <table>\n        <thead><tr><th>Mode</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Per-partum (<span>90 %</span>)</td><td>Contact avec le sang maternel — indépendant de la voie d'accouchement (basse ou <span class=\"nc-pink nc-bold\">césarienne</span>)</td></tr>\n          <tr><td>Transplacentaire</td><td>Possible chez les femmes à <strong>haut taux de réplication <span>virale</span></strong> (AgHBe+ avec ADN <span>VHB</span> détectable)</td></tr>\n          <tr><td>Post-natale</td><td><span>Allaitement</span> (faible, autorisé après sérovaccination)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span><span class=\"nc-green_bg\">VHB</span></span><span class=\"nc-green_bg\"> n'est pas </span><span><span class=\"nc-green_bg\">tératogène</span></span></strong> : <span class=\"nc-green_bg\">pas d'embryofœtopathie</span>, pas d'<span><span class=\"nc-blue_bg\">ictère</span></span> néonatal (délai d'incubation). Mais en cas de transmission, <span><span class=\"nc-red_bg nc-bold\">80 à 90 %</span> <span class=\"nc-red_bg\">des nouveau-nés développent une hépatite B chronique</span></span> (<span>vs</span><span> 5-10 %</span> chez l'adulte) → <span>cirrhose</span>, CHC.</div>\n      <p>Risque de transmission élevé en l'absence de mesures préventives, majoré par AgHBe+ avec ADN <span>VHB</span> détectable (<span>90 %</span>) ; AC anti-HBe+ → quasi nul.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-16","rang":"A","rubrique":"Prise en charge","titre":"Virus de l'hépatite B (VHB) : connaître les éléments de prévention fœtale par la vaccination","contenu":"<div class=\"notion-course\"><p>La prévention de l'IMF à <span>VHB</span> repose sur le <strong><span><span class=\"nc-blue_bg\">dépistage</span></span> <span class=\"nc-red nc-bold\">obligatoire</span></strong> + la <strong>sérovaccination du nouveau-né</strong>.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">Dépistage</span></span></td><td><span>Recherche AgHBs</span> obligatoire dès la déclaration de <span><span class=\"nc-green_bg\">grossesse</span></span> (au 1ᵉʳ trimestre)</td></tr>\n          <tr><td>Mère AgHBs+</td><td>Traitement <span>antiviral</span> envisagé pour réduire la charge <span>virale</span> (<span><span class=\"nc-pink nc-bold\">lamivudine</span></span> ou <span><span class=\"nc-pink nc-bold\">ténofovir</span></span>) ; pas de <span class=\"nc-pink nc-bold\">césarienne</span> prophylactique ❌</td></tr>\n          <tr><td><span class=\"nc-blue_bg nc-bold\">Nouveau-né</span></td><td><strong>Sérovaccination <span class=\"nc-pink nc-bold\">dès la naissance</span>, avant <span>H12</span></strong> : Ig anti-HBs IM + 1ʳᵉ dose du vaccin <span>VHB</span> ; schéma complet M0-<span>M1</span>-M6</td></tr>\n          <tr><td><span>Surveillance</span></td><td>À partir de <span><span class=\"nc-pink nc-bold\">9 mois</span></span> (et <span>≥ 1 mois</span> après dernière dose) : AgHBs + titrage AC anti-HBs pour vérifier efficacité</td></tr>\n          <tr><td><span>Allaitement</span></td><td><strong>Autorisé</strong> après sérovaccination (enfant protégé)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Vaccination universelle :</strong> tous les nouveau-nés sont vaccinés contre le <span>VHB</span> selon le calendrier vaccinal — la sérovaccination s'ajoute aux mères AgHBs+ pour court-circuiter la fenêtre per-partum.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-17","rang":"A","rubrique":"Prise en charge","titre":"Virus de l'immunodéficience humaine (VIH) : connaître les éléments de prévention par le dépistage","contenu":"<div class=\"notion-course\"><ul><li>Proposer le <span class=\"nc-blue_bg\">dépistage</span> du VIH en début de <span class=\"nc-green_bg\">grossesse</span>, puis le renouveler en cas d’exposition ou de risque persistant. Un résultat positif conduit rapidement à une prise en charge infectiologique et obstétricale coordonnée.</li><li>Traitement antirétroviral efficace pour toute femme vivant avec le VIH, sans attendre un terme tardif. Choix des molécules, interactions et surveillance selon recommandations actualisées ; ne pas reprendre une liste ancienne de contre-indications sans <span class=\"nc-brown_bg\">vérifier le</span> traitement concerné.</li><li>L’objectif est une charge virale <span class=\"nc-green_bg nc-bold\">indétectable</span> durable. La voie d’accouchement et les mesures périnatales dépendent notamment du contrôle virologique ; une <span class=\"nc-pink nc-bold\">césarienne</span> n’est pas automatique.</li><li>Prophylaxie néonatale et calendrier diagnostique adaptés au niveau de risque, avec équipe pédiatrique.</li><li><b>HAS 2024 :</b> l’allaitement peut être envisagé chez une femme qui le souhaite sous conditions strictes de contrôle virologique, observance et suivi spécialisé maternel et infantile. Le risque résiduel, les alternatives, la prophylaxie infantile et les critères d’interruption doivent être explicités ; ne pas présenter cette possibilité comme applicable sans surveillance.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-18","rang":"A","rubrique":"Prise en charge","titre":"Virus varicelle zona (VZV) : connaître les éléments de prévention par la vaccination","contenu":"<div class=\"notion-course\"><p>La varicelle pendant la <span><span class=\"nc-green_bg\">grossesse</span></span> comporte un <strong>risque maternel</strong> (<span><span class=\"nc-red nc-bold\">pneumonie</span></span> varicelleuse — surmortalité), un <strong>risque embryofœtal</strong> et un <strong>risque néonatal grave</strong>.</p>\n      <table>\n        <thead><tr><th>Période</th><th>Risque</th></tr></thead>\n        <tbody>\n          <tr><td>&lt; 20 SA</td><td><span>Embryofœtopathie varicelleuse</span> (<span>1-2 %</span>) : hypoplasie membres, atteinte cutanée zostérienne, <span class=\"nc-orange_bg\">microphtalmie</span>, <span class=\"nc-red_bg\">microcéphalie</span></td></tr>\n          <tr><td><span>Éruption</span> maternelle 5 j avant à 2 j après accouchement</td><td><span>Varicelle néonatale grave</span> — <span>mortalité</span> ~<span>30 %</span> sans traitement</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong><span>Prévention primaire</span></strong> : <span>vaccin VZV vivant atténué</span> <strong>avant <span><span class=\"nc-green_bg\">grossesse</span></span></strong> chez femmes non immunes ; <span>CI pendant la <span class=\"nc-green_bg\">grossesse</span></span> ⚠️</li>\n        <li><strong>Contage chez femme enceinte non immune</strong> : <span>Ig anti-VZV IV</span> dans les <strong><span>96 h</span></strong></li>\n        <li><strong>Varicelle confirmée chez la mère</strong> : <span>aciclovir IV</span></li>\n      </ul>\n      <p>Contraception <span>≥ 1 mois</span> après vaccin <span>VZV</span> (vaccin vivant).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-19","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de transmission materno-fœtale de la listériose","contenu":"<div class=\"notion-course\"><p><span>Listeria monocytogenes</span> — bactérie Gram+ saprophyte, <span>résiste au <span class=\"nc-red nc-bold\">froid</span></span> mais <span>sensible à la <span class=\"nc-green nc-bold\">chaleur</span></span>. Rare (~ 1/<span <span=\"\">&gt;1000</span> grossesses) mais sévère.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Contamination maternelle</td><td>Alimentation (fromages au lait cru, charcuterie, produits réfrigérés contaminés)</td></tr>\n          <tr><td><span>Diffusion</span></td><td><strong>Bactériémie maternelle</strong> → <strong>transmission <span class=\"nc-orange_bg\">transplacentaire</span> hématogène</strong></td></tr>\n          <tr><td>Atteinte placentaire</td><td>Colonisation placentaire → <strong><span class=\"nc-red\">chorioamniotite</span></strong> → bactériémie fœtale</td></tr>\n          <tr><td>Manifestation maternelle</td><td>2 phases : <span><span class=\"nc-green_bg\">syndrome pseudo-grippal</span></span> (assez banal) puis <span>chorioamniotite</span> (<strong><span class=\"nc-blue nc-bold\">travail prématuré fébrile</span> + <span class=\"nc-blue nc-bold\">perte liquidienne vaginale épaisse</span>/<span class=\"nc-blue nc-bold\">teintée</span></strong>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Conséquences néonatales :</strong> <span class=\"nc-red_bg\">accouchement prématuré</span>, <span class=\"nc-red_bg\">infection néonatale</span> (<span>mortalité</span> <span>50-75 %</span>) — <span>cyanose</span>, apnée, <span>détresse</span> respiratoire, troubles de la conscience, <span><span class=\"nc-red nc-bold\">méningite purulente</span> (95 %)</span>.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-20","rang":"A","rubrique":"Prise en charge","titre":"Listériose materno-fœtale (MF) : connaître les éléments de prévention","contenu":"<div class=\"notion-course\"><p>La prévention de la listériose chez la femme enceinte repose sur des <strong>règles d'hygiène alimentaire strictes</strong> (<span>Listeria</span> résiste au <span class=\"nc-red nc-bold\">froid</span> mais est tuée par la <span class=\"nc-green nc-bold\">chaleur</span> <span>≥ 72 °C</span>).</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td>Aliments <span>à éviter</span></td><td><strong>Fromages au lait cru</strong> à pâte molle (camembert, brie, roquefort), <span class=\"nc-red nc-bold\">fromages vendus râpés</span>, croûtes ; charcuterie cuite consommée en l'état (pâté, rillettes, jambon cuit, produits en gelée) ; <span class=\"nc-red_bg\">poissons fumés</span>, <span class=\"nc-red_bg\">coquillages crus</span>, <span class=\"nc-red_bg\">surimi</span>, <span class=\"nc-red_bg\">tarama</span> ; graines germées crues (soja, luzerne)</td></tr>\n          <tr><td>Précautions cuisson</td><td>Viande consommée <span>bien cuite (≥ 72 °C)</span> ou congelée (-<span <span=\"\">&gt;18</span> °C) ; réchauffer soigneusement les restes alimentaires</td></tr>\n          <tr><td>Hygiène générale</td><td>Lavage des mains avant/après manipulation d'aliments à risque et jardinage ; <span class=\"nc-green_bg\">nettoyage régulier du réfrigérateur</span> ; séparation aliments crus/cuits</td></tr>\n          <tr><td>Légumes/fruits</td><td>Crudités, fruits, légumes et herbes aromatiques soigneusement lavés</td></tr>\n        </tbody>\n      </table>\n      <p><span>Activité physique adaptée</span> :<span> <span class=\"nc-pink nc-bold\">30 min</span></span>, 3 à 5 ×/sem.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span> · 173 — Zoonose</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-21","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à prescrire en cas de suspicion de listériose MF","contenu":"<div class=\"notion-course\"><p>Devant tout <strong>syndrome fébrile sans foyer évident</strong> chez la femme enceinte, suspecter une listériose et prescrire :</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-blue nc-bold\">Hémocultures</span></span></strong> (aéro/anaérobies)</td><td>En précisant explicitement <strong>la recherche de <span>Listeria</span> monocytogenes</strong> au laboratoire</td></tr>\n          <tr><td><span>ECBU</span> + bilan <span>inflammatoire</span></td><td><span>NFS</span>, <span>CRP</span> — recherche d'autres foyers (<span>pyélonéphrite</span>, chorioamniotite)</td></tr>\n          <tr><td>À l'accouchement</td><td><span>Hémocultures</span> en cas de reprise fébrile ; examen bactériologique <strong>du placenta + lochies</strong> (presque toujours positif si recueil correct) ; <span>anatomopathologie</span> placentaire (<strong><span class=\"nc-orange nc-bold\">granulomes </span><span><span class=\"nc-orange nc-bold\">infectieux</span></span></strong>)</td></tr>\n          <tr><td>Nouveau-né</td><td><strong><span><span class=\"nc-blue_bg\">Hémocultures</span></span>, <span><span class=\"nc-blue_bg\">LCS</span></span></strong> (germe facilement isolé en culture), prélèvement de liquide gastrique, <span class=\"nc-brown_bg\">méconium</span>, <span class=\"nc-brown_bg\">peau</span></td></tr>\n          <tr><td>Enquête environnementale</td><td>À partir des aliments suspects si suspicion d'épidémie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span>Antibiothérapie</span> probabiliste dès la suspicion</strong> (avant résultat des <span><span class=\"nc-blue_bg\">hémocultures</span></span>) chez la femme enceinte fébrile avec <span>signes de gravité</span> : <span><span class=\"nc-pink_bg\">amoxicilline</span> IV</span> (ou <span>érythromycine</span> si <span>allergie</span>). Si confirmation : <strong><span><span class=\"nc-pink_bg\">amoxicilline</span></span> + <span class=\"nc-pink_bg nc-bold\">aminoside</span> 5 j</strong> puis <span><span class=\"nc-pink_bg\">amoxicilline</span></span> <span>≥ 4</span> sem ou <span class=\"nc-pink_bg nc-bold\">jusqu'à l'accouchement</span>.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-22","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de transmission materno-fœtale du streptocoque B","contenu":"<div class=\"notion-course\"><p><span><span class=\"nc-purple_bg\">Streptococcus agalactiae</span></span> (SGB) — <strong><span class=\"nc-red nc-bold\">bactérie la plus fréquemment en cause dans les infections graves du nouveau-né</span></strong>.</p>\n      <table>\n        <thead><tr><th>Indicateur</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span>Prévalence</span> portage en France</td><td><span>10-15 %</span> (<span>10-35 %</span> digestif/vaginal selon Pilly)</td></tr>\n          <tr><td>Colonisation néonatale</td><td><span>50-70 %</span> (Pilly)</td></tr>\n          <tr><td>Risque de transmission néonatale (gynéco)</td><td><span>40-50 %</span></td></tr>\n          <tr><td>Risque d'<span class=\"nc-red_bg\">infection néonatale</span> (Pilly)</td><td><span>1 %</span> des nouveau-nés colonisés</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Colonisation cervico-vaginale maternelle</strong> asymptomatique</li>\n        <li><strong>Transmission per-partum ascendante</strong> lors de l'accouchement ou de la <span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> prolongée des membranes</span> (RPM)</li>\n        <li>Conséquences néonatales : <span>sepsis néonatal précoce</span> (pneumopathie, <span>méningite</span>), <span><span class=\"nc-red_bg\">chorioamniotites</span></span>, IMF, <span class=\"nc-red_bg\">endométrites du post-partum</span></li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-23","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge médicamenteuse de la vaginose bactérienne","contenu":"<div class=\"notion-course\"><p>La <span>vaginose bactérienne</span> est un déséquilibre de la flore vaginale (lactobacilles → <span class=\"nc-red_bg\">anaérobies</span> : <em><span class=\"nc-purple nc-bold\">Gardnerella vaginalis</span></em>, <em>Mobiluncus</em>, Bacteroides, mycoplasmes). <span>Prévalence</span> : <span>7 %</span> au 1ᵉʳ trimestre en France.</p>\n      <table>\n        <thead><tr><th>Traitement</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-pink nc-bold\">Métronidazole</span></span></td><td><span>7 jours</span>, voie orale ou ovule</td></tr>\n          <tr><td><span><span class=\"nc-pink nc-bold\">Clindamycine</span></span></td><td><span>7 jours</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Indication du <span><span class=\"nc-blue_bg\">dépistage</span></span></strong> : pas de bénéfice systématique en population générale ; utile si <strong><span class=\"nc-purple_bg nc-bold\">ATCD</span> d'accouchement prématuré</strong> dans un contexte de <span class=\"nc-orange_bg\">chorioamniotite</span> <span>bactérienne</span> (<span class=\"nc-blue_bg\">dépistage</span> par prélèvement vaginal au 1ᵉʳ trimestre)</li>\n        <li><strong>Diagnostic</strong> : <span><span class=\"nc-yellow_bg\">critères cliniques</span></span><span class=\"nc-yellow_bg\"> d'</span><span><span class=\"nc-yellow_bg nc-bold\">Amsel</span></span> (<span>≥ 3</span>/4 : <span>pH</span> &gt; 4,5, <span class=\"nc-blue_bg\">leucorrhées</span> <span class=\"nc-blue_bg\">grisâtres</span> <span class=\"nc-blue_bg\">homogènes</span>, <span class=\"nc-yellow_bg nc-bold\">clue</span> <span class=\"nc-yellow_bg nc-bold\">cells</span> &gt;<span> 20 %</span>, <span class=\"nc-yellow_bg\">sniff test</span> positif) et/ou <span>score de <span class=\"nc-yellow_bg nc-bold\">Nugent</span></span> <span>≥ 7</span> (coloration de Gram)</li>\n        <li><strong><span>Surveillance</span></strong> : contrôle trimestriel (récidive fréquente) ; renouveler le traitement si nécessaire</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-24","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le risque de la vaginose bactérienne au cours de la grossesse","contenu":"<div class=\"notion-course\"><p>La <span>vaginose</span> <span>bactérienne</span> expose à des risques infectieux et obstétricaux. Le lien avec l'accouchement prématuré reste modeste mais réel.</p>\n      <ul>\n        <li><strong>Complications obstétricales</strong> : <span><span class=\"nc-orange nc-bold\">menace d'accouchement prématuré</span> (<span class=\"nc-orange_bg\">MAP</span>)</span> (odds ratio 1,5 à 2)</li>\n        <li><strong><span class=\"nc-red\">Infections génitales</span> hautes (IGH)</strong></li>\n        <li><strong><span class=\"nc-purple_bg\">Infections postopératoires</span></strong><span class=\"nc-purple_bg\"> en cas de geste chirurgical par voie vaginale</span></li>\n        <li><strong>Chorioamniotite</strong> <span>bactérienne</span></li>\n        <li><strong><span>Rupture</span> prématurée des membranes (RPM)</strong></li>\n        <li><strong>Endométrite</strong> du post-partum</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Lien faible mais significatif</strong> avec la <span class=\"nc-red nc-bold\">prématurité</span> — d'où l'indication de <span>dépistage</span> ciblé en cas d'<span class=\"nc-purple_bg nc-bold\">ATCD</span> d'<span class=\"nc-red\">accouchement prématuré</span> sur <span class=\"nc-red\">chorioamniotite</span> (et non systématique).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-25","rang":"A","rubrique":"Prise en charge","titre":"Grippe et grossesse","contenu":"<div class=\"notion-course\"><p>La femme enceinte est une <strong>population à risque de <span><span class=\"nc-red nc-bold\">grippe</span></span> sévère</strong> (surtout T2 et T3) — la <span class=\"nc-red nc-bold\">grippe</span> entraîne plus d'hospitalisations graves chez la femme enceinte que la listériose ou la toxoplasmose.</p>\n      <table>\n        <thead><tr><th>Versant</th><th>Risques</th></tr></thead>\n        <tbody>\n          <tr><td>Maternel</td><td><span>Hospitalisation</span> accrue (T2-T3), <span>complications pulmonaires</span> (surinfection, <span>OAP</span>), <span>complications cardiovasculaires</span>, hospitalisation en réanimation</td></tr>\n          <tr><td>Fœtal</td><td><strong>Pas <span>tératogène</span> ❌</strong> · <span class=\"nc-orange_bg\">avortement</span>, <span class=\"nc-orange_bg\">prématurité</span> (lié à la <span>fièvre</span> et aux complications maternelles)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Prévention primaire</span> :</strong></p>\n      <ul>\n        <li><span>Vaccination antigrippale</span> = <strong>meilleur moyen de protection</strong>, <span class=\"nc-yellow_bg\">possible à tous les stades de la </span><span><span class=\"nc-yellow_bg\">grossesse</span></span> (<strong>vaccin inactivé</strong>)</li>\n        <li>Passage des AC maternels protège le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> et le nourrisson de moins de <span>6 mois</span> (non vaccinables)</li>\n        <li><span class=\"nc-green_bg\">Mesures d'hygiène</span>, limitation des contacts</li>\n      </ul>\n      <p><strong><span>Prévention secondaire</span> / traitement post-exposition :</strong></p>\n      <ul>\n        <li>Contage &lt;<span> 48h</span> : <span><span class=\"nc-pink_bg\">oseltamivir</span> prophylactique</span> 1×/j pendant 10 j (sauf si vaccinée)</li>\n        <li>Suspicion <span>grippe</span> : <span><span class=\"nc-pink_bg\">oseltamivir</span> curatif</span> 2×/j pendant 5 j, débuté &lt;<span> 48 h</span> après les 1ᵉʳˢ signes</li>\n        <li><span>Hospitalisation</span> si <span>signes de gravité</span> (atteinte fonctions supérieures, FR &gt; 30, PAS &lt; 90, FC &gt; 120)</li>\n        <li><span>Allaitement</span> maternel possible ✅</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-26","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l'allo-immunisation antiérythrocytaire","contenu":"<div class=\"notion-course\"><p>L'allo-immunisation antiérythrocytaire correspond à la présence chez une femme enceinte d'un <span>AC irrégulier</span> (non-A ou non-B) dirigé contre un <span>antigène</span> de groupe sanguin érythrocytaire fœtal.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Sensibilisation maternelle</td><td>Passage de GR fœtales incompatibles dans la circulation maternelle (mère <span>RhD</span>-, fœtus RhD+) lors d'événements à risque (accouchement, FCS, IVG, GEU, traumatisme abdo, <span>amniocentèse</span>, version par manœuvre externe, <span>chirurgie</span> utérine, métrorragies, ou de façon spontanée silencieuse ⚠️) ; ou transfusion non isogroupe (rare)</td></tr>\n          <tr><td>Production d'IgG anti-D</td><td>AC <strong>réguliers IgM</strong> ne passent pas la barrière placentaire ❌ ; AC <strong>irréguliers IgG</strong> passent ✅</td></tr>\n          <tr><td>Passage <span class=\"nc-orange_bg\">transplacentaire</span></td><td>IgG anti-D <span class=\"nc-blue_bg nc-bold\">maternelles</span> traversent le placenta vers la circulation fœtale</td></tr>\n          <tr><td>Hémolyse fœtale</td><td><strong><span class=\"nc-red_bg\">Anémie</span> hémolytique fœtale</strong> (1ʳᵉ cause d'<span class=\"nc-red_bg\">anémie</span> fœtale) → <span>anasarque</span> (épanchements séreux) → <span>MFIU</span></td></tr>\n          <tr><td>Atteinte néonatale</td><td>AC maternels persistent plusieurs semaines : <span><span class=\"nc-red_bg\">anémie</span> hémolytique néonatale</span> + <span><span class=\"nc-blue_bg\">ictère</span> à bilirubine libre</span> (risque <strong><span><span class=\"nc-blue_bg\">ictère</span></span> nucléaire</strong> = séquelles neuro)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>AC les + fréquents et + graves :</strong> anti-D (Rh1), anti-c (Rh4), anti-Kell. Mère non concernée (ses propres GR n'expriment pas l'Ag).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-27","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic de l'allo-immunisation antiérythrocytaire","contenu":"<div class=\"notion-course\"><p>Le diagnostic combine un <strong>versant maternel</strong> (<span><span class=\"nc-blue_bg\">dépistage</span></span> sérologique de l'allo-immunisation) et un <strong>versant fœtal</strong> (évaluation du risque d'<span class=\"nc-red_bg\">anémie</span>).</p>\n      <table>\n        <thead><tr><th>Versant</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Maternel — systématique au 1ᵉʳ trimestre</td><td><strong><span>Groupe rhésus phénotype</span></strong> (2 déterminations) + <strong><span>RAI</span></strong> (Recherche d'Agglutinines Irrégulières)</td></tr>\n          <tr><td>Recontrôle RAI</td><td>Indications : femmes <span>RhD</span>- ou RhD+ précédemment transfusées · à <strong><span>M6</span>, M8, M9</strong> · inutile si Ig anti-D déjà injectées ou génotypage fœtal RhD-</td></tr>\n          <tr><td>Si RAI positive</td><td>1️⃣ <strong>Identifier l'AC</strong> (anti-D, anti-Kell, anti-c…) · 2️⃣ <strong>Titrage</strong> de l'AC (<span>Coombs</span> indirect) · 3️⃣ Dosage pondéral des AC anti-Rh (plus précis)</td></tr>\n          <tr><td>Phénotypage père</td><td>Groupe rhésus du conjoint connu chez femmes <span>RhD</span>- ; phénotypage père pour autres Ag (Kell…)</td></tr>\n          <tr><td>Fœtal — génotypage <span>RhD</span></td><td><span>PCR sur ADN fœtal circulant</span> dans le sang maternel ; <strong>dès 11 SA</strong> ; uniquement si mère <span>RhD</span>-</td></tr>\n          <tr><td>Évaluation <span class=\"nc-red_bg\">anémie</span> fœtale</td><td><span>Doppler artère cérébrale moyenne (PSV-ACM)</span> : <span>Vmax &gt; 1,5 MoM</span> = <span class=\"nc-red_bg\">anémie</span> significative ; <span>Doppler ombilical</span> ; <span>ECG-tocographie</span> : <span>tachycardie</span> ou <span>rythme sinusoïdal</span> = <span class=\"nc-red_bg\">anémie</span> très sévère</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Seuils à risque fœtal important :</strong> titrage AC ≥ <span>16</span> (1/16) ou dosage pondéral ≥ <span>1 µg/mL</span>. <strong><span class=\"nc-red\">Anasarque</span> échographique</strong> + tracé sinusoïdal = <span class=\"nc-red_bg\">anémie</span> sévère = <span>urgence</span> (Hb &lt;<span> 5 g/dL</span> le + souvent).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-28","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître la prévention de l'allo-immunisation antiérythrocytaire durant la grossesse","contenu":"<div class=\"notion-course\"><ul><li>La prophylaxie anti-D concerne une femme RhD négatif non déjà immunisée, exposée à des hématies fœtales RhD positives. Le génotypage fœtal RhD permet d’adapter la prévention lorsqu’il est disponible et interprétable.</li><li>Prophylaxie systématique vers 28 SA si fœtus RhD positif ou statut inconnu : immunoglobulines anti-D selon protocole, après vérification du groupe et de la RAI. Une RAI positive doit être interprétée en tenant compte d’une injection récente.</li><li>Prévention ciblée après événement à risque de passage fœto-maternel, selon terme, situation et statut fœtal ; injection idéalement dans les 72 heures et dose adaptée si hémorragie fœto-maternelle importante.</li><li><b>CNGOF 2024 :</b> avant 12 SA, il est recommandé de ne pas administrer systématiquement d’anti-D pour IVG, <span class=\"nc-red nc-bold\">fausse couche</span> ou <span class=\"nc-green_bg\">grossesse</span> arrêtée intra-utérine, ni pour métrorragies d’une <span class=\"nc-green_bg\">grossesse</span> intra-utérine évolutive. Le niveau de preuve est très faible.</li><li>Pour la GEU avant 12 SA, aucune recommandation n’a pu être émise : avis/protocole spécialisé. Ne pas étendre cette absence de prophylaxie du premier trimestre aux gestes ou événements ultérieurs.</li><li>La prophylaxie prévient l’immunisation ; elle ne traite pas une allo-immunisation déjà constituée, qui nécessite une surveillance fœtale spécialisée.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/27/allo-immunisation-schema-resume.png\" alt=\"Schéma résumé d&#x27;évaluation et de prévention de l&#x27;allo-immunisation maternofœtale Rhésus (versant maternel RAI / versant fœtal génotypage RhD)\" loading=\"lazy\">\n        <figcaption>Schéma résumé d'évaluation et de prévention de l'allo-immunisation maternofœtale Rhésus (rang C). Source : fiche source EDN item 27 — Allo-immunisation maternofoetale Rhésus.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":2},{"id":"27-29","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître la prévention de l'allo-immunisation antiérythrocytaire dans le post-partum","contenu":"<div class=\"notion-course\"><ul><li>Après la <span class=\"nc-pink nc-bold\">naissance</span>, la prophylaxie concerne une mère RhD négatif non immunisée et un enfant RhD positif (ou statut non établi selon protocole). Vérifier groupe et contexte des injections antérieures.</li><li>Administrer les immunoglobulines anti-D idéalement dans les 72 heures, selon RCP/protocole. Si retard, solliciter rapidement l’équipe : ne pas conclure soi-même que toute prévention est devenue inutile.</li><li>Quantifier l’hémorragie fœto-maternelle par test approprié, notamment Kleihauer, pour adapter la dose. La prophylaxie systématique de <span class=\"nc-green_bg\">grossesse</span> ne dispense pas de l’évaluation postnatale.</li><li>Une allo-immunisation déjà constituée relève de la surveillance et du traitement spécialisés ; l’anti-D prophylactique ne traite pas l’<span class=\"nc-red_bg\">anémie</span> fœtale ou néonatale.</li><li>Les règles du post-partum ne doivent pas être transposées aux événements du premier trimestre : voir les distinctions CNGOF 2024 de l’objectif 27-28.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-30","rang":"A","rubrique":"Prise en charge","titre":"Médicaments et grossesse : connaître la conduite à tenir en cas d'exposition","contenu":"<div class=\"notion-course\"><p>L'évaluation d'une exposition médicamenteuse repose sur la <strong>chronologie</strong>, le <strong>terme d'exposition</strong> et le <strong>profil <span>tératogène</span></strong> du médicament. Ressource clé : <span>CRAT</span> (Centre de Référence sur les Agents Tératogènes — lecrat.fr) et centres régionaux de pharmacovigilance.</p>\n      <table>\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Patiente prenant un traitement, ne se sachant pas enceinte</td><td>Consigner durée, quantité, indication. Évaluer le risque selon le terme (organogenèse T1) + bénéfice maternel à l'arrêt. Discussion en <strong>comité de diagnostic prénatal (CPDPN)</strong> après information du couple</td></tr>\n          <tr><td>Patiente sous traitement désirant une <span>grossesse</span></td><td>Consultation préconceptionnelle pour adapter au traitement le mieux connu pour une <span>grossesse</span> — assistance des CRPV</td></tr>\n          <tr><td>Malformation découverte à la naissance</td><td><span>Prévalence</span> des malformations en population générale ~ <span>2-3 %</span>, dont &lt;<span> 5 %</span> d'origine médicamenteuse. Reprendre rétrospectivement la chronologie, déclarer au CRPV/ANSM</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Principes fondamentaux :</strong> <span>ne jamais</span> inquiéter inutilement une patiente après découverte d'une prise médicamenteuse en début de <span>grossesse</span> ; un traitement chronique ne doit pas être interrompu brutalement ; éviter l'automédication ; en cas de doute, diagnostic anténatal possible pour la majorité des médicaments tératogènes.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0,"liens":[{"href":"https://www.lecrat.fr/","label":"CRAT — Centre de Référence sur les Agents Tératogènes"}]},{"id":"27-31","rang":"A","rubrique":"Diagnostic positif","titre":"Médicaments et grossesse : connaître les principaux médicaments à risque","contenu":"<div class=\"notion-course\"><p>Les médicaments à risque sont classés par <strong>profil de risque</strong> (<span>tératogène</span>, fœtotoxique, néonatal). En population générale, le risque spontané de malformation majeure est de <span>2-3 %</span>.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Molécules</th><th>Risque tératogène (T1)</th></tr></thead>\n        <tbody>\n          <tr><td>Anticancéreux</td><td><span>Méthotrexate</span> fortes doses, <span>cyclophosphamide</span></td><td><span>CI absolue</span> — anomalies fermeture tube neural, dysmorphie</td></tr>\n          <tr><td>Antiépileptiques</td><td><span><span class=\"nc-red nc-bold\">Valproate de sodium</span></span> (× 4-5), <span><span class=\"nc-red nc-bold\">carbamazépine</span></span>, <span>phénytoïne</span>, <span><span class=\"nc-red nc-bold\">phénobarbital</span></span>, <span>topiramate</span></td><td>Spina bifida (AFTN), cardiopathies (CIA, CIV), fentes faciales, hypospadias, retard psychomoteur</td></tr>\n          <tr><td><span>Rétinoïdes</span></td><td><span>Isotrétinoïne</span> (Roaccutane®), <span>acitrétine</span></td><td><span>CI</span> ·<span> 25-30 %</span> de malformations (SNC, oreille externe, cœur, squelette) ; contraception <span>2 ans</span> après arrêt acitrétine</td></tr>\n          <tr><td>Thymorégulateur</td><td><span>Lithium</span> (Téralithe®)</td><td>Malformations cardiaques (<span>Ebstein</span>, CA, CIV)<span> 4-8 %</span></td></tr>\n          <tr><td>Anti-vit K</td><td><span><span class=\"nc-red nc-bold\">Warfarine</span></span></td><td>Warfarin fetal syndrome <span>4-6 %</span> (dysmorphie, hypoplasie phalanges, anomalies cérébrales) ; relais <span>HBPM</span> en vue <span>grossesse</span></td></tr>\n          <tr><td><span>Immunosuppresseurs</span></td><td><span>Mycophénolate</span> (CellCept®)</td><td>FCS <span>50 %</span> ; anomalies oreille externe, fente labio-palatine, micrognathie</td></tr>\n          <tr><td>Prostaglandines</td><td><span>Misoprostol</span></td><td><span>Syndrome de Moebius</span>, rétrognathie, anomalies membres</td></tr>\n          <tr><td>Antithyroïdiens</td><td><span>Carbimazole</span></td><td>Aplasie cuir chevelu, atrésie choanes/œsophage, omphalocèle (remplacer par PTU au T1)</td></tr>\n          <tr><td>Virostatiques</td><td><span>Ribavirine</span>, <span>éfavirenz</span></td><td>Malformations faciales, membres, tube neural</td></tr>\n          <tr><td><strong><span><span class=\"nc-red nc-bold\">AINS</span></span></strong> (T2-T3)</td><td><span>Aspirine</span> (<span class=\"nc-green_bg\">sauf</span> faible dose &lt;<span> 100 mg</span>/j), <span>ibuprofène</span>, célécoxib</td><td><span>CI absolue ≥ 24 SA</span> ⚠️ : fermeture prématurée canal artériel, HTAP fœtale, oligoamnios, IR fœtale</td></tr>\n          <tr><td><strong><span>IEC</span> / <span>ARA2</span></strong> (T2-T3)</td><td>Enalapril, <span>losartan</span>…</td><td><span>CI T2-T3</span> : oligoamnios, IR fœtale et néonatale, anomalies voûte crânienne</td></tr>\n          <tr><td>Thalidomide / lénalidomide</td><td>—</td><td><span>CI absolue</span> ·<span> 30-40 %</span> phocomélie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Antibiotiques <span>à éviter</span> :</strong> <span class=\"nc-pink_bg\">tétracyclines</span> (coloration dentaire), aminosides (atteinte cochléovestibulaire), <span class=\"nc-pink_bg\">quinolones</span> (risque ostéoarticulaire). Aucun ATB n'est <em>formellement</em> CI — priorité au bénéfice maternel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-32","rang":"B","rubrique":"Diagnostic positif","titre":"Médicaments et grossesse : connaître les conséquences des principaux médicaments à risque","contenu":"<div class=\"notion-course\"><p>Les conséquences dépendent de la <strong>fenêtre d'exposition</strong> — c'est le piège QCM central de l'item.</p>\n      <table>\n        <thead><tr><th>Fenêtre</th><th>Terme</th><th>Conséquence type</th></tr></thead>\n        <tbody>\n          <tr><td>Péri-implantatoire</td><td>&lt; J12</td><td><strong><span class=\"nc-brown_bg\">Tout ou rien</span></strong> : <span class=\"nc-red nc-bold\">mort embryonnaire</span> <strong>ou</strong> <span class=\"nc-green nc-bold\">aucun effet</span> (sauf médicaments à demi-vie longue)</td></tr>\n          <tr><td>Embryonnaire (organogenèse)</td><td>J13 – J56 (T1)</td><td><strong>Période de sensibilité maximale aux <span class=\"nc-red_bg\">effets tératogènes</span></strong> → malformations structurelles</td></tr>\n          <tr><td>Fœtale</td><td>T2 et T3</td><td>Effets fœtotoxiques : <span><span class=\"nc-blue nc-bold\">atteinte de la croissance</span></span>, <span><span class=\"nc-blue nc-bold\">atteinte de la maturation histologique</span></span>, <span><span class=\"nc-blue nc-bold\">atteinte fonctionnelle des organes en place</span></span></td></tr>\n          <tr><td>Fin de <span>grossesse</span> / accouchement</td><td>T3 / per-partum</td><td><span class=\"nc-yellow_bg\">Effets néonataux</span> : <span>sevrage</span>, <span>détresse</span> respiratoire, hypoglycémie/<span>bradycardie</span> (BB-)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Exemples concrets par profil :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">AINS</span> T2-T3</span> : <span>fermeture prématurée canal artériel</span>, HTAP fœtale, IR néonatale, hémorragie néonatale — <span>CI absolue ≥ 24 SA</span> (exception : <span>aspirine</span> faible dose &lt;<span> 100 mg</span>/j pour prééclampsie/<span class=\"nc-green_bg nc-bold\">SAPL</span> jusqu'à 36 SA)</li>\n        <li><span>IEC / ARA2 T2-T3</span> : oligoamnios, IR fœtale et néonatale, anomalies voûte crânienne</li>\n        <li><span>Inducteurs enzymatiques</span> (<span><span class=\"nc-red nc-bold\">rifampicine</span></span>, <span><span class=\"nc-red nc-bold\">phénobarbital</span></span>, <span class=\"nc-red nc-bold\">carbamazépine</span>) : déficit en vitamine K néonatale → <span>supplémentation vitamine K orale</span> aux 2 derniers trimestres chez la mère + vitamine K1 chez nouveau-né</li>\n        <li><span><span class=\"nc-yellow_bg\">Psychotropes</span> T3</span> (<span>ISRS</span>, BZD, antipsychotiques, imipraminiques) : <span>détresse</span> respiratoire, <span>syndrome de sevrage néonatal</span> ou sérotoninergique, hypertonie, troubles succion (privilégier demi-vies courtes)</li>\n        <li><span>Bêtabloquants</span> (<span><span class=\"nc-red nc-bold\">propranolol</span></span>, <span><span class=\"nc-red nc-bold\">labétalol</span></span>) : <span>hypoglycémie + bradycardie</span> néonatale, RCIU si traitement prolongé — prévenir l'équipe pédiatrique</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/27/sensibilite-foetale-terme.png\" alt=\"Sensibilité fœtale en fonction du terme — schéma chronologique des 4 fenêtres : péri-implantatoire (tout ou rien), embryonnaire (tératogenèse T1), fœtale T2-T3 (fœtotoxicité), accouchement (effets néonataux)\" loading=\"lazy\">\n        <figcaption>Sensibilité fœtale en fonction du terme : 4 fenêtres d'exposition aux médicaments. Source : fiche source EDN item 27 — Médicaments et <span>grossesse</span>.</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":2},{"id":"27-33","rang":"A","rubrique":"Prise en charge","titre":"Vaccins et grossesse","contenu":"<div class=\"notion-course\"><p>La règle générale : <strong>vaccins inactivés autorisés</strong> · <strong>vaccins vivants atténués théoriquement <span>contre-indiqués</span></strong>. Néanmoins, en cas de vaccination par inadvertance, <strong>pas d'interruption de <span>grossesse</span></strong> et <strong>pas d'inquiétude à transmettre à la patiente</strong>.</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Vaccins concernés</th><th>Pendant la grossesse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Vaccins vivants atténués</strong></td><td><span><span class=\"nc-red_bg\">ROR</span></span> (rougeole-oreillons-rubéole), <span><span class=\"nc-red_bg\">varicelle</span></span>, <span><span class=\"nc-red_bg\">BCG</span></span>, <span><span class=\"nc-red_bg\">poliomyélite</span></span> (oral), <span><span class=\"nc-red_bg\">rotavirus</span></span>, <span><span class=\"nc-orange_bg\">fièvre jaune</span></span></td><td><span>Théoriquement CI</span> · <span><span class=\"nc-orange_bg\">fièvre</span></span><span class=\"nc-orange_bg\"> jaune</span> : exception si zone endémique inévitable (bénéfice/risque favorable)</td></tr>\n          <tr><td><strong>Vaccins inactivés autorisés</strong></td><td><span>Grippe</span> (<span class=\"nc-green nc-bold\">recommandé</span> +++), <span>dTPa</span> <span class=\"nc-orange_bg\">coqueluche</span> (20-36 SA, protection nouveau-né), <span>COVID</span>, <span>VHA</span>, <span>VHB</span>, <span>méningo</span>, <span>pneumo</span>, <span>rage</span>, polio injectable</td><td>Autorisés à tous les trimestres</td></tr>\n          <tr><td>Risque fœtal théorique</td><td>Vaccins responsables d'une <span>réaction vaccinale importante avec fièvre</span> : <span class=\"nc-orange_bg\">diphtérie</span>, <span class=\"nc-orange_bg\">coqueluche</span>, <span><span class=\"nc-orange_bg\">fièvre</span></span><span class=\"nc-orange_bg\"> jaune</span></td><td><span>Surveillance</span> maternelle</td></tr>\n          <tr><td>Innocuité non prouvée</td><td>Choléra, VHA, typhoïde</td><td>À discuter selon séjour en zone à risque</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Vaccin antigrippal <span class=\"nc-green nc-bold\">recommandé</span> +++</strong> chez la femme enceinte, notamment chez les patientes à risque (<span>diabète</span>, <span>obésité</span>) — femmes enceintes plus à risque de complications pulmonaires et cardiovasculaires au T2-T3.</div>\n      <p>Délai après vaccin vivant atténué : contraception <span>≥ 1 mois</span> avant <span>grossesse</span>.</p><div class=\"callout callout-info\"><b>Actualisation et précisions</b><ul><li>Vaccination maternelle contre le VRS : possibilité entre 32 et 36 SA selon campagne et recommandations, en alternative à la prévention néonatale appropriée ; coordonner le choix et les situations particulières. Vérifier le calendrier vaccinal de l’année.</li></ul></div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-34","rang":"B","rubrique":"Physiopathologie","titre":"Tabac et grossesse : connaître la physiopathologie","contenu":"<div class=\"notion-course\"><p>La fumée de <span>tabac</span> contient &gt; <span>4000 produits toxiques</span>. L'atteinte fœtale est <strong>dose-dépendante</strong> et liée à l'interaction de facteurs sociodémographiques, épidémiologiques et génétiques.</p>\n      <table>\n        <thead><tr><th><span>Toxique</span></th><th>Mécanisme physiopathologique</th></tr></thead>\n        <tbody>\n          <tr><td>Nicotine</td><td>Vasoconstriction utéro-placentaire → <span>hypoperfusion placentaire</span> chronique</td></tr>\n          <tr><td>Monoxyde de carbone (CO)</td><td>Liaison à l'Hb (HbCO) → <span>diminution du transport d'O₂</span> au fœtus → hypoxie chronique</td></tr>\n          <tr><td>Métabolites cytochrome P450 / glutathione S-transférase</td><td>Polymorphisme <span>génétique</span> influence la sensibilité — chez les mères de petits poids, davantage de polymorphismes de l'un ou l'autre de ces <span>2 g</span>ènes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Effet majoré au 3ᵉ trimestre :</strong> les patientes sevrées aux T1-T2 ont des nouveau-nés au poids quasi normal ; l'effet sur la croissance est surtout au T3.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-35","rang":"A","rubrique":"Diagnostic","titre":"Connaître les conséquences d'une intoxication tabagique pendant la grossesse","contenu":"<div class=\"notion-course\"><p>Dans la plupart des pays européens, le <span>tabagisme</span> en cours de <span>grossesse</span> est <strong><span class=\"nc-red nc-bold\">la principale cause évitable de </span><span><span class=\"nc-red nc-bold\">morbidité</span></span><span class=\"nc-red nc-bold\"> périnatale</span></strong>. <span>~17 %</span> des femmes enceintes continuent à fumer jusqu'à la fin de la grossesse.</p>\n      <table>\n        <thead><tr><th>Période</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td>Fertilité</td><td><span class=\"nc-red nc-bold\">Stérilité</span> (RR&gt;2 : 2 × plus de cycles nécessaires)</td></tr>\n          <tr><td>T1</td><td><strong>1ʳᵉ cause de <span><span class=\"nc-red_bg\">GEU</span></span></strong> (RR &gt; 2) · <span>FCS</span> dose-dépendantes (RR ≈ 2) · effets tératogènes réels mais faibles</td></tr>\n          <tr><td>T2-T3</td><td><span><span class=\"nc-red_bg\">RCIU</span></span> dose-dépendant (apparaît préférentiellement 2ᵉ moitié de <span>grossesse</span>) · <span>prématurité</span> (faible mais significatif) · <span><span class=\"nc-red_bg\">placenta praevia</span></span> (+<span> 30 %</span>) · <span>HRP (× 2)</span> · césarienne ↑ si &gt; <span>20 cig/j</span></td></tr>\n          <tr><td>Néonatal</td><td><strong><span class=\"nc-red_bg\">Mort inattendue/subite du nourrisson</span></strong> (× 2 même en environnement non fumeur ⭐) · <span class=\"nc-orange_bg\">infections respiratoires basses</span> + otites (+<span> 50 %</span>) · <span><span class=\"nc-orange_bg\">obésité</span></span><span class=\"nc-orange_bg\"> de l'adolescent</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Effet-dose démontré</strong> entre <span>tabagisme</span> maternel et atteinte fœtale. Même le <span>tabagisme passif</span> a un effet significatif sur le <span class=\"nc-red_bg\">RCIU</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span>tabac</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-36","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge des femmes enceintes fumeuses","contenu":"<div class=\"notion-course\"><p>Environ <span>50 %</span> des femmes fumeuses arrêtent spontanément sans aide médicamenteuse. Le <span>sevrage</span> est bénéfique <strong>à tous les stades de la <span>grossesse</span></strong>.</p>\n      <table>\n        <thead><tr><th>Type</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Médicamenteuse</td><td><span>Substituts nicotiniques</span> autorisés <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span> (en cas de dépendance pharmacologique) ; <span>varénicline et bupropion CI</span></td></tr>\n          <tr><td>Évaluation objective</td><td><span>Analyseur de CO expiré</span> — mesure objective remise à la patiente</td></tr>\n          <tr><td>Non médicamenteuse</td><td>Conseil minimal de <span>sevrage</span> · intervention brève (questions ouvertes) · <strong>entretien motivationnel</strong> · TCC · consultation psychologique · consultation addictologie si polyconsommation</td></tr>\n          <tr><td>Prévention rechutes</td><td>~2/3 des patientes sevrées rechutent à<span> 6 mois</span> et &gt;3/<span>4 à 1 an</span> · anticipation avec tabacologue en cours de <span>grossesse</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span>tabac</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-37","rang":"A","rubrique":"Diagnostic","titre":"Connaître les conséquences d'une alcoolisation pendant la grossesse : syndrome d'alcoolisation fœtale (SAF) et ensemble des troubles causés par l'alcoolisation fœtale (ETCAF)","contenu":"<div class=\"notion-course\"><p>Le <span>SAF</span> est la <strong>principale complication d'une alcoolisation chronique <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span></strong>. Fréquence en France : <span>1 à 2/1000</span> sous sa forme complète. <strong>1ʳᵉ cause évitable de retard mental d'origine non <span>génétique</span>.</strong></p>\n      <p><strong>Le SAF associe 4 éléments à divers degrés :</strong></p>\n      <table>\n        <thead><tr><th>Élément</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Retard de croissance</td><td>Modéré dans <span>80 %</span> des cas, <strong><span class=\"nc-yellow_bg\">harmonieux</span></strong> (<span class=\"nc-blue_bg\">os longs</span> + périmètre abdo + PC — toxicité directe sur les cellules neurologiques)</td></tr>\n          <tr><td><span>Dysmorphie craniofaciale</span></td><td><span class=\"nc-blue_bg\">Hypertrichose</span> + <span class=\"nc-blue_bg\">synophris</span> (monosourcil), <span><span class=\"nc-yellow_bg\">fentes palpébrales étroites</span></span>, ptosis, <span class=\"nc-yellow_bg\">épicanthus</span>, <span class=\"nc-yellow_bg\">hypertélorisme</span>, oreilles basses mal ourlées, <span class=\"nc-green_bg\">ensellure nasale prononcée</span>, nez court, <span><span class=\"nc-red nc-bold\">allongement</span> et effacement du philtrum</span> (« <span class=\"nc-red nc-bold\">en verre de montre</span> »), <span>lèvre supérieure mince</span>, menton effacé, rétrognathisme</td></tr>\n          <tr><td>Retard des acquisitions</td><td><span class=\"nc-orange_bg\">Troubles cognitifs et comportementaux</span>, retard mental dans formes sévères → handicap</td></tr>\n          <tr><td>Malformations</td><td><span>10-30 %</span> des formes sévères : <span class=\"nc-red_bg\">neurologiques</span> (<span>spina bifida</span>, agénésie corps calleux, hydrocéphalie), <span class=\"nc-red_bg\">cardiaques</span> (CIA, CIV), <span class=\"nc-red_bg\">squelettiques</span> (scoliose), fentes labiopalatines</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"nc-green_bg\">ETCAF</span></strong> (<span class=\"nc-green_bg\">ensemble des troubles causés par l'alcoolisation fœtale</span>) : remplace SAF quand les troubles surviennent <strong>sans retard de croissance ni dysmorphie</strong>, lorsque l'<span class=\"nc-green nc-bold\">alcoolisation est plus modérée</span>. Fréquence ~ <span>5/1000</span>. Manifestations : baisse du QI, retard langage/écriture, agressivité, <span class=\"nc-blue_bg\">hyperactivité</span>, troubles de la motricité fine.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span>alcool</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-38","rang":"B","rubrique":"Physiopathologie","titre":"Alcool et grossesse : mécanisme – relation dose-effet","contenu":"<div class=\"notion-course\"><p>L'atteinte fœtale est liée au <strong>passage rapide de l'<span>alcool</span> à travers le placenta</strong>. Le taux d'<span>alcool</span> fœtal est <strong>quasiment identique</strong> à celui de la mère.</p>\n      <table>\n        <thead><tr><th>Niveau de consommation</th><th>Conséquences fœtales</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Consommation importante</span> (&gt; 2 <span>VS</span>/j)</td><td>Retentissement fœtal documenté : <span>risque de SAF</span></td></tr>\n          <tr><td>Consommation occasionnelle légère/modérée (1-2 <span>VS</span>/j)</td><td><span class=\"nc-green nc-bold\">Pas de syndrome dysmorphique ou malformatif</span> · <span class=\"nc-blue nc-bold\">troubles comportementaux</span>, affectifs et anxieux possibles</td></tr>\n          <tr><td>Binge drinking début de <span>grossesse</span> (≥ <span>4 verres</span> en 1 fois)</td><td><span class=\"nc-green nc-bold\">Pas d'impact démontré si épisode isolé</span> (situation fréquente, <span>grossesse</span> encore inconnue)</td></tr>\n          <tr><td>Binge drinking T2-T3</td><td>Risques de <span><span class=\"nc-red nc-bold\">troubles cognitifs</span></span> par altération de la migration neuronale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Mécanisme central :</strong> atteinte neurologique = arrêts/déviations de la <span>migration neuronale</span> (fin T1 → naissance). <strong><span class=\"nc-green_bg\">Recommandation</span> officielle :</strong> <span><span class=\"nc-green_bg nc-bold\">zéro alcool</span></span> <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span> — <strong>absence d'effet seuil démontré</strong>.</div>\n      <p><span class=\"nc-green_bg\">Rassurer/</span><span class=\"nc-green_bg nc-bold\">déculpabiliser</span> une patiente présentant une alcoolisation légère ou un binge drinking isolé <span class=\"nc-green_bg\">en début de </span><span><span class=\"nc-green_bg\">grossesse</span></span> — l'objectif est de maintenir le lien médecin-patiente, pas d'aggraver la culpabilité.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":1},{"id":"27-39","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Alcool et grossesse : dépistage","contenu":"<div class=\"notion-course\"><p>~ <span>3 %</span> des femmes enceintes consomment de l'<span>alcool</span> de façon épisodique ou régulière en sachant être enceintes. La <span>grossesse</span> est une occasion unique de dépister.</p>\n      <table>\n        <thead><tr><th>Outil</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Interrogatoire</strong> (clé du <span>dépistage</span>)</td><td>À chaque consultation prénatale</td></tr>\n          <tr><td>Auto-questionnaire <span><span class=\"nc-yellow_bg\">T-ACE</span></span></td><td>Meilleure sensibilité que l'interrogatoire seul. <span>Score</span> ≥ <span>2 points</span> = positif. <strong>T</strong>olerance (<span>≥ 3</span> verres = 2 pts), <strong>A</strong>nnoyance, <strong>C</strong>ut-down, <strong>E</strong>ye-opener (1 pt chacun si oui)</td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Dosages biologiques</span></td><td>Sensibilité ~<span>50 %</span> pour alcoolisation excessive (<span>≥ 2</span> verres/j) — peu performants</td></tr>\n          <tr><td>CAT en cas de consommation</td><td>Cadre exempt de jugement · maintenir le lien · aide au <span>sevrage</span> par <span>acamprosate (Aotal®)</span> ; cure, foyer thérapeutique, <span>hospitalisation</span> ; <span>surveillance</span> échographique ; supplémentation B1-B6 si carence <span>folates</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mesures associées :</strong> rechercher autres vulnérabilités (drogues, violence conjugale), PEC sociale, orthophonie/scolarité adaptée pour dépister précocement ETCAF.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-40","rang":"B","rubrique":"Physiopathologie","titre":"Addictologie et grossesse : produits en cause et leurs principaux effets","contenu":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Produit</th><th>Passage</th><th>Effets fœtaux/néonataux</th></tr></thead>\n        <tbody>\n          <tr><td><span>Cannabis (THC)</span></td><td>Liposoluble → barrière placentaire en quelques min · concentration ↑ × 8 dans le lait maternel</td><td><span class=\"nc-red_bg\">RCIU</span> par hypoperfusion placentaire ; consommation régulière (<span>≥ 6</span>×/sem) : prématurité, ↓ poids naissance, <span><span class=\"nc-orange_bg\">syndrome de sevrage néonatal</span></span><span class=\"nc-orange_bg\"> modéré</span> (trémulations) régressif</td></tr>\n          <tr><td><span>Cocaïne</span></td><td>Barrière placentaire + lait maternel</td><td><span><span class=\"nc-orange_bg\">HTA</span></span> + vasoconstriction → <span>FCS, prématurité, RCIU, <span class=\"nc-red_bg\">hydramnios</span>, RPM, HRP ⭐ (RR 4-5)</span> · syndrome d'imprégnation néonatal (hypertonie, trémulations, <span>convulsions</span>) · entérocolites ulcéronécrosantes, <span>infarctus</span> mésentériques</td></tr>\n          <tr><td><span>Opiacés / héroïne</span></td><td>Barrière placentaire + lait maternel</td><td><span>Grossesse</span> à haut risque : <strong>manque maternel</strong> → souffrance fœtale, <span class=\"nc-red nc-bold\">MFIU possible</span> ; FCS, prématurité, <span class=\"nc-orange_bg\">RCIU</span> ; <span>syndrome de sevrage néonatal</span><span> 60 %</span> (<span>J0</span> à J10, durée 1-3 sem)</td></tr>\n          <tr><td>Benzodiazépines</td><td>Barrière placentaire</td><td>Syndrome de <span>sevrage</span> néonatal plus tardif/long, hypotonie, floppy baby</td></tr>\n          <tr><td>Amphétamines / ecstasy / LSD</td><td>—</td><td>Risques mal connus (usage récréatif souvent interrompu à la découverte de <span>grossesse</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Héroïne et <span>opiacés</span> ne sont pas tératogènes</strong> — la gravité vient du manque maternel, des conditions de vie, et du <span>syndrome de sevrage néonatal</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 78 — Addiction aux drogues · 79 — Addiction comportementale</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-41","rang":"A","rubrique":"Diagnostic","titre":"Repérage des conduites addictives et des facteurs de risques associés au cours de la grossesse","contenu":"<div class=\"notion-course\"><p>Le repérage des conduites addictives s'effectue par l'interrogatoire systématique à chaque consultation prénatale, complété par la recherche de <span>facteurs de risque</span> associés.</p>\n      <ul>\n        <li><strong>Interrogatoire</strong> systématique à chaque consultation prénatale : <span>tabac</span>, <span>alcool</span>, cannabis, <span>opiacés</span>, BZD, médicaments détournés</li>\n        <li><strong>Questionnaires validés</strong> : <span><span class=\"nc-yellow_bg\">T-ACE</span></span> (<span>alcool</span>), aide au repérage de la dépendance et du mésusage</li>\n        <li><strong>FR associés à rechercher</strong> : précarité, IST, troubles psychiatriques, antécédents traumatiques, polyconsommations, violences conjugales</li>\n        <li><strong>Mesure objective</strong> : analyseur de CO (<span>tabac</span>), <span class=\"nc-blue_bg\">dosages biologiques</span> (<span>alcool</span>, peu sensibles), <span>dépistage</span> urinaire (cannabis, <span>opiacés</span>) si pertinent</li>\n        <li><strong>Accompagnement multidisciplinaire</strong> : sage-femme + addictologue + psychiatre + travailleur social + PMI</li>\n      </ul>\n      <p>Ressources : <span>CRAT</span> (lecrat.fr) et <span>CRPV</span> pour l'évaluation des risques <span>médicamenteux</span> <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span>.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-42","rang":"B","rubrique":"Prise en charge","titre":"Addictologie et grossesse : aspects essentiels de la prise en charge obstétricale et addictologique","contenu":"<div class=\"notion-course\"><p>Le principe central : <strong>préserver le fœtus de la souffrance du manque</strong> sans imposer un <span>sevrage</span> brutal qui aggraverait le <span>pronostic</span>.</p>\n      <table>\n        <thead><tr><th>Conduite</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span>Sevrage opiacés non recommandé ❌</span></td><td><strong>Déconseillé au T1</strong> (risque FCS) · <strong>déconseillé au T3</strong> (risque <span class=\"nc-orange_bg\">accouchement prématuré</span>) · envisageable au T2 si patiente insistante (long, prudent, risque élevé de rechute)</td></tr>\n          <tr><td>Traitement de substitution <span>opiacés</span> ✅</td><td><span><span class=\"nc-pink_bg\">Méthadone</span></span> (sirop/gélule) <strong>ou</strong> <span><span class=\"nc-pink_bg\">buprénorphine</span></span> (sublingual) — association sans AMM ; doses efficaces pour éviter le manque (souvent augmentées en fin de <span>grossesse</span>)</td></tr>\n          <tr><td>Pluridisciplinarité</td><td>Sage-femme + obstétricien + addictologue + psychiatre + travailleur social ; <span>surveillance</span> échographique renforcée</td></tr>\n          <tr><td>Planification accouchement</td><td>Maternité de niveau adapté, équipe addicto informée à l'avance</td></tr>\n          <tr><td>Médicaments <span>à éviter</span> péri-partum</td><td>BZD et <span>opiacés</span> à courte durée d'action (<span>sevrage</span> néonatal)</td></tr>\n          <tr><td><span>Allaitement</span></td><td>Compatible avec <span><span class=\"nc-pink_bg\">méthadone</span></span>/<span><span class=\"nc-pink_bg\">buprénorphine</span></span> à dose stable (sauf <span>VIH</span> non contrôlé ou cocaïne)</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-43","rang":"B","rubrique":"Prise en charge","titre":"Addictologie et grossesse : accueil de l'enfant","contenu":"<div class=\"notion-course\"><p>L'accueil du nouveau-né de mère addicte impose une <span>surveillance</span> néonatale rigoureuse du <strong>syndrome de <span>sevrage</span></strong>.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Évaluation</td><td><span>Score de Finnegan</span> (ou Lipsitz) toutes les <span>4 h</span> dès la naissance, jusqu'à 3-10 j</td></tr>\n          <tr><td>Survenue</td><td>Délai &lt; 3 j post-naissance (jusqu'à 1-10 j), durée <span>1-3 semaines</span> · fréquence <span>60 %</span> chez nouveau-nés exposés aux <span>opiacés</span>/TSO</td></tr>\n          <tr><td>Symptômes</td><td>Trémulations, hypertonie, hyperréflexie, <span class=\"nc-blue_bg\">troubles du sommeil</span>, pleurs incoercibles, troubles de la succion, <span>hyperthermie</span>, mauvaise courbe pondérale, troubles digestifs</td></tr>\n          <tr><td>Traitement</td><td>Si <strong><span>score</span> &gt; <span <span=\"\">&gt;8</span> lors de 3 évaluations consécutives</strong> : <span><span class=\"nc-pink nc-bold\">chlorhydrate</span> ou <span class=\"nc-pink nc-bold\">sulfate de morphine</span></span> PO (morphinique de remplacement)</td></tr>\n          <tr><td><span>Allaitement</span></td><td>Encouragé si TSO stable (<span><span class=\"nc-pink_bg\">méthadone</span></span>, <span><span class=\"nc-pink_bg\">buprénorphine</span></span>) · CI <span>VIH</span>, cocaïne active</td></tr>\n          <tr><td><span>Suivi</span></td><td>Pédiatrique au long cours · signalement PMI/ASE selon contexte social</td></tr>\n        </tbody>\n      </table>\n      <p>Sévérité du <span>sevrage</span> non corrélée à la posologie du TSO, mais majorée par les co-prises (BZD → sevrage plus tardif et plus long).</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-44","rang":"B","rubrique":"Diagnostic","titre":"Addictologie et grossesse : conséquences à long terme","contenu":"<div class=\"notion-course\"><ul>\n        <li><span>Troubles neurodéveloppementaux</span> : cognition, attention, comportement</li>\n        <li><span>Troubles psychiatriques</span> à l'adolescence et à l'âge adulte</li>\n        <li><span>Vulnérabilité aux addictions</span> chez l'enfant et l'adolescent (transmission psycho-socio-environnementale)</li>\n        <li><span>Troubles de l'attachement</span> et parentalité fragile</li>\n        <li><span class=\"nc-red_bg\">Mort inattendue/subite du nourrisson</span> (<span>tabagisme</span>, polyconsommations)</li>\n        <li>Difficultés scolaires, troubles d'apprentissage (cannabis), <span class=\"nc-blue_bg\">hyperactivité</span>, <span class=\"nc-blue_bg\">troubles du sommeil</span></li>\n      </ul>\n      <p>Le repérage précoce et la mise en place d'un <span>suivi</span> pédiatrique et orthophonique adapté limite le handicap social et fonctionnel à long terme.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span>tabac</span> · 76 — Addiction à l'<span>alcool</span> · 78 — Addiction aux drogues</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0},{"id":"27-45","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes d'action de l'irradiation sur le fœtus","contenu":"<div class=\"notion-course\"><p>L'<span>irradiation</span> fœtale se mesure en <strong><span class=\"nc-pink nc-bold\">milligrays</span> (<span class=\"nc-pink nc-bold\">mGy</span>)</strong>. Deux mécanismes d'action s'opposent : <strong>effets déterministes</strong> (à seuil, mort cellulaire) et <strong>effets stochastiques</strong> (sans seuil, lésions ADN).</p>\n      <table>\n        <thead><tr><th>Mécanisme</th><th>Effets</th><th>Période sensible</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Effets déterministes</strong> (mort cellulaire)</td><td>Dose seuil <span><span class=\"nc-pink nc-bold\">100-200 mGy</span></span> ⭐⭐⭐ — pas de répercussions en-dessous</td><td>SNC le + touché : sensibilité <strong><span class=\"nc-pink nc-bold\">10-27 SA</span></strong></td></tr>\n          <tr><td>Multiplication neuronale</td><td><span class=\"nc-red_bg\">10-17 SA</span> : <span><span class=\"nc-red nc-bold\">diminution sévère du QI</span> (- 30)</span>,<span> 40 %</span> d'arriération mentale (QI &lt; 25) à partir de <span <span=\"\">&gt;1000</span> mGy</td><td>Conséquences : <span class=\"nc-orange_bg\">microcéphalie</span>, <span class=\"nc-orange_bg\">RCIU</span>, <span class=\"nc-orange_bg\">cataracte</span>, ↓ QI</td></tr>\n          <tr><td>Migration neuronale</td><td><span class=\"nc-green_bg\">18-27 SA</span> : <span class=\"nc-green nc-bold\">diminution du QI moins importante</span></td><td><span class=\"nc-yellow_bg\">Relation dose-effet</span> à partir de <span <span=\"\">&gt;<span class=\"nc-pink nc-bold\">500</span></span><span class=\"nc-pink nc-bold\"> mGy</span></td></tr>\n          <tr><td><strong>Effets stochastiques</strong> (lésions ADN)</td><td><strong>Pas de dose seuil ❌</strong> · <span class=\"nc-yellow_bg\">Relation dose-effet</span> ✅ : <span>↑ risque leucémie/cancer × 1,4</span> (<span>40 %</span>)</td><td>Risque brut leucémie/cancer enfant :<span> 0,2-0,3 %</span> →<span> 0,3-0,4 %</span> après <span>irradiation</span> fœtale (reste faible)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Autres organes :</strong> mieux préservés ; à doses très élevées : <span class=\"nc-orange_bg\">RCIU</span>, voire décès in utero (curiethérapie utérine pour cancer du col par exemple).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":0,"liens":[{"href":"https://www.irsn.fr/professionnels-sante/faq-grossesse-exposition-rayonnements-ionisants","label":"IRSN — FAQ grossesse & rayonnements ionisants"}]},{"id":"27-46","rang":"A","rubrique":"Prise en charge","titre":"Irradiation et grossesse : en pratique, ce que l'on peut retenir","contenu":"<div class=\"notion-course\"><p>Le principe directeur : <strong>un examen radiologique justifié n'est jamais une indication d'IMG</strong>. Le « principe de précaution » historique (inquiéter la femme, proposer l'IMG probabiliste) doit être <strong>définitivement abandonné</strong>.</p>\n      <p><strong>Doses fœtales reçues par examen (mGy, moyenne / max) :</strong></p>\n      <table>\n        <thead><tr><th>Examen</th><th>Dose moy</th><th>Dose max</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr><td><span>RP</span>, RX crâne, RX rachis dorsal, RX membres</td><td>&lt; 0,01</td><td>&lt; 0,01</td><td>Utérus hors faisceau · rassurer +++</td></tr>\n          <tr><td>RX abdomen</td><td>1,4</td><td>4,2</td><td>—</td></tr>\n          <tr><td>RX rachis lombaire</td><td>1,7</td><td>10</td><td>—</td></tr>\n          <tr><td><span>TDM</span> thorax</td><td>0,06</td><td>0,96</td><td>Très faible (utérus hors faisceau)</td></tr>\n          <tr><td><span>TDM</span> tête</td><td>0,005</td><td>0,005</td><td>Négligeable</td></tr>\n          <tr><td><span>TDM</span> abdomen</td><td>8,0</td><td>49</td><td>Utérus dans le faisceau</td></tr>\n          <tr><td><span>TDM</span> bassin</td><td>25</td><td>79</td><td>Dose la + élevée des examens diagnostiques</td></tr>\n          <tr><td>Lavement baryté</td><td>6,8</td><td>24</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Aucun examen radiologique diagnostique standard ne dépasse <span <span=\"\">&gt;100</span> mGy</strong> — la limite déterministe. Seules les <span>situations exceptionnelles</span> (scopie prolongée, curiethérapie, <span>radiothérapie</span> pelvienne) peuvent y conduire.</div>\n      <p><strong>Principes pratiques (ALARA) :</strong></p>\n      <ul>\n        <li>Demander systématiquement à toute femme en âge de procréer si elle est enceinte avant un examen radiologique</li>\n        <li>Privilégier les <span>examens non irradiants</span> : <strong><span>échographie</span></strong>, <strong><span>IRM</span></strong> sans gadolinium (T1)</li>\n        <li><span>Tablier de plomb</span> sur l'abdomen pour limiter la dose à l'utérus</li>\n        <li>Limiter le nombre de clichés et le temps de scopie au strict nécessaire</li>\n        <li><strong>Ne pas contre-indiquer un examen radiographique uniquement pour la <span>grossesse</span></strong> : balance bénéfice/risque souvent favorable</li>\n        <li><span>Iode 131 radioactif CI absolue</span> ⚠️ (détruit thyroïde fœtale)</li>\n        <li><span>Radiothérapie CI</span> (doses très élevées) ; en cas d'exposition involontaire → calcul dose-gonades avec IRSN, avis CPDPN</li>\n      </ul>\n      <p><strong>Médecine du travail :</strong> exposition de l'enfant à naître <strong>&lt; 1 mSv</strong> entre la déclaration et l'accouchement. Femme allaitante : pas de poste à risque de contamination interne.</p>\n      <p><strong>Découverte de <span>grossesse</span> après examen :</strong> si utérus hors faisceau (crâne, thorax, membres) → rassurer ; si utérus dans le faisceau (UIV, hystéro, <span>TDM</span> pelvien) → en standard, rassurer (dose exceptionnellement &gt; <span <span=\"\">&gt;100</span> mGy) ; si examen inhabituel → avis service compétent (radiologue, IRSN).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 333 — Situations sanitaires exceptionnelles</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Grossesse et VIH, 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Herpès et grossesse, 2017</a></li></ul></details>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-etio\">VIH</span> — <span class=\"q\">charge <span class=\"kw-etio\">virale</span> <span class=\"kw-chiffre\">≥ 400</span> copies/mL à l'accouchement</span></strong></p><p>Objectif : <span class=\"kw-clinique\">CV indétectable</span> (<span class=\"kw-chiffre\">&lt; 50 copies/mL</span>) avant l'accouchement — <span class=\"kw-chiffre\">TMF de 20 % sans ARV → 0,3–0,6 %</span> avec trithérapie efficace</p><ul><li><span class=\"kw-alerte\">CV ≥ 400 copies/mL</span> (CD4 bas, traitement tardif ou non pris) : <span class=\"kw-ttt\">césarienne programmée</span> + <span class=\"kw-ttt\">perfusion prophylactique de zidovudine (AZT)</span></li><li>Gestes <span class=\"kw-ci\">contre-indiqués</span> en salle de naissance : <span class=\"kw-ci\">pH au scalp</span>, <span class=\"kw-ci\">électrode au scalp</span>, <span class=\"kw-ci\">tocométrie interne</span></li></ul><p><strong><span class=\"kw-def\">Allo-immunisation</span> — <span class=\"q\">anémie fœtale sévère</span></strong></p><p><span class=\"kw-ttt\">Transfusion in utero</span> répétée (sang O− déplasmatisé, lavé, irradié) ou <span class=\"kw-ttt\">exsanguinotransfusion in utero</span> (évite la surcharge volémique)</p><ul><li><span class=\"kw-alerte\">Tracé sinusoïdal</span> au <span class=\"kw-imagerie\">RCF</span> = <span class=\"kw-alerte\">anémie fœtale sévère</span>, <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-alerte\">Anasarque fœtale</span> (Hb &lt; <span class=\"kw-chiffre\">5 g/dL</span>) : épanchements des séreuses, ascite</li></ul><p><strong><span class=\"kw-etio\">Grippe</span> grave chez la femme enceinte</strong></p><p><span class=\"kw-ttt\">Oseltamivir</span> curatif débuté <span class=\"kw-chiffre\">&lt; 48h</span> après les 1ᵉʳˢ signes + <span class=\"kw-ttt\">hospitalisation</span> en cas de <span class=\"kw-alerte\">signes de gravité</span> (précautions gouttelettes <span class=\"kw-chiffre\">7 jours</span>)</p><ul><li><span class=\"kw-alerte\">Signes de gravité</span> : <span class=\"kw-alerte\">atteintes fonctions supérieures</span>, <span class=\"kw-chiffre\">FR &gt; 30</span>, <span class=\"kw-chiffre\">PAS &lt; 90</span>, <span class=\"kw-chiffre\">FC &gt; 120</span></li><li>Risque accru d'<span class=\"kw-alerte\">hospitalisation en réanimation</span> pour atteintes respiratoires graves (notamment aux 2ᵉ et 3ᵉ trimestres)</li></ul>","hospit":"<p><strong>Listériose</strong></p><p><span class=\"kw-ttt\">Antibiothérapie démarrée dès la suspicion</span> (confirmation non requise) : <span class=\"kw-ttt\">amoxicilline</span> puis <span class=\"kw-ttt\">biantibiothérapie parentérale amoxicilline + aminoside ≥ 5 jours</span>, relais per os jusqu'à l'accouchement</p><ul><li>Tableau : <span class=\"kw-clinique\">syndrome pseudo-grippal fébrile</span> + <span class=\"kw-clinique\">perte liquidienne vaginale épaisse/teintée</span> (travail prématuré fébrile)</li><li><span class=\"kw-alerte\">Mortalité néonatale élevée (50–75 %)</span> si non traitée</li></ul><p><strong><span class=\"kw-def\">Allo-immunisation</span> — <span class=\"q\">anémie fœtale documentée</span></strong></p><p>Transfert en <span class=\"kw-ttt\">centre de médecine fœtale</span> / maternité de niveau III</p><ul><li><span class=\"kw-imagerie\">Doppler de l'artère cérébrale moyenne (ACM)</span> : <span class=\"kw-alerte\">Vmax &gt; 1,5 MoM</span> pour l'âge gestationnel = signe d'anémie fœtale → indiquer la <span class=\"kw-ttt\">transfusion in utero</span></li><li>Si <span class=\"kw-chiffre\">&lt; 34 SA</span> : possibilité de <span class=\"kw-ttt\">transfusions fœtales répétées</span> toutes les <span class=\"kw-chiffre\">3 semaines</span> ; si terme raisonnable : <span class=\"kw-ttt\">accouchement prématuré induit</span> (AVB ou césarienne) + <span class=\"kw-ttt\">corticothérapie</span></li></ul><p><strong>Toxoplasmose — <span class=\"q\">séroconversion confirmée</span></strong></p><p><span class=\"kw-bio\">PCR</span> sur amniocentèse réalisée <span class=\"kw-chiffre\">≥ 16–18 SA</span> et <span class=\"kw-chiffre\">4 semaines</span> après la date d'infection maternelle estimée</p><ul><li>Orientation vers <span class=\"kw-def\">CPDPN</span> (Centre Pluridisciplinaire de Diagnostic Prénatal) pour décision de prise en charge</li><li><span class=\"kw-imagerie\">Échographies mensuelles</span> à la recherche de <span class=\"kw-clinique\">dilatation ventriculaire</span>, <span class=\"kw-clinique\">hydrocéphalie</span>, <span class=\"kw-clinique\">calcifications intracrâniennes</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Vmax ACM &gt; 1,5 MoM</span> à l'<span class=\"kw-imagerie\">Doppler de l'artère cérébrale moyenne</span> — signe d'anémie fœtale (allo-immunisation)</li><li><span class=\"kw-alerte\">Tracé sinusoïdal</span> au <span class=\"kw-imagerie\">RCF</span> ou <span class=\"kw-alerte\">anasarque fœtale</span> — anémie très sévère, <span class=\"kw-alerte\">urgence</span> transfusionnelle</li><li><span class=\"kw-alerte\">CV VIH ≥ 400 copies/mL</span> à l'accouchement — <span class=\"kw-def\">TMF</span> élevée, césarienne + <span class=\"kw-ttt\">AZT</span> en perfusion</li><li>Toxoplasmose : <span class=\"kw-imagerie\">PCR amniotique positive</span> + <span class=\"kw-imagerie\">anomalies échographiques</span> — fœtopathie sévère, discuter <span class=\"kw-def\">IMG</span> au CPDPN</li><li><span class=\"kw-etio\">Cocaïne</span> en cours de <span class=\"kw-ci\">grossesse</span> → <span class=\"kw-alerte\">hématome rétroplacentaire (HRP)</span> dans les suites immédiates de la prise (RR 4–5)</li><li><span class=\"kw-etio\">Grippe</span> : <span class=\"kw-alerte\">FR &gt; 30</span>, <span class=\"kw-alerte\">PAS &lt; 90</span>, <span class=\"kw-alerte\">FC &gt; 120</span> — atteinte respiratoire grave, <span class=\"kw-alerte\">hospitalisation</span></li></ul>","principes":"<p>Pour chaque risque fœtal, la PEC repose sur <strong><span class=\"kw-def\">prévention primaire</span> (éviction, vaccination, hygiène), dépistage sérologique adapté, et traitement ciblé</strong> selon le germe ou l'agent en cause.</p><p><strong><span class=\"kw-etio\">VIH</span></strong></p><ul><li>Traitement ARV de toute femme enceinte : <span class=\"kw-ttt\">2 INTI + 1 IP</span> (schéma le plus efficace)</li><li><span class=\"kw-ci\">Éfavirenz contre-indiqué au 1ᵉʳ trimestre</span></li><li>Instauration au plus tard <span class=\"kw-chiffre\">avant fin du 2ᵉ trimestre</span> si CV négative ; dès que possible (<span class=\"kw-chiffre\">avant 26 SA</span>) si CV positive ou séropositivité découverte en cours de <span class=\"kw-ci\">grossesse</span></li><li>Traitement du nouveau-né : <span class=\"kw-ttt\">zidovudine (AZT)</span> per os <span class=\"kw-chiffre\">4 semaines</span> si bilan satisfaisant ; trithérapie si prématurité ou CV élevée</li></ul><p><strong><span class=\"kw-def\">Allo-immunisation anti-D</span> — prévention</strong></p><ul><li>Femme <span class=\"kw-chiffre\">RhD−</span>, <span class=\"kw-bio\">RAI</span> négative, fœtus <span class=\"kw-chiffre\">RhD+</span> : <span class=\"kw-ttt\">Rhophylac 300 µg</span> à <span class=\"kw-chiffre\">28 SA</span> (prophylaxie systématique)</li><li>Prophylaxie ciblée dans les <span class=\"kw-chiffre\">&lt; 72h</span> de tout événement à risque de passage de GR fœtales (métrorragies, amniocentèse, VME…)</li><li><span class=\"kw-bio\">RAI</span> de contrôle : <span class=\"kw-chiffre\">M6</span>, <span class=\"kw-chiffre\">M8</span> et <span class=\"kw-chiffre\">M9</span> chez les femmes <span class=\"kw-chiffre\">RhD−</span></li></ul><p><strong>Toxoplasmose — séroconversion prouvée</strong></p><ul><li><span class=\"kw-bio\">PCR</span> amniotique négative, échographies normales : <span class=\"kw-ttt\">spiramycine</span> maintenue jusqu'à l'accouchement + <span class=\"kw-imagerie\">suivi échographique mensuel</span></li><li><span class=\"kw-bio\">PCR</span> amniotique positive : arrêt spiramycine → <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span> jusqu'à l'accouchement (traitement parasiticide in utero)</li><li><span class=\"kw-imagerie\">Surveillance NFS hebdomadaire</span> sous pyriméthamine-sulfadiazine (hématotoxicité ; risque de <span class=\"kw-alerte\">syndrome de Lyell</span> maternel)</li></ul><p><strong>Listériose</strong></p><ul><li>Dès la suspicion : <span class=\"kw-ttt\">amoxicilline</span> seule (ou <span class=\"kw-ttt\">érythromycine</span> si <span class=\"kw-ci\">allergie</span>)</li><li>Si confirmée : <span class=\"kw-ttt\">amoxicilline parentérale <span class=\"kw-chiffre\">10 jours</span> + aminoside <span class=\"kw-chiffre\">5 jours</span></span>, puis relais oral <span class=\"kw-ttt\">amoxicilline ≥ 4 semaines</span> jusqu'à l'accouchement</li></ul><p><strong>Médicaments tératogènes / fœtotoxiques</strong></p><ul><li>Consultation <span class=\"kw-def\">préconceptionnelle</span> obligatoire pour toute pathologie chronique (adapter le traitement avant <span class=\"kw-ci\">grossesse</span>)</li><li>Référence : <span class=\"kw-def\">CRAT</span> (Centre de Référence sur les Agents Tératogènes) pour évaluation du risque</li><li><span class=\"kw-ci\">AINS contre-indiqués à partir de 24 SA</span> (fermeture prématurée du canal artériel, <span class=\"kw-alerte\">HTAP fœtale</span>, oligo-amnios)</li><li><span class=\"kw-ci\">IEC/sartans contre-indiqués aux 2ᵉ et 3ᵉ trimestres</span> (atteinte rénale fœtale)</li></ul><p><strong><span class=\"kw-clinique\">Irradiation</span></strong></p><ul><li>Privilégier les <span class=\"kw-imagerie\">examens non irradiants</span> (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">IRM</span>) pendant la <span class=\"kw-ci\">grossesse</span></li><li>Examens de radiodiagnostic standard : <span class=\"kw-chiffre\">dose fœtale &lt;&lt; 100 mGy</span> → pas d'effet déterministe (seuil <span class=\"kw-chiffre\">100–200 mGy</span>)</li><li>Si l'utérus est hors du faisceau (thorax, crâne, membres) : <span class=\"kw-ttt\">tablier de plomb</span> suffisant, examen réalisable</li><li><span class=\"kw-ci\">Iode 131 totalement proscrit</span> (détruirait la thyroïde fœtale) ; <span class=\"kw-ci\">radiothérapie contre-indiquée</span></li></ul>","suivi":"<p><strong><span class=\"kw-etio\">VIH</span></strong></p><ul><li><span class=\"kw-bio\">Charge virale VIH</span> + <span class=\"kw-bio\">NFS-plaquettes</span> + <span class=\"kw-bio\">transaminases</span> + <span class=\"kw-bio\">créatininémie</span> : <span class=\"kw-def\">suivi</span> <strong>mensuel</strong></li><li><span class=\"kw-bio\">Lymphocytes CD4</span> : <span class=\"kw-def\">suivi</span> trimestriel</li><li>Nouveau-né : <span class=\"kw-bio\">PCR VIH</span> à la <span class=\"kw-chiffre\">naissance</span>, <span class=\"kw-chiffre\">M1</span>, <span class=\"kw-chiffre\">M3</span>, <span class=\"kw-chiffre\">M6</span> (<span class=\"kw-bio\">sérologies</span> inutilisables — AC maternels présents)</li></ul><p><strong><span class=\"kw-def\">Allo-immunisation</span></strong></p><ul><li>Femme <span class=\"kw-chiffre\">RhD−</span> : <span class=\"kw-bio\">RAI</span> à <span class=\"kw-chiffre\">M6</span>, <span class=\"kw-chiffre\">M8</span>, <span class=\"kw-chiffre\">M9</span></li><li>Si <span class=\"kw-bio\">RAI</span> positive et fœtus <span class=\"kw-ttt\">RhD</span>+ : <span class=\"kw-imagerie\">Doppler ACM</span> tous les <span class=\"kw-chiffre\">15 jours</span> (Vmax — seuil d'alerte <span class=\"kw-chiffre\">&gt; 1,5 MoM</span>)</li><li><span class=\"kw-imagerie\">Titrage des AC</span> + <span class=\"kw-bio\">dosage pondéral</span> répétés régulièrement pour dépister une réactivation brutale</li></ul><p><strong>Toxoplasmose (femme non immune)</strong></p><ul><li><span class=\"kw-bio\">Sérologie toxoplasmose mensuelle (IgM + IgG)</span> obligatoire tout au long de la <span class=\"kw-ci\">grossesse</span> chez la femme séronégative</li><li>Si séroconversion : spiramycine précoce + orientation CPDPN + <span class=\"kw-imagerie\">échographies mensuelles</span> (puis bimensuelles si <span class=\"kw-bio\">PCR</span>+ )</li><li>Après la naissance (même si <span class=\"kw-bio\">PCR</span> négative) : <span class=\"kw-imagerie\">fond d'œil</span> + <span class=\"kw-imagerie\">échographie transfontanellaire</span> + <span class=\"kw-def\">suivi</span> sérologique jusqu'à disparition des IgG maternels (<span class=\"kw-chiffre\">4–6 mois</span>)</li></ul>"},"liensGlobaux":[{"href":"https://www.irsn.fr/professionnels-sante/faq-grossesse-exposition-rayonnements-ionisants","label":"irsn.fr"},{"href":"https://www.lecrat.fr","label":"lecrat.fr"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi","label":"HAS · Dépistage du CMV et prise en charge, 2026"},{"href":"https://cngof.fr/app/uploads/2025/11/Allo-immunisation20-20RhC3A9sus20D202024-Prevention20de20l27allo-immunisation20anti20RH1.pdf","label":"CNGOF · Prévention de l’allo-immunisation RhD au premier trimestre, 2024"},{"href":"https://www.has-sante.fr/jcms/p_3518878/fr/grossesse-et-vih-desir-d-enfant-soins-de-la-femme-enceinte-et-prevention-de-la-transmission-mere-enfant","label":"HAS · Grossesse et VIH, 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/herpes-grossesse-201720RPC.pdf","label":"CNGOF · Herpès et grossesse, 2017"}],"cards":[{"i":"7c60cbc5ba61","n":27,"o":"27-1","u":"Définition","t":"Connaître la définition de l'infection materno-fœtale (IMF)","q":"Que retenir concernant la définition de l'infection materno-fœtale (IMF) ?","a":"<div class=\"notion-course\"><p>L'<span>infection materno-fœtale (IMF)</span> est une infection contractée par le fœtus ou le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> à partir de germes d'origine maternelle, transmise au cours de la <span><span class=\"nc-green_bg\">grossesse</span></span>, à l'accouchement ou en post-partum immédiat.</p>\n      <table>\n        <thead><tr><th>Période</th><th>Mode</th><th>Conséquences possibles</th></tr></thead>\n        <tbody>\n          <tr><td>Anténatale</td><td>Passage transplacentaire hématogène</td><td><span><span class=\"nc-red_bg\">Embryopathie</span></span>, fœtopathie, <span>MFIU</span>, <span class=\"nc-red nc-bold\">fausse couche</span></td></tr>\n          <tr><td>Per-partum</td><td>Voie ascendante (filière génitale) ou contact direct</td><td><span class=\"nc-red\">Chorioamniotite</span>, <span class=\"nc-red_bg\">accouchement prématuré</span>, <span class=\"nc-red_bg\">infection néonatale</span> précoce</td></tr>\n          <tr><td>Post-natale</td><td><span>Allaitement</span>, contact</td><td><span class=\"nc-red_bg\">Infection néonatale</span> tardive (symptomatique d'emblée ou à distance)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Fréquence :</strong> <span><span class=\"nc-pink nc-bold\">1 à 4 %</span></span> des naissances toutes infections confondues, <span>2 à 4 ×</span> plus chez les prématurés.</div>\n      <p>Toute infection fébrile chez la femme enceinte peut, de façon non spécifique, être responsable d'une <span><span class=\"nc-red nc-bold\">fausse couche</span> spontanée</span>, même sans atteinte directe du tissu embryonnaire.</p></div>"},{"i":"26b36b873d8a","n":27,"o":"27-2","u":"Epidémiologie","t":"Connaître l'épidémiologie \"microbienne\" des IMF","q":"Que retenir concernant l'épidémiologie \"microbienne\" des IMF ?","a":"<div class=\"notion-course\"><p>Les germes responsables d'IMF se répartissent en <span <span=\"\">&gt;3</span> grandes familles. Le profil microbien dépend de la voie de contamination.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Germes principaux</th><th>Voie dominante</th></tr></thead>\n        <tbody>\n          <tr><td>Bactéries</td><td><span>Listeria monocytogenes</span>, <span><span class=\"nc-purple_bg\">Streptococcus agalactiae</span></span> (SGB), <span>Escherichia coli</span>, <span>syphilis</span>, <span>tuberculose</span>, <span>fièvre</span> Q</td><td>Hématogène (<span>Listeria</span>) · ascendante (SGB, <span>E. coli</span>) · transplacentaire (<span>syphilis</span>)</td></tr>\n          <tr><td>Parasites</td><td><span>Toxoplasma gondii</span>, paludisme</td><td>Hématogène transplacentaire</td></tr>\n          <tr><td>Virus</td><td><span>Grippe</span>, <span>hépatite</span> B, <span>HSV</span>, varicelle, rubéole, CMV, VIH, parvovirus B19, Zika</td><td>Hématogène (rubéole, <span>CMV</span>, parvo, toxo, VIH) · per-partum (HSV, VHB, VIH)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span> · 162 — IST · 167 — Hépatites virales · 168 — Herpesvirus · 169 — <span>VIH</span> · 170 — Paludisme · 173 — Zoonose</em></p></div>"},{"i":"fedb73949cb7","n":27,"o":"27-3","u":"Physiopathologie","t":"Connaître les principaux mécanismes des IMF","q":"Que retenir concernant les principaux mécanismes des IMF ?","a":"<div class=\"notion-course\"><p>Trois voies de contamination structurent la <span>physiopathologie</span> des IMF — le piège QCM est de relier la voie au germe et à la conséquence attendue.</p>\n      <table>\n        <thead><tr><th>Voie</th><th>Mécanisme</th><th>Germes typiques</th><th>Conséquences ⚠️</th></tr></thead>\n        <tbody>\n          <tr><td>Hématogène <span class=\"nc-orange_bg\">transplacentaire</span></td><td>Bactériémie/virémie maternelle → passage placentaire</td><td><span>Listeria</span>, <span>CMV</span>, rubéole, toxo, parvovirus B19, <span>syphilis</span></td><td><span>Atteinte fœtale</span> (embryo/fœtopathie)</td></tr>\n          <tr><td>Ascendante cervico-vaginale</td><td>Germes de la filière génitale → membranes</td><td>SGB, <span>E. coli</span>, <span>vaginose</span></td><td><span><span class=\"nc-orange_bg\">MAP</span></span>, <span class=\"nc-orange_bg\">chorioamniotite</span>, <span class=\"nc-red nc-bold\">fausse couche</span> tardive</td></tr>\n          <tr><td>Per-partum / post-natale</td><td>Contact filière génitale ou <span><span class=\"nc-brown_bg\">allaitement</span></span></td><td>SGB, <span>HSV</span>, VHB, VIH, CMV</td><td><span class=\"nc-red_bg\">Infection néonatale</span> précoce ou tardive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège QCM :</strong> distinguer la <span>fenêtre embryonnaire</span> (<span>J0</span>–J56, organogenèse, malformations structurelles) de la <span>fenêtre fœtale</span> (&gt; J56, atteinte fonctionnelle et croissance). L'évocation devant un point d'appel maternel (<span>fièvre</span>) <em>ou</em> fœtal (signe échographique, altération du bien-être) est <span class=\"nc-red nc-bold\">obligatoire</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span> · 162 — IST</em></p></div>"},{"i":"b13c2e536d6c","n":27,"o":"27-4","u":"Définition","t":"Toxoplasmose : connaître les conséquences de l'IMF","q":"Que retenir concernant toxoplasmose : connaître les conséquences de l'IMF ?","a":"<div class=\"notion-course\"><p>La toxoplasmose <span>congénitale</span> résulte de la <span><span class=\"nc-red nc-bold\">primo-infection</span> maternelle</span> pendant la <span><span class=\"nc-green_bg\">grossesse</span></span> (<span>1-2 %</span> des grossesses, 4000-5000 femmes/an en France).</p>\n      <table>\n        <thead><tr><th>Période</th><th>Risque transmission</th><th>Sévérité fœtale</th></tr></thead>\n        <tbody>\n          <tr><td>Périconceptionnelle (0-7 SA)</td><td><span>1 %</span></td><td>Embryopathie/fœtopathie sévère <span>60 %</span> (avortement, MFIU)</td></tr>\n          <tr><td>Jusqu'à 13 SA</td><td><span>5 %</span></td><td>Lésions sévères</td></tr>\n          <tr><td>2ᵉ trimestre</td><td><span>40 %</span></td><td>Fœtopathie ou forme infraclinique <span>25 %</span></td></tr>\n          <tr><td>3ᵉ trimestre</td><td><span>70 %</span></td><td><span class=\"nc-blue_bg\">Formes sérologiques pures</span> ou choriorétinite <span>9 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations chez l'enfant contaminé :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-green_bg\">Atteinte infraclinique</span></span> :<span> 70 %</span></li>\n        <li><span><span class=\"nc-green_bg\">Forme légère</span></span> :<span> 25 %</span></li>\n        <li><span>Forme grave</span> (&lt; 5 %) : <span><span class=\"nc-red nc-bold\">microcéphalie</span></span>, <span><span class=\"nc-red nc-bold\">hydrocéphalie</span></span>, <span><span class=\"nc-red nc-bold\">calcifications intracrâniennes</span></span>, <span>choriorétinite</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Paradoxe à retenir :</strong> le <span class=\"nc-yellow_bg\">risque de transmission augmente avec le terme</span>, mais la sévérité décroît — l'infection T1 est rare mais dévastatrice, l'infection T3 est fréquente mais souvent infraclinique.</div></div>"},{"i":"8bec67c3aafd","n":27,"o":"27-5","u":"Prise en charge","t":"Toxoplasmose : connaître les modalités de surveillance d'une femme enceinte séronégative pour la toxoplasmose","q":"Que retenir concernant toxoplasmose : connaître les modalités de surveillance d'une femme enceinte séronégative pour la toxoplasmose ?","a":"<div class=\"notion-course\"><p>La <span>sérologie toxoplasmose</span> est <strong><span class=\"nc-red nc-bold\">obligatoire</span> au 1ᵉʳ trimestre</strong> (1ʳᵉ consultation) chez toute femme enceinte. <span>45-50 %</span> des femmes enceintes en France sont séronégatives.</p>\n      <table>\n        <thead><tr><th>Statut</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Femme immune (IgG+)</td><td>Aucune <span>surveillance</span>, aucune précaution</td></tr>\n          <tr><td>Femme non-immune</td><td><strong><span>Prévention primaire</span></strong> (conseils alimentaires/chats — voir obj-5) + <strong><span>prévention secondaire</span> <span class=\"nc-red nc-bold\">obligatoire</span></strong> : <span>sérologie mensuelle</span> (IgM, IgG) jusqu'à 3 sem après l'accouchement</td></tr>\n        </tbody>\n      </table>\n      <p><strong>CAT en cas de séroconversion :</strong></p>\n      <ul>\n        <li>Orientation <span>CPDPN</span> (Centre Pluridisciplinaire de Diagnostic Prénatal)</li>\n        <li><span class=\"nc-pink_bg\">Traitement précoce par</span> <span><span class=\"nc-pink_bg nc-bold\">spiramycine</span></span> <span>9 MUI/j</span> (prophylactique, diminue le risque de transmission, bien toléré)</li>\n        <li><span><span class=\"nc-blue_bg\">PCR sur amniocentèse</span></span> à partir de <span><span class=\"nc-pink nc-bold\">≥ 16</span></span><span class=\"nc-pink nc-bold\">-18 SA</span>, réalisée ≥ <span><span class=\"nc-pink nc-bold\">4 semaines</span></span><span class=\"nc-pink nc-bold\"> après la date d'infection maternelle</span></li>\n        <li>Si <span>PCR</span> + : relais par <span><span class=\"nc-pink_bg\">pyriméthamine + sulfadiazine + acide folinique</span></span> <span class=\"nc-pink_bg nc-bold\">jusqu'à l'accouchement</span></li>\n        <li>Échographies <span>mensuelles</span> ciblées (recherche dilatation ventriculaire, <span class=\"nc-red nc-bold\">hydrocéphalie</span>, calcifications intra-crâniennes)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Pas de vaccin :</strong> il n'existe pas de vaccin contre la toxoplasmose.</div>\n      </div>"},{"i":"879dbd9cb2f5","n":27,"o":"27-6","u":"Prise en charge","t":"Toxoplasmose : connaître les principaux conseils de prévention de la toxoplasmose","q":"Que retenir concernant toxoplasmose : connaître les principaux conseils de prévention de la toxoplasmose ?","a":"<div class=\"notion-course\"><p>Chez la femme enceinte <strong>séronégative</strong>, les <span class=\"nc-green_bg\">conseils de </span><span><span class=\"nc-green_bg\">prévention</span> primaire</span> sont remis par écrit dès le 1ᵉʳ trimestre.</p>\n      <ul>\n        <li><span>Viande bien cuite</span> (<span>≥ 67-72 °C</span> à cœur) ou congelée (-<span <span=\"\">&gt;18</span> °C) ; éviter charcuterie crue (jambon cru, saucisson, viande fumée)</li>\n        <li><span>Laver soigneusement</span> fruits, légumes, herbes aromatiques (terre potentiellement contaminée)</li>\n        <li>Éviter le <span>contact avec la litière des chats</span> ; si inévitable : <span>port de gants</span> + désinfection à l'eau bouillante quotidienne</li>\n        <li><span>Lavage des mains</span> systématique après jardinage, manipulation de terre, manipulation de viande crue</li>\n        <li>Éviter <span class=\"nc-red_bg\">coquillages crus</span>, <span class=\"nc-red_bg\">surimi</span>, <span class=\"nc-red_bg\">tarama</span></li>\n        <li>Conserver aliments crus séparés des aliments cuits/prêts à consommer</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong><span>Activité physique adaptée</span> :</strong><span> <span class=\"nc-pink nc-bold\">30 min</span></span>, 3 à 5 ×/semaine — recommandation HAS.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span>Grossesse</span> normale · 24 — Complications de la grossesse · 173 — Zoonose</em></p></div>"},{"i":"58352f4105ba","n":27,"o":"27-7","u":"Suivi et/ou pronostic","t":"Connaître les conséquences d'une rubéole au cours de la grossesse","q":"Que retenir concernant les conséquences d'une rubéole au cours de la grossesse ?","a":"<div class=\"notion-course\"><p>La rubéole maternelle est <strong>grave</strong> chez la <span class=\"nc-orange nc-bold\">femme enceinte non immunisée</span> — le virus est <span><span class=\"nc-red nc-bold\">tératogène</span></span>. <span><span class=\"nc-pink_bg\">5-10 %</span></span><span class=\"nc-pink_bg\"> des femmes enceintes</span> ne sont <span class=\"nc-pink_bg\">pas immunisées</span> en France (<span class=\"nc-pink nc-bold\">&lt; 40 cas/an</span>).</p>\n      <table>\n        <thead><tr><th>Âge gestationnel</th><th>Risque de malformation</th></tr></thead>\n        <tbody>\n          <tr><td>0-8 SA</td><td><span>85 %</span></td></tr>\n          <tr><td>9-12 SA</td><td><span>52 %</span></td></tr>\n          <tr><td>13-20 SA</td><td><span>16 %</span></td></tr>\n          <tr><td><span>&gt; 20</span> SA</td><td><span>0 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 tableaux cliniques (rubéole <span>congénitale</span>) :</strong></p>\n      <ul>\n        <li><span>Syndrome malformatif (triade de Gregg)</span> : <span><span class=\"nc-red_bg\">RCIU</span></span>, MFIU, FCS ; atteinte neurosensorielle (<span><span class=\"nc-red_bg\">surdité</span></span>, <span class=\"nc-red_bg\">microcéphalie</span>, <span class=\"nc-red_bg\">retard psychomoteur</span>) ; atteinte cardiaque (<span>CIV, CIA, PCA</span>, sténose artère pulmonaire) ; atteinte oculaire (<span><span class=\"nc-orange_bg\">cataracte</span></span>, <span class=\"nc-orange_bg\">microphtalmie</span>, <span class=\"nc-orange_bg\">rétinopathie pigmentaire</span>, <span class=\"nc-orange_bg\">glaucome</span>)</li>\n        <li><span>Rubéole congénitale évolutive</span> : infection chronique persistante (nouveau-né très contagieux) — <span class=\"nc-red nc-bold\">RCIU</span>, <span><span class=\"nc-orange nc-bold\">purpura</span></span><span class=\"nc-orange nc-bold\"> thrombopénique</span>, <span>hépatosplénomégalie</span>, <span><span class=\"nc-blue_bg\">ictère</span></span>, <span><span class=\"nc-orange nc-bold\">convulsions</span></span>, <span class=\"nc-blue_bg nc-bold\">anomalies osseuses</span> <span class=\"nc-blue_bg\">radiologiques</span> ; <span>pronostic</span> psychomoteur réservé</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p></div>"},{"i":"291bf7e3a070","n":27,"o":"27-8","u":"Prise en charge","t":"Rubéole : connaître les éléments de la prévention fœtale","q":"Que retenir concernant rubéole : connaître les éléments de la prévention fœtale ?","a":"<div class=\"notion-course\"><p>La prévention de la rubéole <span>congénitale</span> repose sur deux axes complémentaires — primaire (vaccination) et secondaire (<span><span class=\"nc-blue_bg\">dépistage</span></span> sérologique).</p>\n      <table>\n        <thead><tr><th>Type</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Prévention primaire</span></strong></td><td><span>Vaccination ROR</span> des femmes non immunisées <strong>en âge de procréer</strong> ; vaccination des enfants (calendrier vaccinal) ; femme enceinte séronégative vaccinée en <strong>post-partum</strong> (vaccin vivant atténué <span>CI pendant la grossesse</span>)</td></tr>\n          <tr><td><strong><span>Prévention secondaire</span></strong></td><td><span>Sérologie IgG</span> <span class=\"nc-red nc-bold\">obligatoire</span> à la 1ʳᵉ consultation (sauf immunité antérieure documentée) ; si négative : contrôle <strong>mensuel jusqu'à <span class=\"nc-pink nc-bold\">18-20 SA</span></strong> (au-delà, risque très faible)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>CAT séroconversion T1 :</strong> avis CPDPN — <span><span class=\"nc-pink nc-bold\">autorisation d'IMG possible</span></span> si demande du couple. Si refus <span class=\"nc-pink nc-bold\">IMG</span> : diagnostic anténatal par <span>amniocentèse</span> (<span><span class=\"nc-pink nc-bold\">≥ 18</span></span><span class=\"nc-pink nc-bold\"> SA</span> et ≥ 4 sem <span class=\"nc-pink nc-bold\">après</span> séroconversion) + <span><span class=\"nc-blue nc-bold\">surveillance</span></span><span class=\"nc-blue nc-bold\"> échographique</span> mensuelle. <strong>Pas de <span class=\"nc-yellow_bg\">traitement curatif</span> disponible.</strong></div>\n      <p>Délai de contraception après vaccin ROR : <span>≥ 1 mois</span> (vaccin vivant).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p></div>"},{"i":"f474d708ad92","n":27,"o":"27-9","u":"Définition","t":"Connaître la définition de la rougeole materno-fœtale","q":"Que retenir concernant la définition de la rougeole materno-fœtale ?","a":"<div class=\"notion-course\"><p>La <span>rougeole materno-fœtale</span> désigne l'infection rougeoleuse contractée par la femme enceinte avec possible transmission au fœtus ou au <span class=\"nc-blue_bg nc-bold\">nouveau-né</span>. La rougeole est rare pendant la <span><span class=\"nc-green_bg\">grossesse</span></span> mais grave.</p>\n      <table>\n        <thead><tr><th>Mode</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Transmission placentaire</td><td>Passage hématogène transplacentaire</td></tr>\n          <tr><td>Transmission néonatale précoce</td><td>Voie aérienne en per-partum / post-natal immédiat</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pas d'effet <span><span class=\"nc-red nc-bold\">tératogène</span></span> :</strong> contrairement à la rubéole, la rougeole <span>n'est pas associée à un syndrome polymalformatif</span>. Le risque est obstétrical (FCS, <span class=\"nc-red nc-bold\">prématurité</span>) et néonatal (rougeole <span>congénitale</span>).</div></div>"},{"i":"db5d87e457e2","n":27,"o":"27-10","u":"Suivi et/ou pronostic","t":"Connaître les conséquences d'une rougeole au cours de la grossesse","q":"Que retenir concernant les conséquences d'une rougeole au cours de la grossesse ?","a":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Versant</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td>Rougeole maternelle</td><td><span><span class=\"nc-red nc-bold\">Pneumonie</span></span> par surinfection <span>bactérienne</span> (forme + grave durant la <span>grossesse</span>) ; <span><span class=\"nc-red nc-bold\">fausse couche</span></span>, <span><span class=\"nc-red nc-bold\">prématurité</span></span> (comme tout syndrome fébrile)</td></tr>\n          <tr><td>Rougeole <span>congénitale</span> ou périnatale</td><td>Risque maximal si <span>éruption</span> maternelle dans les <strong><span class=\"nc-pink nc-bold\">&lt; 10 jours précédant l'accouchement</span></strong> ; <span>éruption</span> néonatale dans les <span class=\"nc-blue_bg nc-bold\">10 premiers jours de vie</span> ; <span>mortalité</span> néonatale historiquement élevée ; risque accru de <span>panencéphalite subaiguë sclérosante (Van Bogaert)</span> précoce (&lt; 2 ans) et fulminante ⚠️</td></tr>\n          <tr><td>Rougeole post-natale</td><td><span>Éruption</span> entre J14 et J30 post-natal ; plus rare, généralement <span class=\"nc-green_bg\">moins grave</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pas de malformation <span>congénitale</span> :</strong> <span class=\"nc-green_bg\">absence d'effet </span><span><span class=\"nc-green_bg\">tératogène</span></span> — le <span>pronostic</span> est dominé par le risque maternel (pneumopathie) et néonatal (rougeole congénitale).</div></div>"},{"i":"fca7ca0b00d5","n":27,"o":"27-11","u":"Prise en charge","t":"Rougeole : Connaître les éléments de prévention fœtale","q":"Que retenir concernant rougeole : Connaître les éléments de prévention fœtale ?","a":"<div class=\"notion-course\"><ul>\n        <li><strong><span>Prévention primaire</span></strong> : amélioration de la <span>couverture vaccinale ROR</span> avant <span><span class=\"nc-green_bg\">grossesse</span></span> (vaccin vivant atténué, <span>CI pendant la <span class=\"nc-green_bg\">grossesse</span></span>) — couverture actuelle insuffisante pour éradiquer le virus</li>\n        <li><strong>CAT en cas de contage chez femme enceinte non immune</strong> : <span><span class=\"nc-pink_bg\">immunoglobulines polyvalentes IV</span></span>, efficaces dans les <strong><span>6 jours</span> suivant le contage</strong></li>\n        <li><strong>Si <span>éruption</span> maternelle &lt; 10 j <span class=\"nc-pink_bg nc-bold\">avant</span> accouchement</strong> : Ig polyvalentes IV chez le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> <strong><span class=\"nc-pink nc-bold\">dès la naissance</span></strong> (prévention de la rougeole <span>congénitale</span> et de ses complications)</li>\n        <li><strong>Inutile</strong> si <span>éruption</span> maternelle &gt; 10 j avant accouchement (collège de gynéco)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p></div>"},{"i":"390dd4386fcd","n":27,"o":"27-12","u":"Définition","t":"Connaître la définition de l'infection à Cytomégalovirus (CMV) materno-fœtale","q":"Que retenir concernant la définition de l'infection à Cytomégalovirus (CMV) materno-fœtale ?","a":"<div class=\"notion-course\"><ul><li>Le CMV peut être transmis au fœtus <span class=\"nc-pink nc-bold\">après</span> <span class=\"nc-red nc-bold\">primo-infection</span> mais aussi <span class=\"nc-pink nc-bold\">après</span> infection maternelle non primaire. La transmission augmente avec le terme ; les atteintes sévères sont surtout liées aux infections précoces. Une séropositivité ancienne ne garantit pas une protection absolue.</li><li>Atteintes possibles : <span class=\"nc-red_bg\">surdité</span> neurosensorielle, anomalies cérébrales et neurodéveloppementales, <span class=\"nc-red nc-bold\">retard de croissance</span> et atteintes viscérales. Une échographie normale ne permet pas d’exclure toute séquelle.</li><li><b>Évolution du référentiel :</b> la HAS recommande depuis 2025 un <span class=\"nc-blue_bg\">dépistage</span> systématiquement proposé au premier trimestre, avec modalités précisées en 2026. Sérologie précoce ; si négative, renouvellement toutes les quatre semaines avec dernier contrôle entre 13+0 et 14+0 SA.</li><li>Une IgM positive isolée ne date pas l’infection : interprétation experte des IgG/IgM, avidité et résultats antérieurs. Une <span class=\"nc-red nc-bold\">primo-infection</span> récente conduit rapidement à un avis spécialisé/CPDPN, une information sur les incertitudes et la discussion d’un <span class=\"nc-pink_bg\">traitement précoce par</span> valaciclovir et du diagnostic fœtal.</li><li>Prévention pour toutes : lavage des mains après contact avec sécrétions d’un jeune enfant, ne pas partager couverts/verres et éviter les baisers sur la bouche. Ce conseil reste utile quel que soit le statut sérologique.</li></ul></div>"},{"i":"30dc561ff162","n":27,"o":"27-13","u":"Physiopathologie","t":"Connaître les mécanismes de transmission materno-fœtale des virus les plus fréquemment impliqués","q":"Que retenir concernant les mécanismes de transmission materno-fœtale des virus les plus fréquemment impliqués ?","a":"<div class=\"notion-course\"><p>Le mécanisme de transmission <span>virale</span> dépend du virus et conditionne la période à risque + la stratégie préventive.</p>\n      <table>\n        <thead><tr><th>Virus</th><th>Voie principale</th><th>Période à risque</th></tr></thead>\n        <tbody>\n          <tr><td><span>CMV</span></td><td>Hématogène <span class=\"nc-orange_bg\">transplacentaire</span></td><td>Risque de séquelles surtout lié aux infections précoces ; ne pas assimiler une infection plus tardive à une absence absolue de risque.</td></tr>\n          <tr><td>Rubéole</td><td>Hématogène transplacentaire</td><td>&lt; 18-20 SA (<span>tératogène</span>)</td></tr>\n          <tr><td>Parvovirus B19</td><td>Hématogène <span class=\"nc-orange_bg\">transplacentaire</span></td><td>T1-T2 (<span class=\"nc-red_bg\">anémie</span> fœtale, anasarque)</td></tr>\n          <tr><td><span>VZV</span></td><td>Hématogène + per-partum</td><td>&lt; 20 SA (embryofœtopathie) ; 5 j avant à 2 j après accouchement (<span>varicelle néonatale grave</span>)</td></tr>\n          <tr><td><span>HSV</span></td><td>Per-partum +++</td><td><span class=\"nc-red nc-bold\">Primo-infection</span> T3 (transmission <span>50 %</span>)</td></tr>\n          <tr><td><span>VHB</span></td><td>Per-partum (<span>90 %</span>) &gt; <span class=\"nc-brown_bg\">transplacentaire</span></td><td>Accouchement</td></tr>\n          <tr><td><span>VIH</span></td><td><span class=\"nc-brown_bg\">Per-partum</span> (<span>20 %</span>), <span class=\"nc-brown_bg\">transplacentaire</span> (<span>6 %</span>), <span><span class=\"nc-brown_bg\">allaitement</span></span> (<span>15 %</span>)</td><td>Accouchement et <span><span class=\"nc-brown_bg\">allaitement</span></span></td></tr>\n          <tr><td><span>Grippe</span></td><td>Pas de transmission fœtale directe (pas <span>tératogène</span>)</td><td>Tous trimestres (risque maternel + FCS, prématurité)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 168 — Herpesvirus · 169 — <span>VIH</span></em></p></div>"},{"i":"0683c0cca743","n":27,"o":"27-14","u":"Prise en charge","t":"Herpes simplex virus (HSV) : connaître les éléments de prévention fœtale","q":"Que retenir concernant herpes simplex virus (HSV) : connaître les éléments de prévention fœtale ?","a":"<div class=\"notion-course\"><ul><li>Distinguer un premier épisode connu (<span class=\"nc-red nc-bold\">primo-infection</span>, infection initiale non primaire ou récurrence méconnue) d’une récurrence documentée. PCR de la lésion et sérologie selon situation ; une lésion atypique nécessite confirmation.</li><li>Premier épisode pendant la <span class=\"nc-green_bg\">grossesse</span> : traitement antiviral, puis prophylaxie à partir de 36 SA selon RPC. Une infection initiale proche de l’accouchement expose au risque néonatal le plus élevé et conduit à discuter/recommander la <span class=\"nc-pink nc-bold\">césarienne</span> selon le délai et les lésions.</li><li>Récurrence : traitement si symptômes invalidants, particulièrement précoce, et prophylaxie en fin de grossesse si épisode pendant la grossesse. Pas de <span class=\"nc-blue_bg\">dépistage</span> virologique systématique en travail en l’absence de lésion/prodrome.</li><li>Récurrence en travail : décision selon membranes, terme et terrain ; une <span class=\"nc-pink nc-bold\">césarienne</span> est davantage considérée si membranes intactes, prématurité ou VIH, une voie vaginale davantage si rupture prolongée à terme sans VIH. Ce n’est pas une règle binaire universelle.</li><li>Prévenir l’équipe pédiatrique et limiter les gestes traumatiques fœtaux en cas de lésions actives. Les deux arbres LiSA/CNGOF détaillent les branches ; les notes distinguent le schéma de ses précautions d’interprétation.</li></ul></div>"},{"i":"0c44a77281e8","n":27,"o":"27-15","u":"Définition","t":"Connaître la définition de l'infection à VHB materno-fœtale","q":"Que retenir concernant la définition de l'infection à VHB materno-fœtale ?","a":"<div class=\"notion-course\"><p>L'<span>infection à VHB materno-fœtale</span> est l'infection par le virus de l'<span>hépatite</span> B contractée par le fœtus ou le nouveau-né à partir d'une mère porteuse (~ <span>1 %</span> des femmes enceintes en France).</p>\n      <table>\n        <thead><tr><th>Mode</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Per-partum (<span>90 %</span>)</td><td>Contact avec le sang maternel — indépendant de la voie d'accouchement (basse ou <span class=\"nc-pink nc-bold\">césarienne</span>)</td></tr>\n          <tr><td>Transplacentaire</td><td>Possible chez les femmes à <strong>haut taux de réplication <span>virale</span></strong> (AgHBe+ avec ADN <span>VHB</span> détectable)</td></tr>\n          <tr><td>Post-natale</td><td><span>Allaitement</span> (faible, autorisé après sérovaccination)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span><span class=\"nc-green_bg\">VHB</span></span><span class=\"nc-green_bg\"> n'est pas </span><span><span class=\"nc-green_bg\">tératogène</span></span></strong> : <span class=\"nc-green_bg\">pas d'embryofœtopathie</span>, pas d'<span><span class=\"nc-blue_bg\">ictère</span></span> néonatal (délai d'incubation). Mais en cas de transmission, <span><span class=\"nc-red_bg nc-bold\">80 à 90 %</span> <span class=\"nc-red_bg\">des nouveau-nés développent une hépatite B chronique</span></span> (<span>vs</span><span> 5-10 %</span> chez l'adulte) → <span>cirrhose</span>, CHC.</div>\n      <p>Risque de transmission élevé en l'absence de mesures préventives, majoré par AgHBe+ avec ADN <span>VHB</span> détectable (<span>90 %</span>) ; AC anti-HBe+ → quasi nul.</p></div>"},{"i":"114359d5031c","n":27,"o":"27-16","u":"Prise en charge","t":"Virus de l'hépatite B (VHB) : connaître les éléments de prévention fœtale par la vaccination","q":"Que retenir concernant virus de l'hépatite B (VHB) : connaître les éléments de prévention fœtale par la vaccination ?","a":"<div class=\"notion-course\"><p>La prévention de l'IMF à <span>VHB</span> repose sur le <strong><span><span class=\"nc-blue_bg\">dépistage</span></span> <span class=\"nc-red nc-bold\">obligatoire</span></strong> + la <strong>sérovaccination du nouveau-né</strong>.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">Dépistage</span></span></td><td><span>Recherche AgHBs</span> obligatoire dès la déclaration de <span><span class=\"nc-green_bg\">grossesse</span></span> (au 1ᵉʳ trimestre)</td></tr>\n          <tr><td>Mère AgHBs+</td><td>Traitement <span>antiviral</span> envisagé pour réduire la charge <span>virale</span> (<span><span class=\"nc-pink nc-bold\">lamivudine</span></span> ou <span><span class=\"nc-pink nc-bold\">ténofovir</span></span>) ; pas de <span class=\"nc-pink nc-bold\">césarienne</span> prophylactique ❌</td></tr>\n          <tr><td><span class=\"nc-blue_bg nc-bold\">Nouveau-né</span></td><td><strong>Sérovaccination <span class=\"nc-pink nc-bold\">dès la naissance</span>, avant <span>H12</span></strong> : Ig anti-HBs IM + 1ʳᵉ dose du vaccin <span>VHB</span> ; schéma complet M0-<span>M1</span>-M6</td></tr>\n          <tr><td><span>Surveillance</span></td><td>À partir de <span><span class=\"nc-pink nc-bold\">9 mois</span></span> (et <span>≥ 1 mois</span> après dernière dose) : AgHBs + titrage AC anti-HBs pour vérifier efficacité</td></tr>\n          <tr><td><span>Allaitement</span></td><td><strong>Autorisé</strong> après sérovaccination (enfant protégé)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Vaccination universelle :</strong> tous les nouveau-nés sont vaccinés contre le <span>VHB</span> selon le calendrier vaccinal — la sérovaccination s'ajoute aux mères AgHBs+ pour court-circuiter la fenêtre per-partum.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p></div>"},{"i":"fd27d830de93","n":27,"o":"27-17","u":"Prise en charge","t":"Virus de l'immunodéficience humaine (VIH) : connaître les éléments de prévention par le dépistage","q":"Que retenir concernant virus de l'immunodéficience humaine (VIH) : connaître les éléments de prévention par le dépistage ?","a":"<div class=\"notion-course\"><ul><li>Proposer le <span class=\"nc-blue_bg\">dépistage</span> du VIH en début de <span class=\"nc-green_bg\">grossesse</span>, puis le renouveler en cas d’exposition ou de risque persistant. Un résultat positif conduit rapidement à une prise en charge infectiologique et obstétricale coordonnée.</li><li>Traitement antirétroviral efficace pour toute femme vivant avec le VIH, sans attendre un terme tardif. Choix des molécules, interactions et surveillance selon recommandations actualisées ; ne pas reprendre une liste ancienne de contre-indications sans <span class=\"nc-brown_bg\">vérifier le</span> traitement concerné.</li><li>L’objectif est une charge virale <span class=\"nc-green_bg nc-bold\">indétectable</span> durable. La voie d’accouchement et les mesures périnatales dépendent notamment du contrôle virologique ; une <span class=\"nc-pink nc-bold\">césarienne</span> n’est pas automatique.</li><li>Prophylaxie néonatale et calendrier diagnostique adaptés au niveau de risque, avec équipe pédiatrique.</li><li><b>HAS 2024 :</b> l’allaitement peut être envisagé chez une femme qui le souhaite sous conditions strictes de contrôle virologique, observance et suivi spécialisé maternel et infantile. Le risque résiduel, les alternatives, la prophylaxie infantile et les critères d’interruption doivent être explicités ; ne pas présenter cette possibilité comme applicable sans surveillance.</li></ul></div>"},{"i":"f754b20262d8","n":27,"o":"27-18","u":"Prise en charge","t":"Virus varicelle zona (VZV) : connaître les éléments de prévention par la vaccination","q":"Que retenir concernant virus varicelle zona (VZV) : connaître les éléments de prévention par la vaccination ?","a":"<div class=\"notion-course\"><p>La varicelle pendant la <span><span class=\"nc-green_bg\">grossesse</span></span> comporte un <strong>risque maternel</strong> (<span><span class=\"nc-red nc-bold\">pneumonie</span></span> varicelleuse — surmortalité), un <strong>risque embryofœtal</strong> et un <strong>risque néonatal grave</strong>.</p>\n      <table>\n        <thead><tr><th>Période</th><th>Risque</th></tr></thead>\n        <tbody>\n          <tr><td>&lt; 20 SA</td><td><span>Embryofœtopathie varicelleuse</span> (<span>1-2 %</span>) : hypoplasie membres, atteinte cutanée zostérienne, <span class=\"nc-orange_bg\">microphtalmie</span>, <span class=\"nc-red_bg\">microcéphalie</span></td></tr>\n          <tr><td><span>Éruption</span> maternelle 5 j avant à 2 j après accouchement</td><td><span>Varicelle néonatale grave</span> — <span>mortalité</span> ~<span>30 %</span> sans traitement</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong><span>Prévention primaire</span></strong> : <span>vaccin VZV vivant atténué</span> <strong>avant <span><span class=\"nc-green_bg\">grossesse</span></span></strong> chez femmes non immunes ; <span>CI pendant la <span class=\"nc-green_bg\">grossesse</span></span> ⚠️</li>\n        <li><strong>Contage chez femme enceinte non immune</strong> : <span>Ig anti-VZV IV</span> dans les <strong><span>96 h</span></strong></li>\n        <li><strong>Varicelle confirmée chez la mère</strong> : <span>aciclovir IV</span></li>\n      </ul>\n      <p>Contraception <span>≥ 1 mois</span> après vaccin <span>VZV</span> (vaccin vivant).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p></div>"},{"i":"03a840c24a05","n":27,"o":"27-19","u":"Physiopathologie","t":"Connaître les mécanismes de transmission materno-fœtale de la listériose","q":"Que retenir concernant les mécanismes de transmission materno-fœtale de la listériose ?","a":"<div class=\"notion-course\"><p><span>Listeria monocytogenes</span> — bactérie Gram+ saprophyte, <span>résiste au <span class=\"nc-red nc-bold\">froid</span></span> mais <span>sensible à la <span class=\"nc-green nc-bold\">chaleur</span></span>. Rare (~ 1/<span <span=\"\">&gt;1000</span> grossesses) mais sévère.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Contamination maternelle</td><td>Alimentation (fromages au lait cru, charcuterie, produits réfrigérés contaminés)</td></tr>\n          <tr><td><span>Diffusion</span></td><td><strong>Bactériémie maternelle</strong> → <strong>transmission <span class=\"nc-orange_bg\">transplacentaire</span> hématogène</strong></td></tr>\n          <tr><td>Atteinte placentaire</td><td>Colonisation placentaire → <strong><span class=\"nc-red\">chorioamniotite</span></strong> → bactériémie fœtale</td></tr>\n          <tr><td>Manifestation maternelle</td><td>2 phases : <span><span class=\"nc-green_bg\">syndrome pseudo-grippal</span></span> (assez banal) puis <span>chorioamniotite</span> (<strong><span class=\"nc-blue nc-bold\">travail prématuré fébrile</span> + <span class=\"nc-blue nc-bold\">perte liquidienne vaginale épaisse</span>/<span class=\"nc-blue nc-bold\">teintée</span></strong>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Conséquences néonatales :</strong> <span class=\"nc-red_bg\">accouchement prématuré</span>, <span class=\"nc-red_bg\">infection néonatale</span> (<span>mortalité</span> <span>50-75 %</span>) — <span>cyanose</span>, apnée, <span>détresse</span> respiratoire, troubles de la conscience, <span><span class=\"nc-red nc-bold\">méningite purulente</span> (95 %)</span>.</div></div>"},{"i":"85757b801d57","n":27,"o":"27-20","u":"Prise en charge","t":"Listériose materno-fœtale (MF) : connaître les éléments de prévention","q":"Que retenir concernant listériose materno-fœtale (MF) : connaître les éléments de prévention ?","a":"<div class=\"notion-course\"><p>La prévention de la listériose chez la femme enceinte repose sur des <strong>règles d'hygiène alimentaire strictes</strong> (<span>Listeria</span> résiste au <span class=\"nc-red nc-bold\">froid</span> mais est tuée par la <span class=\"nc-green nc-bold\">chaleur</span> <span>≥ 72 °C</span>).</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td>Aliments <span>à éviter</span></td><td><strong>Fromages au lait cru</strong> à pâte molle (camembert, brie, roquefort), <span class=\"nc-red nc-bold\">fromages vendus râpés</span>, croûtes ; charcuterie cuite consommée en l'état (pâté, rillettes, jambon cuit, produits en gelée) ; <span class=\"nc-red_bg\">poissons fumés</span>, <span class=\"nc-red_bg\">coquillages crus</span>, <span class=\"nc-red_bg\">surimi</span>, <span class=\"nc-red_bg\">tarama</span> ; graines germées crues (soja, luzerne)</td></tr>\n          <tr><td>Précautions cuisson</td><td>Viande consommée <span>bien cuite (≥ 72 °C)</span> ou congelée (-<span <span=\"\">&gt;18</span> °C) ; réchauffer soigneusement les restes alimentaires</td></tr>\n          <tr><td>Hygiène générale</td><td>Lavage des mains avant/après manipulation d'aliments à risque et jardinage ; <span class=\"nc-green_bg\">nettoyage régulier du réfrigérateur</span> ; séparation aliments crus/cuits</td></tr>\n          <tr><td>Légumes/fruits</td><td>Crudités, fruits, légumes et herbes aromatiques soigneusement lavés</td></tr>\n        </tbody>\n      </table>\n      <p><span>Activité physique adaptée</span> :<span> <span class=\"nc-pink nc-bold\">30 min</span></span>, 3 à 5 ×/sem.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span> · 173 — Zoonose</em></p></div>"},{"i":"1ffec6c5008e","n":27,"o":"27-21","u":"Examens complémentaires","t":"Connaître les examens complémentaires à prescrire en cas de suspicion de listériose MF","q":"Que retenir concernant les examens complémentaires à prescrire en cas de suspicion de listériose MF ?","a":"<div class=\"notion-course\"><p>Devant tout <strong>syndrome fébrile sans foyer évident</strong> chez la femme enceinte, suspecter une listériose et prescrire :</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span><span class=\"nc-blue nc-bold\">Hémocultures</span></span></strong> (aéro/anaérobies)</td><td>En précisant explicitement <strong>la recherche de <span>Listeria</span> monocytogenes</strong> au laboratoire</td></tr>\n          <tr><td><span>ECBU</span> + bilan <span>inflammatoire</span></td><td><span>NFS</span>, <span>CRP</span> — recherche d'autres foyers (<span>pyélonéphrite</span>, chorioamniotite)</td></tr>\n          <tr><td>À l'accouchement</td><td><span>Hémocultures</span> en cas de reprise fébrile ; examen bactériologique <strong>du placenta + lochies</strong> (presque toujours positif si recueil correct) ; <span>anatomopathologie</span> placentaire (<strong><span class=\"nc-orange nc-bold\">granulomes </span><span><span class=\"nc-orange nc-bold\">infectieux</span></span></strong>)</td></tr>\n          <tr><td>Nouveau-né</td><td><strong><span><span class=\"nc-blue_bg\">Hémocultures</span></span>, <span><span class=\"nc-blue_bg\">LCS</span></span></strong> (germe facilement isolé en culture), prélèvement de liquide gastrique, <span class=\"nc-brown_bg\">méconium</span>, <span class=\"nc-brown_bg\">peau</span></td></tr>\n          <tr><td>Enquête environnementale</td><td>À partir des aliments suspects si suspicion d'épidémie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span>Antibiothérapie</span> probabiliste dès la suspicion</strong> (avant résultat des <span><span class=\"nc-blue_bg\">hémocultures</span></span>) chez la femme enceinte fébrile avec <span>signes de gravité</span> : <span><span class=\"nc-pink_bg\">amoxicilline</span> IV</span> (ou <span>érythromycine</span> si <span>allergie</span>). Si confirmation : <strong><span><span class=\"nc-pink_bg\">amoxicilline</span></span> + <span class=\"nc-pink_bg nc-bold\">aminoside</span> 5 j</strong> puis <span><span class=\"nc-pink_bg\">amoxicilline</span></span> <span>≥ 4</span> sem ou <span class=\"nc-pink_bg nc-bold\">jusqu'à l'accouchement</span>.</div></div>"},{"i":"515cbf6dc311","n":27,"o":"27-22","u":"Physiopathologie","t":"Connaître les mécanismes de transmission materno-fœtale du streptocoque B","q":"Que retenir concernant les mécanismes de transmission materno-fœtale du streptocoque B ?","a":"<div class=\"notion-course\"><p><span><span class=\"nc-purple_bg\">Streptococcus agalactiae</span></span> (SGB) — <strong><span class=\"nc-red nc-bold\">bactérie la plus fréquemment en cause dans les infections graves du nouveau-né</span></strong>.</p>\n      <table>\n        <thead><tr><th>Indicateur</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span>Prévalence</span> portage en France</td><td><span>10-15 %</span> (<span>10-35 %</span> digestif/vaginal selon Pilly)</td></tr>\n          <tr><td>Colonisation néonatale</td><td><span>50-70 %</span> (Pilly)</td></tr>\n          <tr><td>Risque de transmission néonatale (gynéco)</td><td><span>40-50 %</span></td></tr>\n          <tr><td>Risque d'<span class=\"nc-red_bg\">infection néonatale</span> (Pilly)</td><td><span>1 %</span> des nouveau-nés colonisés</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Colonisation cervico-vaginale maternelle</strong> asymptomatique</li>\n        <li><strong>Transmission per-partum ascendante</strong> lors de l'accouchement ou de la <span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> prolongée des membranes</span> (RPM)</li>\n        <li>Conséquences néonatales : <span>sepsis néonatal précoce</span> (pneumopathie, <span>méningite</span>), <span><span class=\"nc-red_bg\">chorioamniotites</span></span>, IMF, <span class=\"nc-red_bg\">endométrites du post-partum</span></li>\n      </ul></div>"},{"i":"bce98b05a0ca","n":27,"o":"27-23","u":"Prise en charge","t":"Connaître la prise en charge médicamenteuse de la vaginose bactérienne","q":"Que retenir concernant la prise en charge médicamenteuse de la vaginose bactérienne ?","a":"<div class=\"notion-course\"><p>La <span>vaginose bactérienne</span> est un déséquilibre de la flore vaginale (lactobacilles → <span class=\"nc-red_bg\">anaérobies</span> : <em><span class=\"nc-purple nc-bold\">Gardnerella vaginalis</span></em>, <em>Mobiluncus</em>, Bacteroides, mycoplasmes). <span>Prévalence</span> : <span>7 %</span> au 1ᵉʳ trimestre en France.</p>\n      <table>\n        <thead><tr><th>Traitement</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-pink nc-bold\">Métronidazole</span></span></td><td><span>7 jours</span>, voie orale ou ovule</td></tr>\n          <tr><td><span><span class=\"nc-pink nc-bold\">Clindamycine</span></span></td><td><span>7 jours</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Indication du <span><span class=\"nc-blue_bg\">dépistage</span></span></strong> : pas de bénéfice systématique en population générale ; utile si <strong><span class=\"nc-purple_bg nc-bold\">ATCD</span> d'accouchement prématuré</strong> dans un contexte de <span class=\"nc-orange_bg\">chorioamniotite</span> <span>bactérienne</span> (<span class=\"nc-blue_bg\">dépistage</span> par prélèvement vaginal au 1ᵉʳ trimestre)</li>\n        <li><strong>Diagnostic</strong> : <span><span class=\"nc-yellow_bg\">critères cliniques</span></span><span class=\"nc-yellow_bg\"> d'</span><span><span class=\"nc-yellow_bg nc-bold\">Amsel</span></span> (<span>≥ 3</span>/4 : <span>pH</span> &gt; 4,5, <span class=\"nc-blue_bg\">leucorrhées</span> <span class=\"nc-blue_bg\">grisâtres</span> <span class=\"nc-blue_bg\">homogènes</span>, <span class=\"nc-yellow_bg nc-bold\">clue</span> <span class=\"nc-yellow_bg nc-bold\">cells</span> &gt;<span> 20 %</span>, <span class=\"nc-yellow_bg\">sniff test</span> positif) et/ou <span>score de <span class=\"nc-yellow_bg nc-bold\">Nugent</span></span> <span>≥ 7</span> (coloration de Gram)</li>\n        <li><strong><span>Surveillance</span></strong> : contrôle trimestriel (récidive fréquente) ; renouveler le traitement si nécessaire</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST</em></p></div>"},{"i":"3c85c9147ec3","n":27,"o":"27-24","u":"Suivi et/ou pronostic","t":"Connaître le risque de la vaginose bactérienne au cours de la grossesse","q":"Que retenir concernant le risque de la vaginose bactérienne au cours de la grossesse ?","a":"<div class=\"notion-course\"><p>La <span>vaginose</span> <span>bactérienne</span> expose à des risques infectieux et obstétricaux. Le lien avec l'accouchement prématuré reste modeste mais réel.</p>\n      <ul>\n        <li><strong>Complications obstétricales</strong> : <span><span class=\"nc-orange nc-bold\">menace d'accouchement prématuré</span> (<span class=\"nc-orange_bg\">MAP</span>)</span> (odds ratio 1,5 à 2)</li>\n        <li><strong><span class=\"nc-red\">Infections génitales</span> hautes (IGH)</strong></li>\n        <li><strong><span class=\"nc-purple_bg\">Infections postopératoires</span></strong><span class=\"nc-purple_bg\"> en cas de geste chirurgical par voie vaginale</span></li>\n        <li><strong>Chorioamniotite</strong> <span>bactérienne</span></li>\n        <li><strong><span>Rupture</span> prématurée des membranes (RPM)</strong></li>\n        <li><strong>Endométrite</strong> du post-partum</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Lien faible mais significatif</strong> avec la <span class=\"nc-red nc-bold\">prématurité</span> — d'où l'indication de <span>dépistage</span> ciblé en cas d'<span class=\"nc-purple_bg nc-bold\">ATCD</span> d'<span class=\"nc-red\">accouchement prématuré</span> sur <span class=\"nc-red\">chorioamniotite</span> (et non systématique).</div></div>"},{"i":"a9b14f55010e","n":27,"o":"27-25","u":"Prise en charge","t":"Grippe et grossesse","q":"Que retenir concernant grippe et grossesse ?","a":"<div class=\"notion-course\"><p>La femme enceinte est une <strong>population à risque de <span><span class=\"nc-red nc-bold\">grippe</span></span> sévère</strong> (surtout T2 et T3) — la <span class=\"nc-red nc-bold\">grippe</span> entraîne plus d'hospitalisations graves chez la femme enceinte que la listériose ou la toxoplasmose.</p>\n      <table>\n        <thead><tr><th>Versant</th><th>Risques</th></tr></thead>\n        <tbody>\n          <tr><td>Maternel</td><td><span>Hospitalisation</span> accrue (T2-T3), <span>complications pulmonaires</span> (surinfection, <span>OAP</span>), <span>complications cardiovasculaires</span>, hospitalisation en réanimation</td></tr>\n          <tr><td>Fœtal</td><td><strong>Pas <span>tératogène</span> ❌</strong> · <span class=\"nc-orange_bg\">avortement</span>, <span class=\"nc-orange_bg\">prématurité</span> (lié à la <span>fièvre</span> et aux complications maternelles)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Prévention primaire</span> :</strong></p>\n      <ul>\n        <li><span>Vaccination antigrippale</span> = <strong>meilleur moyen de protection</strong>, <span class=\"nc-yellow_bg\">possible à tous les stades de la </span><span><span class=\"nc-yellow_bg\">grossesse</span></span> (<strong>vaccin inactivé</strong>)</li>\n        <li>Passage des AC maternels protège le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> et le nourrisson de moins de <span>6 mois</span> (non vaccinables)</li>\n        <li><span class=\"nc-green_bg\">Mesures d'hygiène</span>, limitation des contacts</li>\n      </ul>\n      <p><strong><span>Prévention secondaire</span> / traitement post-exposition :</strong></p>\n      <ul>\n        <li>Contage &lt;<span> 48h</span> : <span><span class=\"nc-pink_bg\">oseltamivir</span> prophylactique</span> 1×/j pendant 10 j (sauf si vaccinée)</li>\n        <li>Suspicion <span>grippe</span> : <span><span class=\"nc-pink_bg\">oseltamivir</span> curatif</span> 2×/j pendant 5 j, débuté &lt;<span> 48 h</span> après les 1ᵉʳˢ signes</li>\n        <li><span>Hospitalisation</span> si <span>signes de gravité</span> (atteinte fonctions supérieures, FR &gt; 30, PAS &lt; 90, FC &gt; 120)</li>\n        <li><span>Allaitement</span> maternel possible ✅</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire</em></p></div>"},{"i":"bf488b59f641","n":27,"o":"27-26","u":"Physiopathologie","t":"Connaître la physiopathologie de l'allo-immunisation antiérythrocytaire","q":"Que retenir concernant la physiopathologie de l'allo-immunisation antiérythrocytaire ?","a":"<div class=\"notion-course\"><p>L'allo-immunisation antiérythrocytaire correspond à la présence chez une femme enceinte d'un <span>AC irrégulier</span> (non-A ou non-B) dirigé contre un <span>antigène</span> de groupe sanguin érythrocytaire fœtal.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Sensibilisation maternelle</td><td>Passage de GR fœtales incompatibles dans la circulation maternelle (mère <span>RhD</span>-, fœtus RhD+) lors d'événements à risque (accouchement, FCS, IVG, GEU, traumatisme abdo, <span>amniocentèse</span>, version par manœuvre externe, <span>chirurgie</span> utérine, métrorragies, ou de façon spontanée silencieuse ⚠️) ; ou transfusion non isogroupe (rare)</td></tr>\n          <tr><td>Production d'IgG anti-D</td><td>AC <strong>réguliers IgM</strong> ne passent pas la barrière placentaire ❌ ; AC <strong>irréguliers IgG</strong> passent ✅</td></tr>\n          <tr><td>Passage <span class=\"nc-orange_bg\">transplacentaire</span></td><td>IgG anti-D <span class=\"nc-blue_bg nc-bold\">maternelles</span> traversent le placenta vers la circulation fœtale</td></tr>\n          <tr><td>Hémolyse fœtale</td><td><strong><span class=\"nc-red_bg\">Anémie</span> hémolytique fœtale</strong> (1ʳᵉ cause d'<span class=\"nc-red_bg\">anémie</span> fœtale) → <span>anasarque</span> (épanchements séreux) → <span>MFIU</span></td></tr>\n          <tr><td>Atteinte néonatale</td><td>AC maternels persistent plusieurs semaines : <span><span class=\"nc-red_bg\">anémie</span> hémolytique néonatale</span> + <span><span class=\"nc-blue_bg\">ictère</span> à bilirubine libre</span> (risque <strong><span><span class=\"nc-blue_bg\">ictère</span></span> nucléaire</strong> = séquelles neuro)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>AC les + fréquents et + graves :</strong> anti-D (Rh1), anti-c (Rh4), anti-Kell. Mère non concernée (ses propres GR n'expriment pas l'Ag).</div></div>"},{"i":"286987dcb018","n":27,"o":"27-27","u":"Diagnostic positif","t":"Connaître le diagnostic de l'allo-immunisation antiérythrocytaire","q":"Que retenir concernant le diagnostic de l'allo-immunisation antiérythrocytaire ?","a":"<div class=\"notion-course\"><p>Le diagnostic combine un <strong>versant maternel</strong> (<span><span class=\"nc-blue_bg\">dépistage</span></span> sérologique de l'allo-immunisation) et un <strong>versant fœtal</strong> (évaluation du risque d'<span class=\"nc-red_bg\">anémie</span>).</p>\n      <table>\n        <thead><tr><th>Versant</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Maternel — systématique au 1ᵉʳ trimestre</td><td><strong><span>Groupe rhésus phénotype</span></strong> (2 déterminations) + <strong><span>RAI</span></strong> (Recherche d'Agglutinines Irrégulières)</td></tr>\n          <tr><td>Recontrôle RAI</td><td>Indications : femmes <span>RhD</span>- ou RhD+ précédemment transfusées · à <strong><span>M6</span>, M8, M9</strong> · inutile si Ig anti-D déjà injectées ou génotypage fœtal RhD-</td></tr>\n          <tr><td>Si RAI positive</td><td>1️⃣ <strong>Identifier l'AC</strong> (anti-D, anti-Kell, anti-c…) · 2️⃣ <strong>Titrage</strong> de l'AC (<span>Coombs</span> indirect) · 3️⃣ Dosage pondéral des AC anti-Rh (plus précis)</td></tr>\n          <tr><td>Phénotypage père</td><td>Groupe rhésus du conjoint connu chez femmes <span>RhD</span>- ; phénotypage père pour autres Ag (Kell…)</td></tr>\n          <tr><td>Fœtal — génotypage <span>RhD</span></td><td><span>PCR sur ADN fœtal circulant</span> dans le sang maternel ; <strong>dès 11 SA</strong> ; uniquement si mère <span>RhD</span>-</td></tr>\n          <tr><td>Évaluation <span class=\"nc-red_bg\">anémie</span> fœtale</td><td><span>Doppler artère cérébrale moyenne (PSV-ACM)</span> : <span>Vmax &gt; 1,5 MoM</span> = <span class=\"nc-red_bg\">anémie</span> significative ; <span>Doppler ombilical</span> ; <span>ECG-tocographie</span> : <span>tachycardie</span> ou <span>rythme sinusoïdal</span> = <span class=\"nc-red_bg\">anémie</span> très sévère</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Seuils à risque fœtal important :</strong> titrage AC ≥ <span>16</span> (1/16) ou dosage pondéral ≥ <span>1 µg/mL</span>. <strong><span class=\"nc-red\">Anasarque</span> échographique</strong> + tracé sinusoïdal = <span class=\"nc-red_bg\">anémie</span> sévère = <span>urgence</span> (Hb &lt;<span> 5 g/dL</span> le + souvent).</div></div>"},{"i":"b73e49ba01a6","n":27,"o":"27-28","u":"Suivi et/ou pronostic","t":"Connaître la prévention de l'allo-immunisation antiérythrocytaire durant la grossesse","q":"Que retenir concernant la prévention de l'allo-immunisation antiérythrocytaire durant la grossesse ?","a":"<div class=\"notion-course\"><ul><li>La prophylaxie anti-D concerne une femme RhD négatif non déjà immunisée, exposée à des hématies fœtales RhD positives. Le génotypage fœtal RhD permet d’adapter la prévention lorsqu’il est disponible et interprétable.</li><li>Prophylaxie systématique vers 28 SA si fœtus RhD positif ou statut inconnu : immunoglobulines anti-D selon protocole, après vérification du groupe et de la RAI. Une RAI positive doit être interprétée en tenant compte d’une injection récente.</li><li>Prévention ciblée après événement à risque de passage fœto-maternel, selon terme, situation et statut fœtal ; injection idéalement dans les 72 heures et dose adaptée si hémorragie fœto-maternelle importante.</li><li><b>CNGOF 2024 :</b> avant 12 SA, il est recommandé de ne pas administrer systématiquement d’anti-D pour IVG, <span class=\"nc-red nc-bold\">fausse couche</span> ou <span class=\"nc-green_bg\">grossesse</span> arrêtée intra-utérine, ni pour métrorragies d’une <span class=\"nc-green_bg\">grossesse</span> intra-utérine évolutive. Le niveau de preuve est très faible.</li><li>Pour la GEU avant 12 SA, aucune recommandation n’a pu être émise : avis/protocole spécialisé. Ne pas étendre cette absence de prophylaxie du premier trimestre aux gestes ou événements ultérieurs.</li><li>La prophylaxie prévient l’immunisation ; elle ne traite pas une allo-immunisation déjà constituée, qui nécessite une surveillance fœtale spécialisée.</li></ul></div>"},{"i":"f70e7bef3ddb","n":27,"o":"27-29","u":"Suivi et/ou pronostic","t":"Connaître la prévention de l'allo-immunisation antiérythrocytaire dans le post-partum","q":"Que retenir concernant la prévention de l'allo-immunisation antiérythrocytaire dans le post-partum ?","a":"<div class=\"notion-course\"><ul><li>Après la <span class=\"nc-pink nc-bold\">naissance</span>, la prophylaxie concerne une mère RhD négatif non immunisée et un enfant RhD positif (ou statut non établi selon protocole). Vérifier groupe et contexte des injections antérieures.</li><li>Administrer les immunoglobulines anti-D idéalement dans les 72 heures, selon RCP/protocole. Si retard, solliciter rapidement l’équipe : ne pas conclure soi-même que toute prévention est devenue inutile.</li><li>Quantifier l’hémorragie fœto-maternelle par test approprié, notamment Kleihauer, pour adapter la dose. La prophylaxie systématique de <span class=\"nc-green_bg\">grossesse</span> ne dispense pas de l’évaluation postnatale.</li><li>Une allo-immunisation déjà constituée relève de la surveillance et du traitement spécialisés ; l’anti-D prophylactique ne traite pas l’<span class=\"nc-red_bg\">anémie</span> fœtale ou néonatale.</li><li>Les règles du post-partum ne doivent pas être transposées aux événements du premier trimestre : voir les distinctions CNGOF 2024 de l’objectif 27-28.</li></ul></div>"},{"i":"c68bb29aa5f6","n":27,"o":"27-30","u":"Prise en charge","t":"Médicaments et grossesse : connaître la conduite à tenir en cas d'exposition","q":"Que retenir concernant médicaments et grossesse : connaître la conduite à tenir en cas d'exposition ?","a":"<div class=\"notion-course\"><p>L'évaluation d'une exposition médicamenteuse repose sur la <strong>chronologie</strong>, le <strong>terme d'exposition</strong> et le <strong>profil <span>tératogène</span></strong> du médicament. Ressource clé : <span>CRAT</span> (Centre de Référence sur les Agents Tératogènes — lecrat.fr) et centres régionaux de pharmacovigilance.</p>\n      <table>\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Patiente prenant un traitement, ne se sachant pas enceinte</td><td>Consigner durée, quantité, indication. Évaluer le risque selon le terme (organogenèse T1) + bénéfice maternel à l'arrêt. Discussion en <strong>comité de diagnostic prénatal (CPDPN)</strong> après information du couple</td></tr>\n          <tr><td>Patiente sous traitement désirant une <span>grossesse</span></td><td>Consultation préconceptionnelle pour adapter au traitement le mieux connu pour une <span>grossesse</span> — assistance des CRPV</td></tr>\n          <tr><td>Malformation découverte à la naissance</td><td><span>Prévalence</span> des malformations en population générale ~ <span>2-3 %</span>, dont &lt;<span> 5 %</span> d'origine médicamenteuse. Reprendre rétrospectivement la chronologie, déclarer au CRPV/ANSM</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Principes fondamentaux :</strong> <span>ne jamais</span> inquiéter inutilement une patiente après découverte d'une prise médicamenteuse en début de <span>grossesse</span> ; un traitement chronique ne doit pas être interrompu brutalement ; éviter l'automédication ; en cas de doute, diagnostic anténatal possible pour la majorité des médicaments tératogènes.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription</em></p></div>"},{"i":"2890f051dd0b","n":27,"o":"27-31","u":"Diagnostic positif","t":"Médicaments et grossesse : connaître les principaux médicaments à risque","q":"Que retenir concernant médicaments et grossesse : connaître les principaux médicaments à risque ?","a":"<div class=\"notion-course\"><p>Les médicaments à risque sont classés par <strong>profil de risque</strong> (<span>tératogène</span>, fœtotoxique, néonatal). En population générale, le risque spontané de malformation majeure est de <span>2-3 %</span>.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Molécules</th><th>Risque tératogène (T1)</th></tr></thead>\n        <tbody>\n          <tr><td>Anticancéreux</td><td><span>Méthotrexate</span> fortes doses, <span>cyclophosphamide</span></td><td><span>CI absolue</span> — anomalies fermeture tube neural, dysmorphie</td></tr>\n          <tr><td>Antiépileptiques</td><td><span><span class=\"nc-red nc-bold\">Valproate de sodium</span></span> (× 4-5), <span><span class=\"nc-red nc-bold\">carbamazépine</span></span>, <span>phénytoïne</span>, <span><span class=\"nc-red nc-bold\">phénobarbital</span></span>, <span>topiramate</span></td><td>Spina bifida (AFTN), cardiopathies (CIA, CIV), fentes faciales, hypospadias, retard psychomoteur</td></tr>\n          <tr><td><span>Rétinoïdes</span></td><td><span>Isotrétinoïne</span> (Roaccutane®), <span>acitrétine</span></td><td><span>CI</span> ·<span> 25-30 %</span> de malformations (SNC, oreille externe, cœur, squelette) ; contraception <span>2 ans</span> après arrêt acitrétine</td></tr>\n          <tr><td>Thymorégulateur</td><td><span>Lithium</span> (Téralithe®)</td><td>Malformations cardiaques (<span>Ebstein</span>, CA, CIV)<span> 4-8 %</span></td></tr>\n          <tr><td>Anti-vit K</td><td><span><span class=\"nc-red nc-bold\">Warfarine</span></span></td><td>Warfarin fetal syndrome <span>4-6 %</span> (dysmorphie, hypoplasie phalanges, anomalies cérébrales) ; relais <span>HBPM</span> en vue <span>grossesse</span></td></tr>\n          <tr><td><span>Immunosuppresseurs</span></td><td><span>Mycophénolate</span> (CellCept®)</td><td>FCS <span>50 %</span> ; anomalies oreille externe, fente labio-palatine, micrognathie</td></tr>\n          <tr><td>Prostaglandines</td><td><span>Misoprostol</span></td><td><span>Syndrome de Moebius</span>, rétrognathie, anomalies membres</td></tr>\n          <tr><td>Antithyroïdiens</td><td><span>Carbimazole</span></td><td>Aplasie cuir chevelu, atrésie choanes/œsophage, omphalocèle (remplacer par PTU au T1)</td></tr>\n          <tr><td>Virostatiques</td><td><span>Ribavirine</span>, <span>éfavirenz</span></td><td>Malformations faciales, membres, tube neural</td></tr>\n          <tr><td><strong><span><span class=\"nc-red nc-bold\">AINS</span></span></strong> (T2-T3)</td><td><span>Aspirine</span> (<span class=\"nc-green_bg\">sauf</span> faible dose &lt;<span> 100 mg</span>/j), <span>ibuprofène</span>, célécoxib</td><td><span>CI absolue ≥ 24 SA</span> ⚠️ : fermeture prématurée canal artériel, HTAP fœtale, oligoamnios, IR fœtale</td></tr>\n          <tr><td><strong><span>IEC</span> / <span>ARA2</span></strong> (T2-T3)</td><td>Enalapril, <span>losartan</span>…</td><td><span>CI T2-T3</span> : oligoamnios, IR fœtale et néonatale, anomalies voûte crânienne</td></tr>\n          <tr><td>Thalidomide / lénalidomide</td><td>—</td><td><span>CI absolue</span> ·<span> 30-40 %</span> phocomélie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Antibiotiques <span>à éviter</span> :</strong> <span class=\"nc-pink_bg\">tétracyclines</span> (coloration dentaire), aminosides (atteinte cochléovestibulaire), <span class=\"nc-pink_bg\">quinolones</span> (risque ostéoarticulaire). Aucun ATB n'est <em>formellement</em> CI — priorité au bénéfice maternel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription</em></p></div>"},{"i":"3918dbfe9fcf","n":27,"o":"27-32","u":"Diagnostic positif","t":"Médicaments et grossesse : connaître les conséquences des principaux médicaments à risque","q":"Que retenir concernant médicaments et grossesse : connaître les conséquences des principaux médicaments à risque ?","a":"<div class=\"notion-course\"><p>Les conséquences dépendent de la <strong>fenêtre d'exposition</strong> — c'est le piège QCM central de l'item.</p>\n      <table>\n        <thead><tr><th>Fenêtre</th><th>Terme</th><th>Conséquence type</th></tr></thead>\n        <tbody>\n          <tr><td>Péri-implantatoire</td><td>&lt; J12</td><td><strong><span class=\"nc-brown_bg\">Tout ou rien</span></strong> : <span class=\"nc-red nc-bold\">mort embryonnaire</span> <strong>ou</strong> <span class=\"nc-green nc-bold\">aucun effet</span> (sauf médicaments à demi-vie longue)</td></tr>\n          <tr><td>Embryonnaire (organogenèse)</td><td>J13 – J56 (T1)</td><td><strong>Période de sensibilité maximale aux <span class=\"nc-red_bg\">effets tératogènes</span></strong> → malformations structurelles</td></tr>\n          <tr><td>Fœtale</td><td>T2 et T3</td><td>Effets fœtotoxiques : <span><span class=\"nc-blue nc-bold\">atteinte de la croissance</span></span>, <span><span class=\"nc-blue nc-bold\">atteinte de la maturation histologique</span></span>, <span><span class=\"nc-blue nc-bold\">atteinte fonctionnelle des organes en place</span></span></td></tr>\n          <tr><td>Fin de <span>grossesse</span> / accouchement</td><td>T3 / per-partum</td><td><span class=\"nc-yellow_bg\">Effets néonataux</span> : <span>sevrage</span>, <span>détresse</span> respiratoire, hypoglycémie/<span>bradycardie</span> (BB-)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Exemples concrets par profil :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">AINS</span> T2-T3</span> : <span>fermeture prématurée canal artériel</span>, HTAP fœtale, IR néonatale, hémorragie néonatale — <span>CI absolue ≥ 24 SA</span> (exception : <span>aspirine</span> faible dose &lt;<span> 100 mg</span>/j pour prééclampsie/<span class=\"nc-green_bg nc-bold\">SAPL</span> jusqu'à 36 SA)</li>\n        <li><span>IEC / ARA2 T2-T3</span> : oligoamnios, IR fœtale et néonatale, anomalies voûte crânienne</li>\n        <li><span>Inducteurs enzymatiques</span> (<span><span class=\"nc-red nc-bold\">rifampicine</span></span>, <span><span class=\"nc-red nc-bold\">phénobarbital</span></span>, <span class=\"nc-red nc-bold\">carbamazépine</span>) : déficit en vitamine K néonatale → <span>supplémentation vitamine K orale</span> aux 2 derniers trimestres chez la mère + vitamine K1 chez nouveau-né</li>\n        <li><span><span class=\"nc-yellow_bg\">Psychotropes</span> T3</span> (<span>ISRS</span>, BZD, antipsychotiques, imipraminiques) : <span>détresse</span> respiratoire, <span>syndrome de sevrage néonatal</span> ou sérotoninergique, hypertonie, troubles succion (privilégier demi-vies courtes)</li>\n        <li><span>Bêtabloquants</span> (<span><span class=\"nc-red nc-bold\">propranolol</span></span>, <span><span class=\"nc-red nc-bold\">labétalol</span></span>) : <span>hypoglycémie + bradycardie</span> néonatale, RCIU si traitement prolongé — prévenir l'équipe pédiatrique</li>\n      </ul>\n      </div>"},{"i":"b574e4740936","n":27,"o":"27-33","u":"Prise en charge","t":"Vaccins et grossesse","q":"Que retenir concernant vaccins et grossesse ?","a":"<div class=\"notion-course\"><p>La règle générale : <strong>vaccins inactivés autorisés</strong> · <strong>vaccins vivants atténués théoriquement <span>contre-indiqués</span></strong>. Néanmoins, en cas de vaccination par inadvertance, <strong>pas d'interruption de <span>grossesse</span></strong> et <strong>pas d'inquiétude à transmettre à la patiente</strong>.</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Vaccins concernés</th><th>Pendant la grossesse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Vaccins vivants atténués</strong></td><td><span><span class=\"nc-red_bg\">ROR</span></span> (rougeole-oreillons-rubéole), <span><span class=\"nc-red_bg\">varicelle</span></span>, <span><span class=\"nc-red_bg\">BCG</span></span>, <span><span class=\"nc-red_bg\">poliomyélite</span></span> (oral), <span><span class=\"nc-red_bg\">rotavirus</span></span>, <span><span class=\"nc-orange_bg\">fièvre jaune</span></span></td><td><span>Théoriquement CI</span> · <span><span class=\"nc-orange_bg\">fièvre</span></span><span class=\"nc-orange_bg\"> jaune</span> : exception si zone endémique inévitable (bénéfice/risque favorable)</td></tr>\n          <tr><td><strong>Vaccins inactivés autorisés</strong></td><td><span>Grippe</span> (<span class=\"nc-green nc-bold\">recommandé</span> +++), <span>dTPa</span> <span class=\"nc-orange_bg\">coqueluche</span> (20-36 SA, protection nouveau-né), <span>COVID</span>, <span>VHA</span>, <span>VHB</span>, <span>méningo</span>, <span>pneumo</span>, <span>rage</span>, polio injectable</td><td>Autorisés à tous les trimestres</td></tr>\n          <tr><td>Risque fœtal théorique</td><td>Vaccins responsables d'une <span>réaction vaccinale importante avec fièvre</span> : <span class=\"nc-orange_bg\">diphtérie</span>, <span class=\"nc-orange_bg\">coqueluche</span>, <span><span class=\"nc-orange_bg\">fièvre</span></span><span class=\"nc-orange_bg\"> jaune</span></td><td><span>Surveillance</span> maternelle</td></tr>\n          <tr><td>Innocuité non prouvée</td><td>Choléra, VHA, typhoïde</td><td>À discuter selon séjour en zone à risque</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Vaccin antigrippal <span class=\"nc-green nc-bold\">recommandé</span> +++</strong> chez la femme enceinte, notamment chez les patientes à risque (<span>diabète</span>, <span>obésité</span>) — femmes enceintes plus à risque de complications pulmonaires et cardiovasculaires au T2-T3.</div>\n      <p>Délai après vaccin vivant atténué : contraception <span>≥ 1 mois</span> avant <span>grossesse</span>.</p><div class=\"callout callout-info\"><b>Actualisation et précisions</b><ul><li>Vaccination maternelle contre le VRS : possibilité entre 32 et 36 SA selon campagne et recommandations, en alternative à la prévention néonatale appropriée ; coordonner le choix et les situations particulières. Vérifier le calendrier vaccinal de l’année.</li></ul></div></div>"},{"i":"5c526fa8f327","n":27,"o":"27-34","u":"Physiopathologie","t":"Tabac et grossesse : connaître la physiopathologie","q":"Que retenir concernant tabac et grossesse : connaître la physiopathologie ?","a":"<div class=\"notion-course\"><p>La fumée de <span>tabac</span> contient &gt; <span>4000 produits toxiques</span>. L'atteinte fœtale est <strong>dose-dépendante</strong> et liée à l'interaction de facteurs sociodémographiques, épidémiologiques et génétiques.</p>\n      <table>\n        <thead><tr><th><span>Toxique</span></th><th>Mécanisme physiopathologique</th></tr></thead>\n        <tbody>\n          <tr><td>Nicotine</td><td>Vasoconstriction utéro-placentaire → <span>hypoperfusion placentaire</span> chronique</td></tr>\n          <tr><td>Monoxyde de carbone (CO)</td><td>Liaison à l'Hb (HbCO) → <span>diminution du transport d'O₂</span> au fœtus → hypoxie chronique</td></tr>\n          <tr><td>Métabolites cytochrome P450 / glutathione S-transférase</td><td>Polymorphisme <span>génétique</span> influence la sensibilité — chez les mères de petits poids, davantage de polymorphismes de l'un ou l'autre de ces <span>2 g</span>ènes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Effet majoré au 3ᵉ trimestre :</strong> les patientes sevrées aux T1-T2 ont des nouveau-nés au poids quasi normal ; l'effet sur la croissance est surtout au T3.</div></div>"},{"i":"59233d18749b","n":27,"o":"27-35","u":"Diagnostic","t":"Connaître les conséquences d'une intoxication tabagique pendant la grossesse","q":"Que retenir concernant les conséquences d'une intoxication tabagique pendant la grossesse ?","a":"<div class=\"notion-course\"><p>Dans la plupart des pays européens, le <span>tabagisme</span> en cours de <span>grossesse</span> est <strong><span class=\"nc-red nc-bold\">la principale cause évitable de </span><span><span class=\"nc-red nc-bold\">morbidité</span></span><span class=\"nc-red nc-bold\"> périnatale</span></strong>. <span>~17 %</span> des femmes enceintes continuent à fumer jusqu'à la fin de la grossesse.</p>\n      <table>\n        <thead><tr><th>Période</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td>Fertilité</td><td><span class=\"nc-red nc-bold\">Stérilité</span> (RR&gt;2 : 2 × plus de cycles nécessaires)</td></tr>\n          <tr><td>T1</td><td><strong>1ʳᵉ cause de <span><span class=\"nc-red_bg\">GEU</span></span></strong> (RR &gt; 2) · <span>FCS</span> dose-dépendantes (RR ≈ 2) · effets tératogènes réels mais faibles</td></tr>\n          <tr><td>T2-T3</td><td><span><span class=\"nc-red_bg\">RCIU</span></span> dose-dépendant (apparaît préférentiellement 2ᵉ moitié de <span>grossesse</span>) · <span>prématurité</span> (faible mais significatif) · <span><span class=\"nc-red_bg\">placenta praevia</span></span> (+<span> 30 %</span>) · <span>HRP (× 2)</span> · césarienne ↑ si &gt; <span>20 cig/j</span></td></tr>\n          <tr><td>Néonatal</td><td><strong><span class=\"nc-red_bg\">Mort inattendue/subite du nourrisson</span></strong> (× 2 même en environnement non fumeur ⭐) · <span class=\"nc-orange_bg\">infections respiratoires basses</span> + otites (+<span> 50 %</span>) · <span><span class=\"nc-orange_bg\">obésité</span></span><span class=\"nc-orange_bg\"> de l'adolescent</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Effet-dose démontré</strong> entre <span>tabagisme</span> maternel et atteinte fœtale. Même le <span>tabagisme passif</span> a un effet significatif sur le <span class=\"nc-red_bg\">RCIU</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span>tabac</span></em></p></div>"},{"i":"b5c2455671e2","n":27,"o":"27-36","u":"Prise en charge","t":"Connaître la prise en charge des femmes enceintes fumeuses","q":"Que retenir concernant la prise en charge des femmes enceintes fumeuses ?","a":"<div class=\"notion-course\"><p>Environ <span>50 %</span> des femmes fumeuses arrêtent spontanément sans aide médicamenteuse. Le <span>sevrage</span> est bénéfique <strong>à tous les stades de la <span>grossesse</span></strong>.</p>\n      <table>\n        <thead><tr><th>Type</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Médicamenteuse</td><td><span>Substituts nicotiniques</span> autorisés <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span> (en cas de dépendance pharmacologique) ; <span>varénicline et bupropion CI</span></td></tr>\n          <tr><td>Évaluation objective</td><td><span>Analyseur de CO expiré</span> — mesure objective remise à la patiente</td></tr>\n          <tr><td>Non médicamenteuse</td><td>Conseil minimal de <span>sevrage</span> · intervention brève (questions ouvertes) · <strong>entretien motivationnel</strong> · TCC · consultation psychologique · consultation addictologie si polyconsommation</td></tr>\n          <tr><td>Prévention rechutes</td><td>~2/3 des patientes sevrées rechutent à<span> 6 mois</span> et &gt;3/<span>4 à 1 an</span> · anticipation avec tabacologue en cours de <span>grossesse</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span>tabac</span></em></p></div>"},{"i":"286d4fff04b9","n":27,"o":"27-37","u":"Diagnostic","t":"Connaître les conséquences d'une alcoolisation pendant la grossesse : syndrome d'alcoolisation fœtale (SAF) et ensemble des troubles causés par l'alcoolisation fœtale (ETCAF)","q":"Que retenir concernant les conséquences d'une alcoolisation pendant la grossesse : syndrome d'alcoolisation fœtale (SAF) et ensemble des troubles causés par l'alcoolisation fœtale (ETCAF) ?","a":"<div class=\"notion-course\"><p>Le <span>SAF</span> est la <strong>principale complication d'une alcoolisation chronique <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span></strong>. Fréquence en France : <span>1 à 2/1000</span> sous sa forme complète. <strong>1ʳᵉ cause évitable de retard mental d'origine non <span>génétique</span>.</strong></p>\n      <p><strong>Le SAF associe 4 éléments à divers degrés :</strong></p>\n      <table>\n        <thead><tr><th>Élément</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Retard de croissance</td><td>Modéré dans <span>80 %</span> des cas, <strong><span class=\"nc-yellow_bg\">harmonieux</span></strong> (<span class=\"nc-blue_bg\">os longs</span> + périmètre abdo + PC — toxicité directe sur les cellules neurologiques)</td></tr>\n          <tr><td><span>Dysmorphie craniofaciale</span></td><td><span class=\"nc-blue_bg\">Hypertrichose</span> + <span class=\"nc-blue_bg\">synophris</span> (monosourcil), <span><span class=\"nc-yellow_bg\">fentes palpébrales étroites</span></span>, ptosis, <span class=\"nc-yellow_bg\">épicanthus</span>, <span class=\"nc-yellow_bg\">hypertélorisme</span>, oreilles basses mal ourlées, <span class=\"nc-green_bg\">ensellure nasale prononcée</span>, nez court, <span><span class=\"nc-red nc-bold\">allongement</span> et effacement du philtrum</span> (« <span class=\"nc-red nc-bold\">en verre de montre</span> »), <span>lèvre supérieure mince</span>, menton effacé, rétrognathisme</td></tr>\n          <tr><td>Retard des acquisitions</td><td><span class=\"nc-orange_bg\">Troubles cognitifs et comportementaux</span>, retard mental dans formes sévères → handicap</td></tr>\n          <tr><td>Malformations</td><td><span>10-30 %</span> des formes sévères : <span class=\"nc-red_bg\">neurologiques</span> (<span>spina bifida</span>, agénésie corps calleux, hydrocéphalie), <span class=\"nc-red_bg\">cardiaques</span> (CIA, CIV), <span class=\"nc-red_bg\">squelettiques</span> (scoliose), fentes labiopalatines</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"nc-green_bg\">ETCAF</span></strong> (<span class=\"nc-green_bg\">ensemble des troubles causés par l'alcoolisation fœtale</span>) : remplace SAF quand les troubles surviennent <strong>sans retard de croissance ni dysmorphie</strong>, lorsque l'<span class=\"nc-green nc-bold\">alcoolisation est plus modérée</span>. Fréquence ~ <span>5/1000</span>. Manifestations : baisse du QI, retard langage/écriture, agressivité, <span class=\"nc-blue_bg\">hyperactivité</span>, troubles de la motricité fine.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span>alcool</span></em></p></div>"},{"i":"56ee8d5df01e","n":27,"o":"27-38","u":"Physiopathologie","t":"Alcool et grossesse : mécanisme – relation dose-effet","q":"Que retenir concernant alcool et grossesse : mécanisme – relation dose-effet ?","a":"<div class=\"notion-course\"><p>L'atteinte fœtale est liée au <strong>passage rapide de l'<span>alcool</span> à travers le placenta</strong>. Le taux d'<span>alcool</span> fœtal est <strong>quasiment identique</strong> à celui de la mère.</p>\n      <table>\n        <thead><tr><th>Niveau de consommation</th><th>Conséquences fœtales</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Consommation importante</span> (&gt; 2 <span>VS</span>/j)</td><td>Retentissement fœtal documenté : <span>risque de SAF</span></td></tr>\n          <tr><td>Consommation occasionnelle légère/modérée (1-2 <span>VS</span>/j)</td><td><span class=\"nc-green nc-bold\">Pas de syndrome dysmorphique ou malformatif</span> · <span class=\"nc-blue nc-bold\">troubles comportementaux</span>, affectifs et anxieux possibles</td></tr>\n          <tr><td>Binge drinking début de <span>grossesse</span> (≥ <span>4 verres</span> en 1 fois)</td><td><span class=\"nc-green nc-bold\">Pas d'impact démontré si épisode isolé</span> (situation fréquente, <span>grossesse</span> encore inconnue)</td></tr>\n          <tr><td>Binge drinking T2-T3</td><td>Risques de <span><span class=\"nc-red nc-bold\">troubles cognitifs</span></span> par altération de la migration neuronale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Mécanisme central :</strong> atteinte neurologique = arrêts/déviations de la <span>migration neuronale</span> (fin T1 → naissance). <strong><span class=\"nc-green_bg\">Recommandation</span> officielle :</strong> <span><span class=\"nc-green_bg nc-bold\">zéro alcool</span></span> <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span> — <strong>absence d'effet seuil démontré</strong>.</div>\n      <p><span class=\"nc-green_bg\">Rassurer/</span><span class=\"nc-green_bg nc-bold\">déculpabiliser</span> une patiente présentant une alcoolisation légère ou un binge drinking isolé <span class=\"nc-green_bg\">en début de </span><span><span class=\"nc-green_bg\">grossesse</span></span> — l'objectif est de maintenir le lien médecin-patiente, pas d'aggraver la culpabilité.</p></div>"},{"i":"82d09c1da7a4","n":27,"o":"27-39","u":"Suivi et/ou pronostic","t":"Alcool et grossesse : dépistage","q":"Que retenir concernant alcool et grossesse : dépistage ?","a":"<div class=\"notion-course\"><p>~ <span>3 %</span> des femmes enceintes consomment de l'<span>alcool</span> de façon épisodique ou régulière en sachant être enceintes. La <span>grossesse</span> est une occasion unique de dépister.</p>\n      <table>\n        <thead><tr><th>Outil</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Interrogatoire</strong> (clé du <span>dépistage</span>)</td><td>À chaque consultation prénatale</td></tr>\n          <tr><td>Auto-questionnaire <span><span class=\"nc-yellow_bg\">T-ACE</span></span></td><td>Meilleure sensibilité que l'interrogatoire seul. <span>Score</span> ≥ <span>2 points</span> = positif. <strong>T</strong>olerance (<span>≥ 3</span> verres = 2 pts), <strong>A</strong>nnoyance, <strong>C</strong>ut-down, <strong>E</strong>ye-opener (1 pt chacun si oui)</td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Dosages biologiques</span></td><td>Sensibilité ~<span>50 %</span> pour alcoolisation excessive (<span>≥ 2</span> verres/j) — peu performants</td></tr>\n          <tr><td>CAT en cas de consommation</td><td>Cadre exempt de jugement · maintenir le lien · aide au <span>sevrage</span> par <span>acamprosate (Aotal®)</span> ; cure, foyer thérapeutique, <span>hospitalisation</span> ; <span>surveillance</span> échographique ; supplémentation B1-B6 si carence <span>folates</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mesures associées :</strong> rechercher autres vulnérabilités (drogues, violence conjugale), PEC sociale, orthophonie/scolarité adaptée pour dépister précocement ETCAF.</p></div>"},{"i":"a583f9585aa9","n":27,"o":"27-40","u":"Physiopathologie","t":"Addictologie et grossesse : produits en cause et leurs principaux effets","q":"Que retenir concernant addictologie et grossesse : produits en cause et leurs principaux effets ?","a":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Produit</th><th>Passage</th><th>Effets fœtaux/néonataux</th></tr></thead>\n        <tbody>\n          <tr><td><span>Cannabis (THC)</span></td><td>Liposoluble → barrière placentaire en quelques min · concentration ↑ × 8 dans le lait maternel</td><td><span class=\"nc-red_bg\">RCIU</span> par hypoperfusion placentaire ; consommation régulière (<span>≥ 6</span>×/sem) : prématurité, ↓ poids naissance, <span><span class=\"nc-orange_bg\">syndrome de sevrage néonatal</span></span><span class=\"nc-orange_bg\"> modéré</span> (trémulations) régressif</td></tr>\n          <tr><td><span>Cocaïne</span></td><td>Barrière placentaire + lait maternel</td><td><span><span class=\"nc-orange_bg\">HTA</span></span> + vasoconstriction → <span>FCS, prématurité, RCIU, <span class=\"nc-red_bg\">hydramnios</span>, RPM, HRP ⭐ (RR 4-5)</span> · syndrome d'imprégnation néonatal (hypertonie, trémulations, <span>convulsions</span>) · entérocolites ulcéronécrosantes, <span>infarctus</span> mésentériques</td></tr>\n          <tr><td><span>Opiacés / héroïne</span></td><td>Barrière placentaire + lait maternel</td><td><span>Grossesse</span> à haut risque : <strong>manque maternel</strong> → souffrance fœtale, <span class=\"nc-red nc-bold\">MFIU possible</span> ; FCS, prématurité, <span class=\"nc-orange_bg\">RCIU</span> ; <span>syndrome de sevrage néonatal</span><span> 60 %</span> (<span>J0</span> à J10, durée 1-3 sem)</td></tr>\n          <tr><td>Benzodiazépines</td><td>Barrière placentaire</td><td>Syndrome de <span>sevrage</span> néonatal plus tardif/long, hypotonie, floppy baby</td></tr>\n          <tr><td>Amphétamines / ecstasy / LSD</td><td>—</td><td>Risques mal connus (usage récréatif souvent interrompu à la découverte de <span>grossesse</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Héroïne et <span>opiacés</span> ne sont pas tératogènes</strong> — la gravité vient du manque maternel, des conditions de vie, et du <span>syndrome de sevrage néonatal</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 78 — Addiction aux drogues · 79 — Addiction comportementale</em></p></div>"},{"i":"824d2d39d5a7","n":27,"o":"27-41","u":"Diagnostic","t":"Repérage des conduites addictives et des facteurs de risques associés au cours de la grossesse","q":"Que retenir concernant repérage des conduites addictives et des facteurs de risques associés au cours de la grossesse ?","a":"<div class=\"notion-course\"><p>Le repérage des conduites addictives s'effectue par l'interrogatoire systématique à chaque consultation prénatale, complété par la recherche de <span>facteurs de risque</span> associés.</p>\n      <ul>\n        <li><strong>Interrogatoire</strong> systématique à chaque consultation prénatale : <span>tabac</span>, <span>alcool</span>, cannabis, <span>opiacés</span>, BZD, médicaments détournés</li>\n        <li><strong>Questionnaires validés</strong> : <span><span class=\"nc-yellow_bg\">T-ACE</span></span> (<span>alcool</span>), aide au repérage de la dépendance et du mésusage</li>\n        <li><strong>FR associés à rechercher</strong> : précarité, IST, troubles psychiatriques, antécédents traumatiques, polyconsommations, violences conjugales</li>\n        <li><strong>Mesure objective</strong> : analyseur de CO (<span>tabac</span>), <span class=\"nc-blue_bg\">dosages biologiques</span> (<span>alcool</span>, peu sensibles), <span>dépistage</span> urinaire (cannabis, <span>opiacés</span>) si pertinent</li>\n        <li><strong>Accompagnement multidisciplinaire</strong> : sage-femme + addictologue + psychiatre + travailleur social + PMI</li>\n      </ul>\n      <p>Ressources : <span>CRAT</span> (lecrat.fr) et <span>CRPV</span> pour l'évaluation des risques <span>médicamenteux</span> <span class=\"nc-green_bg\">pendant la </span><span><span class=\"nc-green_bg\">grossesse</span></span>.</p></div>"},{"i":"d505618232d6","n":27,"o":"27-42","u":"Prise en charge","t":"Addictologie et grossesse : aspects essentiels de la prise en charge obstétricale et addictologique","q":"Que retenir concernant addictologie et grossesse : aspects essentiels de la prise en charge obstétricale et addictologique ?","a":"<div class=\"notion-course\"><p>Le principe central : <strong>préserver le fœtus de la souffrance du manque</strong> sans imposer un <span>sevrage</span> brutal qui aggraverait le <span>pronostic</span>.</p>\n      <table>\n        <thead><tr><th>Conduite</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span>Sevrage opiacés non recommandé ❌</span></td><td><strong>Déconseillé au T1</strong> (risque FCS) · <strong>déconseillé au T3</strong> (risque <span class=\"nc-orange_bg\">accouchement prématuré</span>) · envisageable au T2 si patiente insistante (long, prudent, risque élevé de rechute)</td></tr>\n          <tr><td>Traitement de substitution <span>opiacés</span> ✅</td><td><span><span class=\"nc-pink_bg\">Méthadone</span></span> (sirop/gélule) <strong>ou</strong> <span><span class=\"nc-pink_bg\">buprénorphine</span></span> (sublingual) — association sans AMM ; doses efficaces pour éviter le manque (souvent augmentées en fin de <span>grossesse</span>)</td></tr>\n          <tr><td>Pluridisciplinarité</td><td>Sage-femme + obstétricien + addictologue + psychiatre + travailleur social ; <span>surveillance</span> échographique renforcée</td></tr>\n          <tr><td>Planification accouchement</td><td>Maternité de niveau adapté, équipe addicto informée à l'avance</td></tr>\n          <tr><td>Médicaments <span>à éviter</span> péri-partum</td><td>BZD et <span>opiacés</span> à courte durée d'action (<span>sevrage</span> néonatal)</td></tr>\n          <tr><td><span>Allaitement</span></td><td>Compatible avec <span><span class=\"nc-pink_bg\">méthadone</span></span>/<span><span class=\"nc-pink_bg\">buprénorphine</span></span> à dose stable (sauf <span>VIH</span> non contrôlé ou cocaïne)</td></tr>\n        </tbody>\n      </table></div>"},{"i":"d037eb5d1222","n":27,"o":"27-43","u":"Prise en charge","t":"Addictologie et grossesse : accueil de l'enfant","q":"Que retenir concernant addictologie et grossesse : accueil de l'enfant ?","a":"<div class=\"notion-course\"><p>L'accueil du nouveau-né de mère addicte impose une <span>surveillance</span> néonatale rigoureuse du <strong>syndrome de <span>sevrage</span></strong>.</p>\n      <table>\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Évaluation</td><td><span>Score de Finnegan</span> (ou Lipsitz) toutes les <span>4 h</span> dès la naissance, jusqu'à 3-10 j</td></tr>\n          <tr><td>Survenue</td><td>Délai &lt; 3 j post-naissance (jusqu'à 1-10 j), durée <span>1-3 semaines</span> · fréquence <span>60 %</span> chez nouveau-nés exposés aux <span>opiacés</span>/TSO</td></tr>\n          <tr><td>Symptômes</td><td>Trémulations, hypertonie, hyperréflexie, <span class=\"nc-blue_bg\">troubles du sommeil</span>, pleurs incoercibles, troubles de la succion, <span>hyperthermie</span>, mauvaise courbe pondérale, troubles digestifs</td></tr>\n          <tr><td>Traitement</td><td>Si <strong><span>score</span> &gt; <span <span=\"\">&gt;8</span> lors de 3 évaluations consécutives</strong> : <span><span class=\"nc-pink nc-bold\">chlorhydrate</span> ou <span class=\"nc-pink nc-bold\">sulfate de morphine</span></span> PO (morphinique de remplacement)</td></tr>\n          <tr><td><span>Allaitement</span></td><td>Encouragé si TSO stable (<span><span class=\"nc-pink_bg\">méthadone</span></span>, <span><span class=\"nc-pink_bg\">buprénorphine</span></span>) · CI <span>VIH</span>, cocaïne active</td></tr>\n          <tr><td><span>Suivi</span></td><td>Pédiatrique au long cours · signalement PMI/ASE selon contexte social</td></tr>\n        </tbody>\n      </table>\n      <p>Sévérité du <span>sevrage</span> non corrélée à la posologie du TSO, mais majorée par les co-prises (BZD → sevrage plus tardif et plus long).</p></div>"},{"i":"87a2274aca6f","n":27,"o":"27-44","u":"Diagnostic","t":"Addictologie et grossesse : conséquences à long terme","q":"Que retenir concernant addictologie et grossesse : conséquences à long terme ?","a":"<div class=\"notion-course\"><ul>\n        <li><span>Troubles neurodéveloppementaux</span> : cognition, attention, comportement</li>\n        <li><span>Troubles psychiatriques</span> à l'adolescence et à l'âge adulte</li>\n        <li><span>Vulnérabilité aux addictions</span> chez l'enfant et l'adolescent (transmission psycho-socio-environnementale)</li>\n        <li><span>Troubles de l'attachement</span> et parentalité fragile</li>\n        <li><span class=\"nc-red_bg\">Mort inattendue/subite du nourrisson</span> (<span>tabagisme</span>, polyconsommations)</li>\n        <li>Difficultés scolaires, troubles d'apprentissage (cannabis), <span class=\"nc-blue_bg\">hyperactivité</span>, <span class=\"nc-blue_bg\">troubles du sommeil</span></li>\n      </ul>\n      <p>Le repérage précoce et la mise en place d'un <span>suivi</span> pédiatrique et orthophonique adapté limite le handicap social et fonctionnel à long terme.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span>tabac</span> · 76 — Addiction à l'<span>alcool</span> · 78 — Addiction aux drogues</em></p></div>"},{"i":"d14fd2beaf05","n":27,"o":"27-45","u":"Physiopathologie","t":"Connaître les mécanismes d'action de l'irradiation sur le fœtus","q":"Que retenir concernant les mécanismes d'action de l'irradiation sur le fœtus ?","a":"<div class=\"notion-course\"><p>L'<span>irradiation</span> fœtale se mesure en <strong><span class=\"nc-pink nc-bold\">milligrays</span> (<span class=\"nc-pink nc-bold\">mGy</span>)</strong>. Deux mécanismes d'action s'opposent : <strong>effets déterministes</strong> (à seuil, mort cellulaire) et <strong>effets stochastiques</strong> (sans seuil, lésions ADN).</p>\n      <table>\n        <thead><tr><th>Mécanisme</th><th>Effets</th><th>Période sensible</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Effets déterministes</strong> (mort cellulaire)</td><td>Dose seuil <span><span class=\"nc-pink nc-bold\">100-200 mGy</span></span> ⭐⭐⭐ — pas de répercussions en-dessous</td><td>SNC le + touché : sensibilité <strong><span class=\"nc-pink nc-bold\">10-27 SA</span></strong></td></tr>\n          <tr><td>Multiplication neuronale</td><td><span class=\"nc-red_bg\">10-17 SA</span> : <span><span class=\"nc-red nc-bold\">diminution sévère du QI</span> (- 30)</span>,<span> 40 %</span> d'arriération mentale (QI &lt; 25) à partir de <span <span=\"\">&gt;1000</span> mGy</td><td>Conséquences : <span class=\"nc-orange_bg\">microcéphalie</span>, <span class=\"nc-orange_bg\">RCIU</span>, <span class=\"nc-orange_bg\">cataracte</span>, ↓ QI</td></tr>\n          <tr><td>Migration neuronale</td><td><span class=\"nc-green_bg\">18-27 SA</span> : <span class=\"nc-green nc-bold\">diminution du QI moins importante</span></td><td><span class=\"nc-yellow_bg\">Relation dose-effet</span> à partir de <span <span=\"\">&gt;<span class=\"nc-pink nc-bold\">500</span></span><span class=\"nc-pink nc-bold\"> mGy</span></td></tr>\n          <tr><td><strong>Effets stochastiques</strong> (lésions ADN)</td><td><strong>Pas de dose seuil ❌</strong> · <span class=\"nc-yellow_bg\">Relation dose-effet</span> ✅ : <span>↑ risque leucémie/cancer × 1,4</span> (<span>40 %</span>)</td><td>Risque brut leucémie/cancer enfant :<span> 0,2-0,3 %</span> →<span> 0,3-0,4 %</span> après <span>irradiation</span> fœtale (reste faible)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Autres organes :</strong> mieux préservés ; à doses très élevées : <span class=\"nc-orange_bg\">RCIU</span>, voire décès in utero (curiethérapie utérine pour cancer du col par exemple).</div></div>"},{"i":"ae7cc76a1b53","n":27,"o":"27-46","u":"Prise en charge","t":"Irradiation et grossesse : en pratique, ce que l'on peut retenir","q":"Que retenir concernant irradiation et grossesse : en pratique, ce que l'on peut retenir ?","a":"<div class=\"notion-course\"><p>Le principe directeur : <strong>un examen radiologique justifié n'est jamais une indication d'IMG</strong>. Le « principe de précaution » historique (inquiéter la femme, proposer l'IMG probabiliste) doit être <strong>définitivement abandonné</strong>.</p>\n      <p><strong>Doses fœtales reçues par examen (mGy, moyenne / max) :</strong></p>\n      <table>\n        <thead><tr><th>Examen</th><th>Dose moy</th><th>Dose max</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr><td><span>RP</span>, RX crâne, RX rachis dorsal, RX membres</td><td>&lt; 0,01</td><td>&lt; 0,01</td><td>Utérus hors faisceau · rassurer +++</td></tr>\n          <tr><td>RX abdomen</td><td>1,4</td><td>4,2</td><td>—</td></tr>\n          <tr><td>RX rachis lombaire</td><td>1,7</td><td>10</td><td>—</td></tr>\n          <tr><td><span>TDM</span> thorax</td><td>0,06</td><td>0,96</td><td>Très faible (utérus hors faisceau)</td></tr>\n          <tr><td><span>TDM</span> tête</td><td>0,005</td><td>0,005</td><td>Négligeable</td></tr>\n          <tr><td><span>TDM</span> abdomen</td><td>8,0</td><td>49</td><td>Utérus dans le faisceau</td></tr>\n          <tr><td><span>TDM</span> bassin</td><td>25</td><td>79</td><td>Dose la + élevée des examens diagnostiques</td></tr>\n          <tr><td>Lavement baryté</td><td>6,8</td><td>24</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Aucun examen radiologique diagnostique standard ne dépasse <span <span=\"\">&gt;100</span> mGy</strong> — la limite déterministe. Seules les <span>situations exceptionnelles</span> (scopie prolongée, curiethérapie, <span>radiothérapie</span> pelvienne) peuvent y conduire.</div>\n      <p><strong>Principes pratiques (ALARA) :</strong></p>\n      <ul>\n        <li>Demander systématiquement à toute femme en âge de procréer si elle est enceinte avant un examen radiologique</li>\n        <li>Privilégier les <span>examens non irradiants</span> : <strong><span>échographie</span></strong>, <strong><span>IRM</span></strong> sans gadolinium (T1)</li>\n        <li><span>Tablier de plomb</span> sur l'abdomen pour limiter la dose à l'utérus</li>\n        <li>Limiter le nombre de clichés et le temps de scopie au strict nécessaire</li>\n        <li><strong>Ne pas contre-indiquer un examen radiographique uniquement pour la <span>grossesse</span></strong> : balance bénéfice/risque souvent favorable</li>\n        <li><span>Iode 131 radioactif CI absolue</span> ⚠️ (détruit thyroïde fœtale)</li>\n        <li><span>Radiothérapie CI</span> (doses très élevées) ; en cas d'exposition involontaire → calcul dose-gonades avec IRSN, avis CPDPN</li>\n      </ul>\n      <p><strong>Médecine du travail :</strong> exposition de l'enfant à naître <strong>&lt; 1 mSv</strong> entre la déclaration et l'accouchement. Femme allaitante : pas de poste à risque de contamination interne.</p>\n      <p><strong>Découverte de <span>grossesse</span> après examen :</strong> si utérus hors faisceau (crâne, thorax, membres) → rassurer ; si utérus dans le faisceau (UIV, hystéro, <span>TDM</span> pelvien) → en standard, rassurer (dose exceptionnellement &gt; <span <span=\"\">&gt;100</span> mGy) ; si examen inhabituel → avis service compétent (radiologue, IRSN).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 333 — Situations sanitaires exceptionnelles</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181b690edf58d3ccb8168?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Prévention de routine ou exposition/symptôme ?","detail":"<ul><li>Terme, statut immunitaire et mécanisme de transmission.</li></ul>","branches":[{"label":"Fièvre / exposition / test nouveau","to":"avis"},{"label":"Prévention","to":"prevenir"}]},{"id":"avis","kind":"decision","label":"Évaluation ciblée et datation","detail":"<ul><li>Interpréter sérologie/PCR avec un expert ; ne pas conclure sur une IgM isolée.</li></ul>","branches":[{"label":"Infection confirmée","to":"specialiste"},{"label":"Non confirmée","to":"prevenir"}]},{"id":"specialiste","kind":"finish","label":"Prise en charge spécifique et conseil","detail":"<ul><li>Risque variable selon agent et terme ; CPDPN si indiqué, bilan fœtal adapté.</li></ul>","branches":[]},{"id":"prevenir","kind":"decision","label":"Hygiène, vaccination et dépistages adaptés","detail":"<ul><li>Toxoplasmose, listériose, CMV, rubéole/varicelle, grippe et vaccins.</li></ul>","branches":[{"label":"Préparer la naissance","to":"perinatal"}]},{"id":"perinatal","kind":"decision","label":"Prévention périnatale selon agent","detail":"<ul><li>SGB, VHB, VIH et herpès : mesures maternelles et néonatales spécifiques.</li></ul>","branches":[{"label":"Symptômes vaginaux","to":"vaginose"},{"label":"Plan établi","to":"suivi"}]},{"id":"vaginose","kind":"finish","label":"Diagnostiquer et traiter si indiqué","detail":"<ul><li>Ne pas confondre vaginose, portage SGB et infection haute.</li></ul>","branches":[]},{"id":"suivi","kind":"finish","label":"Transmettre le plan à la maternité/pédiatrie","detail":"<ul><li>Prévention et surveillance sans examens universels non indiqués.</li></ul>","branches":[]}]}};
